#include <stdlib.h>
#include <time.h>
#include <assert.h>

typedef struct {
    char mac_address[18];  // e.g., "00:A0:C9:14:C8:29"
    unsigned int ip_address;  // Assuming IP addresses are in dotted decimal notation
    unsigned short port_number;
} NicpConfigStructure;

// Function to generate a random MAC address
void getRandomMacAddress(char *mac) {
    srand((unsigned int) time(NULL));
    for (int i = 0; i < 6; ++i) {
        mac[3*i] = rand() % 256;
        mac[3*i + 1] = ':';
    }
    mac[17] = '\0'; // null terminate the string
}

// Function to generate a random IP address within a range (e.g., 192.168.0.1 to 192.168.255.254)
unsigned int getRandomIpAddress() {
    unsigned int ip = (rand() % 3 + 64) << 24; // first octet in range 192-223
    ip |= rand() % 256 << 16; // second octet 0-255
    ip |= rand() % 256 << 8; // third octet 0-255
    ip |= 2 + (rand() % 254); // fourth octet in range 2-255
    return ip;
}

// Function to generate a random port number within a specified range
unsigned short getRandomPortNumber(int min, int max) {
    assert(max <= 65535 && min >= 1024); // ensure the bounds are within valid port numbers
    return rand() % (max - min + 1) + min;
}

NicpConfigStructure* initializeArrayOfNicpConfigs(int size, int minPortNumber, int maxPortNumber) {
    srand((unsigned int) time(NULL)); // Seed the random number generator with current time

    NicpConfigStructure* nicpConfigs = malloc(size * sizeof(NicpConfigStructure));
    if (nicpConfigs == NULL) return NULL;  // handle memory allocation error gracefully

    for (int i = 0; i < size; ++i) {
        getRandomMacAddress(nicpConfigs[i].mac_address);

        unsigned int ip;
        do {
            ip = getRandomIpAddress();
        } while (ip != nicpConfigs[i-1].ip_address && i > 0); // ensure unique IP addresses

        nicpConfigs[i].ip_address = ip;
        nicpConfigs[i].port_number = getRandomPortNumber(minPortNumber, maxPortNumber);
    }

    return nicpConfigs;
}
