```c
#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>
#include <event2/event.h>
#include <event2/dns.h>

void on_resolve(int result, char type, int count, int ttl, void *addrs, void *arg) {
    if (result != DNS_ERR_OK) {
        printf("Error during DNS resolution: %s\n", evdns_err_to_string(result));
        return;
    }

    char addrstr[128];
    struct in_addr *inaddr = addrs;
    const char *base = (type == DNS_IPv6_A) ? "inet6" : "inet";
    evutil_inet_ntop(AF_INET, &inaddr->s_addr, addrstr, sizeof(addrstr));
    printf("Resolved: %s\n", addrstr);
}

void resolve_hostname(struct event_base *base, const char *hostname) {
    int r;
    struct evdns_request *req;

    req = evdns_getaddrinfo(base, hostname, NULL, &on_resolve, NULL);
    if (req == NULL) {
        printf("Error creating DNS request\n");
        return;
    }

    r = event_base_dispatch(base);
    evdns_request_free(req);
}

int main() {
    struct event_base *base;
    base = event_base_new();
    if (!base) {
        printf("Couldn't create an event_base\n");
        return 1;
    }

    const char *hostname = "www.example.com";
    resolve_hostname(base, hostname);

    event_base_free(base);
    return 0;
}
```
This program will create an `event_base` to handle DNS requests and then use the `evdns_getaddrinfo()` function to perform a DNS resolution for a given hostname. The result of this operation is handled in the `on_resolve()` callback, which prints out either the resolved IP address or an error message if the request failed.

