EVP_CIPHER* cipherSelector(const char* cipher) {
    if (!strcmp(cipher, "EDE")) return EVP_des_ede();
    else if (!strcmp(cipher, "ECB")) return EVP_des_ecb();
    else if (!strcmp(cipher, "EDE3")) return EVP_des_ede3();
    else if (!strcmp(cipher, "CFB")) return EVP_des_cfb8();
    else return NULL;
}

bool jsonValidator(const char* json) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        printf("JSON Error: on line %d: %s\n", error.line, error.text);
        return false;
    }

    json_t *access_token = json_object_get(root, "access_token");
    if(!json_is_string(access_token)) {
        printf("Missing or invalid access_token\n");
        return false;
    }

    json_t *expires_in = json_object_get(root, "expires_in");
    if(!json_is_integer(expires_in) || json_integer_value(expires_in) <= 0) {
        printf("Missing or invalid expires_in\n");
        return false;
    }

    json_t *token_type = json_object_get(root, "token_type");
    if(!json_is_string(token_type) || strcmp(json_string_value(token_type), "Bearer")) {
        printf("Missing or invalid token_type\n");
        return false;
    }

    json_t *refresh_token = json_object_get(root, "refresh_token");
    if(!json_is_string(refresh_token)) {
        printf("Missing refresh_token\n");
        return false;
    }

    json_decref(root);
    return true;
}

bool cryptoAndJsonValidator(const char* cipher, const char* json) {
    EVP_CIPHER *chosen = cipherSelector(cipher);
    if(!chosen) {
        printf("Invalid or unsupported cipher\n");
        return false;
    }

