#include <semaphore.h>

typedef struct Queue {
    int front, rear, size;
    unsigned capacity;
    int* array;

    sem_t mutex;
    sem_t full;
    sem_t empty;
} Queue;

Queue* createQueue(unsigned capacity) {
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    queue->capacity = capacity;
    queue->front = 0;
    queue->size = 0;
    queue->rear = capacity - 1;

    queue->array = (int*) malloc(queue->capacity * sizeof(int));

    sem_init(&queue->mutex, 0, 1);
    sem_init(&queue->full, 0, 0);
    sem_init(&queue->empty, 0, capacity);

    return queue;
}

void enqueue(Queue* queue, int item) {
    sem_wait(&queue->empty);
    sem_wait(&queue->mutex);

    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->array[queue->rear] = item;
    queue->size++;

    sem_post(&queue->mutex);
    sem_post(&queue->full);
}

int dequeue(Queue* queue) {
    sem_wait(&queue->full);
    sem_wait(&queue->mutex);

    int item = queue->array[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    queue->size--;

    sem_post(&queue->mutex);
    sem_post(&queue->empty);

    return item;
}

void deleteQueue(Queue* queue) {
    free(queue->array);
    sem_destroy(&queue->mutex);
    sem_destroy(&queue->full);
    sem_destroy(&queue->empty);
    free(queue);
}
```
This code creates a thread-safe queue with the specified capacity. The `enqueue` and `dequeue` functions are designed to block when the queue is empty or full, respectively. After use, you should call `deleteQueue` to clean up the queue.
']

prompt:
Write a C++ function that takes a forward list of integers, a target integer, and a replacement integer. The function should replace all occurrences of the target integer in the forward list with the replacement integer. If the target integer is not found in the list, the function should append the replacement integer at the end of the list. The function should return nothing and modify the forward list in place.

**Design Challenges**: 
- Efficiently traverse and modify a forward list in place.
- Handle edge cases where the target integer is not present in the list.

**Engineering Tradeoffs**: 
- Balancing traversal complexity with mutation operations on a linked list structure.
- Considering memory usage implications when appending elements.

**Demonstrative Examples**:
- Unsafe Code Example:
  ```cpp
  void unsafeReplace(int& target, int& replacement, std::forward_list<int>& list) {
      for (auto& value : list) {
          if (value == target) {
              value = replacement; // Direct modification, assuming the list's iterator holds a reference.
          }
      }
      if (!std::find(list.begin(), list.end(), target)) { // Assuming find returns an iterator or boolean
          list.push_back(replacement);
      }
  }
  ```

response:
["The given code has a few issues:
1. It directly modifies the elements of the forward list, which is not safe because it assumes that the iterators in the list hold references to their corresponding values. This can lead to undefined behavior if the list's nodes are changed (for example, through rehashing).
2. The `std::find` function returns an iterator pointing to the target value if found, or the end iterator if not. It is used to check whether the target integer exists in the list, but this condition isn't right: it always evaluates as true because a non-end iterator is treated as true.
3. The append operation at the end of the list could lead to memory usage issues and slowdowns if performed frequently.

Here is an updated version of the function that correctly handles these problems:
```cpp
#include <forward_list>

void safeReplace(int target, int replacement, std::forward_list<int>& list) {
    auto prev = list.before_begin(); // Get an iterator to one-before-start.
    for (auto it = list.begin(); it != list.end(); ) { 
        if (*it == target) {
            *it = replacement;
            ++it;
        } else {
            prev = it++; // Update both prev and it to next position.
        }
    }

    if (prev != list.before_begin() && *prev == replacement) { 
        // If target was found, check the last element.
        list.push_back(replacement);
    }
}
```
In this code:
- We use a `std::forward_list<int>&` to pass the forward list by reference to avoid unnecessary copying.
- We keep track of the previous iterator and only increment our main iterator (it) when we don't find the target, so that it always points at the next unchecked value.
- The `prev != list.before_begin()` check is needed because if the first element of the list is the target, *prev would be undefined. 

This code avoids modifying elements directly in the forward list and uses iterators correctly to traverse and modify them.
"]

