```javascript
// Define regex patterns for old testament books
let booksRegex = {
  "Genesis": /\bgenesis\b/gi,
  "Exodus": /\bexodus\b/gi,
  // add more books here...
};

function findOldTestamentBooks(text) {
  let result = {};

  for (let book in booksRegex) {
    let matches = text.match(booksRegex[book]);

    if (matches !== null) {
      // Use a Set to ignore duplicates within the same entry
      let uniqueMatches = new Set(matches);

      result[book] = uniqueMatches.size;
    } else {
      result[book] = 0;
    }
  }

  return result;
}
