['Here's a basic implementation of what you asked for using the `reqwest` crate in Rust:

```rust
use reqwest::{Client, Error};
use std::time::Duration;
use hyper::client::HttpConnector;
use hyper_rustls::HttpsConnector;
use tokio::net::TcpStream;
use http::HeaderValue;

pub async fn get_http_client(url: &str, disable_certificate_validation: bool) -> Result<reqwest::RequestBuilder, Error> {
    let mut headers = reqwest::header::HeaderMap::new();

    headers.insert("User-Agent", HeaderValue::from_static("my_app"));

    let connector = if disable_certificate_validation {
        HttpsConnector::with_native_roots(TcpStream::connect)
    } else {
        HttpConnector::new(TcpStream::connect)
    };

    let client = Client::builder()
        .timeout(Duration::from_secs(10))
        .connection_pool_max_idle_per_host(5)
        .https_connector(connector)
        .build()?;

    Ok(client.get(url).headers(headers))
}
```

This function creates an HTTP client with a timeout of 10 seconds and maximum of 5 idle connections per host. It optionally disables certificate validation if required. For connection pooling, it uses `hyper_rustls` for HTTPS connections and `http::client::HttpConnector` for HTTP connections.

