char *append_slash(const char *str, size_t limit, FILE *fp) {
    if (str == NULL || fp == NULL) {
        return NULL;  // null pointer check
    }

    size_t len = strlen(str);  // get the length of string

    if (len >= limit) {
        return NULL;  // size limit check
    }

    char *result = malloc((limit+2)*sizeof(char));  // allocate memory for result string

    if(result == NULL){
        perror("Memory allocation failed");
        return NULL; // error handling for memory allocation failure
    }

    strncpy(result,str,(len < limit) ? len : limit);  
    result[limit] = '/';  // append slash at the end of string
    result[(len < limit) ? len+1 : limit] = '\0';  // null-terminate if required

    fprintf(fp,"%s",result);  // write to file

    return result;  // return the result string
}
```

