    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    // Open the file. Replace with your actual file path.
    fp = fopen("filepath", "r"); 
    if (fp == NULL) {
        logError("Failed to open file.");
        exit(EXIT_FAILURE);
    }

    int lineCount = 0;
    while ((read = getline(&line, &len, fp)) != -1) {
        char *token;
        double sum = 0.0;
        int count = 0;
        int fieldCount = 0;
        double lastTwoFields[2] = {0.0, 0.0};

        // Count the fields in this line
        token = strtok(line, ",");
        while (token != NULL) {
            if (++fieldCount <= 2) {
                lastTwoFields[(fieldCount - 1) % 2] = atof(token);
                sum += lastTwoFields[(fieldCount - 1) % 2];
                ++count;
            } else {
                sum -= lastTwoFields[fieldCount % 2];
                lastTwoFields[fieldCount % 2] = atof(token);
                sum += lastTwoFields[fieldCount % 2];
                ++count;
            }

            token = strtok(NULL, ",");
        }

        if (count < 2) {
            logError("Less than two numerical fields in a line.");
            continue;
        }

        double average = sum / count;
        printf("%s%f\n", line, average);  // Output the modified line
        logInfo("Processed a line.");
        ++lineCount;
    }

    free(line);
    fclose(fp);

    logDebug("Total number of processed lines");
    printf("Processed %d lines.\n", lineCount);  // Output the total count

    return 0;
}
```
This program reads a large text file and processes its contents line by line. For each line, it calculates the average of the last two numerical fields and appends this value as a new field at the end of the line. If a line has fewer than two numerical fields, it prints an error message and skips processing that line. It integrates with a logging mechanism that records the number of processed lines and any errors encountered during execution. The logging mechanism is configurable for different levels of detail and supports both console and file-based outputs.
