#include <stdio.h>
#include <string.h>
#include <ctype.h>
#define MAX_LEN 256

void modifyFilename(char *filename) {
    char dir[MAX_LEN] = "", baseName[MAX_LEN] = "", extension[MAX_LEN] = "";
    const char* lastSlash = strrchr(filename, '/');
    if (lastSlash != NULL) {
        strncpy(dir, filename, lastSlash - filename);
        dir[lastSlash - filename] = '\0'; // Terminate the directory string
    }

    const char* lastDot = strrchr(filename, '.');
    if (lastDot != NULL) {
        size_t lenFilename = strlen(filename);
        strncpy(extension, lastDot + 1, lenFilename - ((lastDot+1) - filename)); // Copy the extension

        size_t lenBaseName = (lastDot - 1) - filename;
        if (*dir != '\0') {
            strncpy(baseName, lastSlash + 1, lenBaseName);
        } else {
            strncpy(baseName, filename, lenBaseName);
        }

        baseName[lenBaseName] = '\0'; // Terminate the basename string
    } else {
        if (*dir != '\0') {
            strcpy(baseName, lastSlash + 1);
        } else {
            strcpy(baseName, filename);
        }
    }

    size_t lenExtension = strlen(extension) + (strlen(filename) - 5);
    if (lenExtension > 8) lenExtension = 8;

    sprintf(extension, ".%0*lu", (unsigned long)(lenExtension), lenExtension); // Modify the extension

    strcpy(filename, ""); // Reset filename string
    if (*dir != '\0') {
        strcat(filename, dir);
        strcat(filename, "/");
    }
    strcat(filename, baseName);
    strcat(filename, extension);
}
```
This function takes a character array `filename` as input and modifies it according to the rules. Please note that this code is case-sensitive when comparing and manipulating the filename components, and it can handle filenames with spaces and special characters correctly. 

