```c
#include <openssl/evp.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>

typedef struct cipher_context {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

static void cleanup(CipherContext* cipher) {
    if (cipher == NULL || cipher->ctx == NULL) return;

    EVP_CIPHER_CTX_cleanup(cipher->ctx); 
    free(cipher->ctx);  
    memset(&cipher->key, 0, sizeof(cipher->key)); 
    memset(&cipher->iv, 0, sizeof(cipher->iv)); 
}

CipherContext* initialize_aes256cbc(const char *password, const unsigned char *salt, int saltlen) {
    CipherContext *cipher = (CipherContext*)calloc(1, sizeof(CipherContext));

    if (!cipher) return NULL;  // Out of memory.

    cipher->ctx = EVP_CIPHER_CTX_new();

    if(!EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char*)password, strlen(password), 1, cipher->key, cipher->iv)) {
        cleanup(cipher);
        return NULL; // Error deriving key and IV.
    }

    if(!EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, cipher->key, cipher->iv)) {
        cleanup(cipher);
        return NULL; // Error initializing cipher.
    }

    return cipher;
}
```
This code defines a `CipherContext` struct that will hold the OpenSSL context and derived encryption key/IV, as well as providing functions to initialize (`initialize_aes256cbc()`) and clean up after use (`cleanup()`). 

You can then utilize this code like:
