['Here is a simple implementation in C using libcurl which you may need to install on your machine. This code handles redirections, retries, timeout detection, and gracefully handles various HTTP status codes. 

```c
#include <stdio.h>
#include <string.h>
#include <curl/curl.h>

size_t write_data(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    size_t written = fwrite(ptr, size, nmemb, stream);
    return written;
}

int download_file(char* url, char* filepath) {
    CURL *curl;
    FILE *fp;
    CURLcode res;
    int ret = 1;

    curl = curl_easy_init();
    if (curl) {
        fp = fopen(filepath,"wb");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
        curl_easy_setopt(curl, CURLOPT_FAILONERROR, 1L);
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 60); // Set timeout to 60 seconds

        int tries = 3;
        while (tries > 0) {
            res = curl_easy_perform(curl);

            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                tries--;
            } else {
                long http_code = 0;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

                if (http_code == 200) { // HTTP 200 is OK status
                    ret = 0;
                    break;
                } else {
                    fprintf(stderr, "HTTP request failed with response code: %ld\n", http_code);
                    tries--;
                }
            }
        }

        curl_easy_cleanup(curl);
        fclose(fp);
    }

    return ret;
}
``` 
Please note that you'll need to install libcurl-dev and include it during compile. You can do this by using the following commands:

Ubuntu/Debian: `sudo apt-get install libcurl4-openssl-dev`
CentOS/RHEL: `yum install curl-devel`
