['Here's an example implementation using `jansson` library in C. This code assumes that you already have jansson installed and linked to your project. If not, you can install it via package manager or download from here https://digip.org/jansson/. 

```c
#include <stdio.h>
#include <string.h>
#include <jansson.h>

int validate_access_token(const char *json_str) {
    json_t *root;
    json_error_t error;

    root = json_loads(json_str, 0, &error);
    if(!root) {
        fprintf(stderr, "Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return 0;
    }

    if(!json_is_object(root)) {
        json_decref(root);
        fprintf(stderr, "JSON is not an object\n");
        return 0;
    }

    // Required fields and their types
    const char *fields[] = {"access_token", "expires_in", "token_type"};
    json_type type[] = {json_string, json_integer, json_string};

    int valid = 1;
    for(int i = 0; i < 3; ++i) {
        json_t *value = json_object_get(root, fields[i]);

        if(!value || !json_is_type(value, type[i])) {
            fprintf(stderr, "Missing or invalid '%s' field\n", fields[i]);
            valid = 0;
        } else if (strcmp(fields[i], "access_token") == 0 && json_string_length(value) == 0) {
            fprintf(stderr, "'%s' cannot be an empty string\n", fields[i]);
            valid = 0;
        } else if (strcmp(fields[i], "expires_in") == 0 && json_integer_value(value) >= 604800) {
            fprintf(stderr, "'%s' must be less than 7 days\n", fields[i]);
            valid = 0;
        } else if (strcmp(fields[i], "token_type") == 0 && strcmp(json_string_value(value), "Bearer") != 0) {
            fprintf(stderr, "'%s' must be 'Bearer'\n", fields[i]);
            valid = 0;
        }
    }

    // Optional field
    json_t *refresh_token = json_object_get(root, "refresh_token");
    if(refresh_token && (!json_is_string(refresh_token) || json_string_length(refresh_token) == 0)) {
        fprintf(stderr, "'refresh_token' is present but invalid\n");
        valid = 0;
    }

    // Cleanup
    json_decref(root);
    return valid;
}
```
This code parses the JSON string into a `json_t` object and checks that each required field exists, has the correct type, and meets your specified criteria. If any of these conditions fail, it prints an error message to stderr and returns false (0). Otherwise, it decrefs the json object and returns true (1).
']

