public class CommunicationService
{
    private readonly HttpClient _httpClient;

    public CommunicationService()
    {
        _httpClient = new HttpClient();
    }

    public async Task<string> SendAndReceiveData(byte[] data, string remoteUrl)
    {
        try
        {
            byte checksum = CalculateChecksum(data); // Assuming a simple checksum method

            var requestContent = new ByteArrayContent(data);
            requestContent.Headers.Add("checksum", checksum.ToString());

            var response = await _httpClient.PostAsync(remoteUrl, requestContent);
            response.EnsureSuccessStatusCode(); // Throws an exception if the response code is not successful

            return await response.Content.ReadAsStringAsync();
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine("Error occurred while communicating with the server: " + ex.Message);
            throw; // Rethrow the exception to let the caller know there was a problem
        }
    }

    private byte CalculateChecksum(byte[] data)
    {
        // This is a simple checksum calculation, you may want to use a stronger algorithm for your application
        byte checksum = 0;

        foreach (var item in data)
            checksum += item;

        return checksum;
    }
}
```
