    private static readonly List<CryptoDataStruct> _availableFunctions = new List<CryptoDataStruct>();

    public string DecryptAndListCryptography(string encryptedMessage, byte[] key, byte[] iv)
    {
        try
        {
            using (TripleDES tripleDesAlgorithm = TripleDES.Create())
            {
                // Set the Key and IV
                tripleDesAlgorithm.Key = key;
                tripleDesAlgorithm.IV = iv;

                byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);

                using (MemoryStream memoryStreamDecrypt = new MemoryStream(encryptedBytes))
                using (CryptoStream cryptoStreamDecrypt = new CryptoStream(memoryStreamDecrypt, tripleDesAlgorithm.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    byte[] decryptedBytes = new byte[encryptedBytes.Length];

                    // Perform the decryption and return result as string
                    cryptoStreamDecrypt.Read(decryptedBytes, 0, decryptedBytes.Length);

                    return Encoding.Unicode.GetString(decryptedBytes).TrimEnd('\0');
                }
            }
        }
        catch (Exception e)
        {
            Console.WriteLine("Error: " + e.Message); // Log or handle the error properly in production code
            return null;
        }
    }

    public IEnumerable<CryptoDataStruct> ListAvailableFunctions()
    {
        if (_availableFunctions.Count == 0)
        {
            var hashAlgorithms = typeof(HashAlgorithm).Assembly.GetTypes().Where(t => t.IsSubclassOf(typeof(HashAlgorithm)));

            foreach (var algorithm in hashAlgorithms)
