```c
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

CipherContext* initializeAES256(const char* password, const char* salt, int useFixedIv) {
    CipherContext *cipher = malloc(sizeof(CipherContext));
    if (cipher == NULL) return NULL; // handle memory allocation failure

    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), digest);

    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), (unsigned char*)salt, digest, 1, cipher->key, cipher->iv);

    if (!useFixedIv) {
        RAND_bytes(cipher->iv, EVP_CIPHER_CTX_iv_length(cipher->ctx)); // ensure iv is correctly generated and stored for decryption purposes
    }

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (cipher->ctx == NULL) return NULL; // handle memory allocation failure

    EVP_EncryptInit(cipher->ctx, EVP_aes_256_cbc(), cipher->key, cipher->iv);

    return cipher;
}

void cleanupCipherContext(CipherContext* ctx) {
    if (ctx == NULL) return;

    EVP_CIPHER_CTX_cleanup(ctx->ctx); // disable and clean up the cipher after use

    free(ctx);
}
```
