        const verticesToAdd = Math.floor(Math.random() * 10); // Random number of vertices to add
        const edgesToAdd = Math.floor(Math.random() * 10); // Random number of edges to add

        let cmd = `${graphDbCommand} add-vertex ${verticesToAdd}`;
        exec(cmd, (error, stdout) => {
            if (error) {
                reject(error);
                return;
            }

            // Add random properties on the vertices here...

            cmd = `${graphDbCommand} add-edge ${edgesToAdd}`;
            exec(cmd, (error, stdout) => {
                if (error) {
                    reject(error);
                    return;
                }

                // Add random properties on the edges here...

                resolve({vertices: verticesToAdd, edges: edgesToAdd});
            });
        });
    });
}
