['Here's how you can create such an Rust function using the `std::env`, `std::path::PathBuf`, `std::fs`, and `log` libraries. This code does not handle concurrent access from multiple threads in a safe manner, as this requires more complex mechanisms (e.g., locks or atomics) which are beyond the scope of this problem.

```rust
use std::env;
use std::path::PathBuf;
use std::fs;
use log::{info, warn};
use rand::Rng;

pub fn manage_config(default_name: Option<&str>) -> PathBuf {
    let mut config_dir = dirs::home_dir().unwrap();

    if let Ok(env_var) = env::var("CONFIG_DIR") {
        info.log(&format![ "Environment variable CONFIG_DIR found: {}", &env_var]);

        match PathBuf::from(env_var).exists() {
            true => config_dir = PathBuf::from(env_var),
            false => {
                let random_number: u64 = rand::thread_rng().gen();

                if let Some(default) = default_name {
                    warn.log(&format![ "Directory doesn't exist, using default name {}", &default]);

                    config_dir.push(&format![ "{}{}", default, random_number]);
                } else {
                    config_dir.push(random_number.to_string());
                }
            },
        }
    } else {
        warn.log("Environment variable CONFIG_DIR not set.");

        if let Some(default) = default_name {
            info.log(&format![ "Using default name {}", &default]);

            config_dir.push(default);
        }
    }

    fs::create_dir_all(&config_dir).unwrap(); // Create directory if it doesn't exist
    env::set_var("CONFIG_DIR", config_dir.to_str().unwrap()).unwrap();  // Set environment variable to the path of the directory

    info.log(&format![ "Using configuration directory: {}", &config_dir.display()]);

    std::mem::drop(std::panic::catch_unwind(move || {
        let _ = fs::remove_dir_all(&config_dir); // Clean up the created directory
    }));

    config_dir
}
```

You'd need to add `log`, `rand` and `dirs` dependencies in your `Cargo.toml` file:

