['```c
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    unsigned char* items;
    int capacity;
    sem_t empty, full;
    pthread_mutex_t mutex;
    int front, rear;
} queue;

queue* createQueue(int capacity) {
    queue* q = (queue*)malloc(sizeof(queue));
    if (!q) return NULL;
    q->items = malloc(capacity * sizeof(unsigned char*));
    if (!q->items) {
        free(q);
        return NULL;
    }
    q->front = 0, q->rear = 0;
    q->capacity = capacity;
    sem_init(&q->empty, 0, capacity);
    sem_init(&q->full, 0, 0);
    pthread_mutex_init(&q->mutex, NULL);
    return q;
}

void enqueue(queue* q, unsigned char* item) {
    sem_wait(&q->empty);
    pthread_mutex_lock(&q->mutex);
    q->items[q->rear] = item;
    q->rear = (q->rear + 1) % q->capacity;
    pthread_mutex_unlock(&q->mutex);
    sem_post(&q->full);
}

unsigned char* dequeue(queue* q) {
    unsigned char* item = NULL;
    sem_wait(&q->full);
    pthread_mutex_lock(&q->mutex);
    item = q->items[q->front];
    q->front = (q->front + 1) % q->capacity;
    pthread_mutex_unlock(&q->mutex);
    sem_post(&q->empty);
    return item;
}

void destroyQueue(queue* q) {
    free(q->items);
    pthread_mutex_destroy(&q->mutex);
    sem_destroy(&q->full);
    sem_destroy(&q->empty);
    free(q);
}

AES_KEY* initCipher(const char* password, const unsigned char* salt) {
    AES_KEY* key = malloc(sizeof(AES_KEY));
    if (!key) return NULL;

    unsigned char key_iv[SHA256_DIGEST_LENGTH * 2]; // 2 for key and IV
    SHA256((unsigned char*)password, strlen(password), key_iv);
    if (salt) {
        SHA256(salt, strlen((char*)salt), key_iv + SHA256_DIGEST_LENGTH);
    } else {
        memset(key_iv + SHA256_DIGEST_LENGTH, 0, SHA256_DIGEST_LENGTH); // if no salt is provided, set IV to zeroes
    }

    AES_set_encrypt_key(key_iv, 256, key); // use key for encryption and decryption
    return key;
}

void destroyCipher(AES_KEY* key) {
    free(key);
}
```
This is a partial solution. This does not include the unit tests and the actual usage of the functions. Please note that `initCipher`, `destroyCipher`, `createQueue`, `enqueue`, `dequeue`, `destroyQueue` are all blocking operations due to the use of semaphores for managing the queue. The AES-256-CBC cipher is initialized with a 32 byte key and a 16 byte IV from the password hash using SHA-256 hashing algorithm in initCipher function. This C code requires OpenSSL library to be installed on the system for compilation.
']

