typedef struct {
    EVP_CIPHER_CTX *ctx;
} EncryptContext;

EncryptContext* initEncryptAndRename(const char *filename, const char *password, const unsigned char *salt, int numDigits) {
    if (numDigits < 1) {
        return NULL; // Invalid number of digits.
    }

    EncryptContext *ctx = malloc(sizeof(EncryptContext));
    if (!ctx) {
        return NULL; // Memory allocation failure.
    }

    unsigned char key[SHA256_DIGEST_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];

    SHA256((const unsigned char *)password, strlen(password), key); // Generate encryption key.

    if (salt) { // If a salt is provided, incorporate it into the IV generation process.
        memcpy(iv + SHA256_DIGEST_LENGTH, salt, EVP_MAX_IV_LENGTH - SHA256_DIGEST_LENGTH);
    } else { // If not, use a random seed for the IV generation process.
        srand((unsigned int)time(NULL));
        for (size_t i = SHA256_DIGEST_LENGTH; i < EVP_MAX_IV_LENGTH; ++i) {
            iv[i] = rand() % 256;
        }
    }

    ctx->ctx = EVP_CIPHER_CTX_new(); // Initialize cipher context.
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        cleanupAndFreeContext(ctx);
        return NULL; // Cipher initialization failure.
    }

    char newFilename[strlen(filename) + 10]; // Allocate memory for the new filename.
    sprintf(newFilename, "%.*s.%d.enc", (int)strlen(filename), filename, numDigits); // Append extension to filename.

    if (rename(filename, newFilename)) {
        cleanupAndFreeContext(ctx);
        return NULL; // Renaming failure.
    }

    return ctx;
}

void cleanupAndFreeContext(EncryptContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx); // Clean up the cipher context.
    free(ctx); // Free the memory allocated for the context.
}
