#define BUFFER_SIZE 1024

typedef struct MessageBuffer {
    unsigned char *buffer;
    size_t length;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} MessageBuffer;

void initMessageBuffer(MessageBuffer *mb) {
    mb->buffer = (unsigned char *)malloc(BUFFER_SIZE);
    if (mb->buffer == NULL) {
        exit(EXIT_FAILURE);
    }
    mb->length = 0;
    pthread_mutex_init(&mb->mutex, NULL);
    pthread_cond_init(&mb->cond, NULL);
}

void destroyMessageBuffer(MessageBuffer *mb) {
    free(mb->buffer);
    pthread_mutex_destroy(&mb->mutex);
    pthread_cond_destroy(&mb->cond);
}

int addToMessageBuffer(MessageBuffer *mb, unsigned char *data, size_t length) {
    pthread_mutex_lock(&mb->mutex);

    while (length + mb->length > BUFFER_SIZE) {
        // Buffer full, wait for space to become available
        pthread_cond_wait(&mb->cond, &mb->mutex);
    }

    memcpy(mb->buffer + mb->length, data, length);
    mb->length += length;

    // Signal that space has become available
    pthread_cond_signal(&mb->cond);

    pthread_mutex_unlock(&mb->mutex);
}
