typedef struct {
    int quant_table[2][64];
    int huffman_tables[2][17];
    JPEGCOLORSPACE color_space;
    int num_components;
} ImageInfo;

ImageInfo parseJpeg(char* filename) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE * infile;        /* source file */
    JSAMPARRAY buffer;        /* Output row buffer */

    ImageInfo imageInfo;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    if ((infile = fopen(filename, "rb")) == NULL) {
        fprintf(stderr, "can't open %s\n", filename);
        exit(1);
    }

    jpeg_stdio_src(&cinfo, infile);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    // Get Quantization Tables
    for (int i = 0; i < cinfo.quant_tbl_ptrs->length; i++) {
        imageInfo.quant_table[i][0] = cinfo.quant_tbl_ptrs->tbl_pts[i]->quantval[0];
        //... rest of quantization table values
    }

    // Get Huffman Tables
    for (int i = 0; i < cinfo.ac_huff_tbl_ptrs->length; i++) {
        imageInfo.huffman_tables[i][0] = cinfo.ac_huff_tbl_ptrs->tbl_list[i].class_code[0];
        //... rest of huffman table values
    }

    imageInfo.color_space = cinfo.out_color_space;
    imageInfo.num_components = cinfo.output_components;

    jpeg_destroy_decompress(&cinfo);
    fclose(infile);

    return imageInfo;
}
