        unsigned char sha_out[SHA256_DIGEST_LENGTH];
        SHA256((unsigned char*)password, strlen(password), sha_out);

        if (salt != NULL && saltlen > 0) {  // use salt if provided
            unsigned char newSha[SHA256_DIGEST_LENGTH];
            SHA256(sha_out, sizeof(sha_out), newSha);

            memcpy(newCtx->key, newSha, EVP_MAX_KEY_LENGTH);
        } else {  // use password directly otherwise
            memcpy(newCtx->key, sha_out, EVP_MAX_KEY_LENGTH);
        }

        // generate random IV
        RAND_bytes(newCtx->iv, EVP_MAX_IV_LENGTH); 

        newCtx->ctx = EVP_CIPHER_CTX_new(); 
        if (EVP_EncryptInit_ex(newCtx->ctx, EVP_aes_256_cbc(), NULL, newCtx->key, newCtx->iv) != 1) {
            free(newCtx);  // cleanup on initialization failure
            return NULL;
        }

        if (reuse) ctxCache = *newCtx;  // cache context for reusing

        char* dotPos = strrchr(filename, '.'); 
        int newLen = (dotPos == NULL ? strlen(filename) : dotPos - filename) + 1 + digits + strlen(FILETYPE);
        char* newName = malloc(newLen+1);

        if (newName != NULL) {
            sprintf(newName, "%.*s%0*d%s", (dotPos == NULL ? strlen(filename) : dotPos - filename), filename, digits, FILETYPE);

            // Rename file with new extension here...
        }

        free(newName);  // cleanup dynamically allocated memory

        return reuse ? &ctxCache : newCtx;
    }
}
