['Here's the Java method you asked for:
```java
import java.io.*;
import java.security.MessageDigest;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.codec.binary.Base64;

public class StateLoader {
    private Cipher cipher;
    private SecretKeySpec secretKey;
    private IvParameterSpec ivParam;

    public Object loadState(String fileName, String password) throws Exception {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(fileName))) {
            initCipher(password);
            byte[] encryptedData = (byte[]) ois.readObject();
            return decrypt(encryptedData);
        } catch (Exception e) {
            e.printStackTrace();
            throw e;
        } finally {
            disableCipher();
        }
    }

    private void initCipher(String password) throws Exception {
        byte[] key = password.getBytes("UTF-8");
        MessageDigest sha = MessageDigest.getInstance("SHA-1");
        key = sha.digest(key);
        key = Arrays.copyOf(key, 32); // use first 256 bits

        secretKey = new SecretKeySpec(key, "AES");
        ivParam = new IvParameterSpec("1234567890ABCDEF".getBytes());
        cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");

        cipher.init(Cipher.DECRYPT_MODE, secretKey, ivParam);
    }

    private Object decrypt(byte[] encryptedData) throws Exception {
        byte[] original = cipher.doFinal(Base64.decodeBase64(encryptedData));

        try (ByteArrayInputStream bais = new ByteArrayInputStream(original);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return ois.readObject();
        }
    }

    private void disableCipher() throws Exception {
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivParam);
    }
}
```
This code uses the Apache Commons Codec library for base64 decoding. Make sure to add it to your project dependencies. Also, note that this code does not handle password hashing or encryption key derivation properly. In a real-world scenario, you should use proven and secure methods.
