typedef struct ImageContext {
    MagickWand *image;
    int reuse_flag;  // flag indicating if the image context can be reused or not
} ImageContext;

ImageContext* processAndOptimizeImage(char *filename, int compression_level, float quality_setting, int reuse_flag, int metadata_update) {
    static ImageContext previous_context = {NULL, 0}; // this will store the previously processed image context

    if (reuse_flag && previous_context.image != NULL && strcmp(previous_context.filename, filename) == 0) {
        /* If the reuse flag is set and a context already exists for this file, use it */
        return &previous_context;
    } else {
        /* Otherwise, create a new context and process the image */

        ImageContext *new_context = (ImageContext*) malloc(sizeof(ImageContext));  // allocate memory for the new context

        if (new_context == NULL) {
            fprintf(stderr, "Memory allocation failed. Aborting.\n");
            return NULL;  // handle memory allocation failure gracefully and return NULL
        }

        MagickWandGenesis();

        new_context->image = NewMagickWand();
        if (new_context->image == NULL) {
            fprintf(stderr, "Failed to create image wand. Aborting.\n");
            return NULL;  // handle memory allocation failure gracefully and return NULL
        }

        MagickBooleanType status = MagickReadImage(new_context->image, filename);
        if (status == MagickFalse) {
            fprintf(stderr, "Failed to read image. Aborting.\n");
            return NULL;  // handle memory allocation failure gracefully and return NULL
        }

        /* Process the image using ImageMagick functions */
        MagickSetCompressionQuality(new_context->image, quality_setting);
        MagickSetImageCompressionQuality(new_context->image, compression_level);

        if (metadata_update) {
            /* Update metadata using ExifTool API */
            char command[256];
            sprintf(command, "exiftool -all= %s", filename);  // replace with actual ExifTool command based on your needs
            system(command);
        }

        MagickWandTerminus();

        if (reuse_flag) {
            /* If the reuse flag is set, save the new context and free the previous one */
            free(previous_context.image);
            previous_context = *new_context;

            return &previous_context;
        } else {
            /* Otherwise, return the new context */
            return new_context;
        }
    }
}

void cleanupImageContext(ImageContext *context) {
    if (context != NULL && context->image != NULL) {
        DestroyMagickWand(context->image);  // free the image wand

        /* Clean up other resources as needed */

        free(context);  // free the memory allocated for the context itself
    }
}
```

