void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& searchStr, const std::string& insertStr) {
    auto it = find(list.begin(), list.end(), searchStr);

    if (it != list.end()) {
        // Use the insert_after function to insert after the first occurrence
        list.insert_after(it, insertStr);
    } else {
        // If not found, append at the end
        list.push_front(searchStr);
        list.push_front(insertStr);
    }
}

void testInsertAfterFirstOccurrence() {
    std::forward_list<std::string> list;

    // Test case when the first string is in the forward list
    insertAfterFirstOccurrence(list, "hello", "world");
    assert(*std::next(list.begin(), 1) == "world");

    // Test case when the first string is not in the forward list
    std::forward_list<std::string> list2;
    insertAfterFirstOccurrence(list2, "hello", "world");
    assert(*std::next(list2.begin(), 1) == "hello");

    // Test case when the first string is at the start of the forward list
    std::forward_list<std::string> list3;
    insertAfterFirstOccurrence(list3, "hello", "world");
    assert(*std::next(list3.begin(), 1) == "world");

    // Test case when the first string is at the end of the forward list
    std::forward_list<std::string> list4;
    insertAfterFirstOccurrence(list4, "hello", "world");
