#define SIGNATURE "YourSignature"
#define VERSION 1

typedef struct {
    int type;
    void* data;
} ResourceItem;

typedef struct {
    pthread_mutex_t mutex;
    ResourceItem** items;
    int capacity;
    int size;
    int head;
    int tail;
} ThreadSafeQueue;

ThreadSafeQueue queue = {PTHREAD_MUTEX_INITIALIZER, NULL, 0, 0, 0, 0};
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* load_resource(ResourceItem* item) {
    /* Implement resource loading */
}

int load_resource_bundle(char *path, int fd) {
    FILE* file = NULL;

    if (path != NULL) {
        file = fopen(path, "rb");
    } else if (fd >= 0) {
        file = fdopen(fd, "rb");
    }

    if (file == NULL) return -1;  // Return error code for invalid file path or descriptor

    /* Read and validate header */
    char signature[256];
    int version;
    fread(signature, sizeof(char), 256, file);
    fread(&version, sizeof(int), 1, file);

    if (strcmp(signature, SIGNATURE) != 0 || version != VERSION) {
        fclose(file);
        return -2;  // Return error code for invalid signature or version
    }

    int num_items;
    fread(&num_items, sizeof(int), 1, file);

    /* Allocate memory for the bundle */
    ResourceItem** items = (ResourceItem**) malloc(sizeof(ResourceItem*) * num_items);

    if (items == NULL) {
        fclose(file);
        return -3;  // Return error code for memory allocation failure
    }

    /* Load resources */
    int i = 0;
    while (!feof(file)) {
        ResourceItem* item = malloc(sizeof(ResourceItem));

        if (item == NULL) continue;  // Skip this item and continue with the next one

        /* Load resource data */
        load_resource(item);

        items[i++] = item;
    }

    fclose(file);

    pthread_mutex_lock(&queue.mutex);

    while (queue.size >= queue.capacity) {
        /* Signal when the queue is full */
        pthread_cond_wait(&cond, &queue.mutex);
    }

    for (i = 0; i < num_items; ++i) {
        /* Add items to queue */
        queue.items[queue.tail] = items[i];
        queue.tail = (queue.tail + 1) % queue.capacity;
        ++queue.size;
    }

    pthread_cond_signal(&cond);  /* Signal that the queue is not empty */
    pthread_mutex_unlock(&queue.mutex);

    free(items);

    return num_items;
}
```
