typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AESContext;

AESContext *initEncryptAndRename(char **filename, char *password, char *salt, int numDigits, bool reuseFlag, bool compressFlag) {
    static AESContext ctx = {0};

    // check if a previously initialized cipher context should be reused
    if (!reuseFlag || !ctx.ctx) {
        unsigned char *digest;

        if (salt) {
            digest = SHA256(password, salt);
        } else {
            digest = SHA256(password);
        }

        ctx.key = digest + 0;  // use first half of SHA-256 hash as key
        ctx.iv  = digest + SHA256_DIGEST_LENGTH / 2;  // use second half of SHA-256 hash as IV

        if (!(ctx.ctx = EVP_CIPHER_CTX_new())) {
            printf("Failed to allocate memory for cipher context!\n");
            return NULL;
        }
    }

    // initialize the AES-256-CBC cipher with the derived key and IV
    if (1 != EVP_EncryptInit_ex(ctx.ctx, EVP_aes_256_cbc(), NULL, ctx.key, ctx.iv)) {
        printf("Failed to initialize cipher!\n");
        return NULL;
    }

    // modify filename extension
    char newExt[10];
    sprintf(newExt, "%.*d%s", numDigits, rand(), ".encrypted");  // append a random number and .encrypted file type
