        char *compressedFilename = malloc(strlen(*filename));  // allocate memory for compressed filename

        if (!compressedFilename) {
            printf("Failed to allocate memory for compressed filename!\n");
            return NULL;
        }

        // compress the modified filename using zlib (example compression library)
        int res = compress(compressedFilename, &strlen(*filename), *filename, strlen(*filename));
        if (res != Z_OK) {
            printf("Failed to compress filename with error code %d!\n", res);
            free(compressedFilename);  // cleanup compressed filename memory
            return NULL;
        }

        free(*filename);  // cleanup original filename memory
        *filename = compressedFilename;  // update filename pointer to point to compressed filename
    }

    return &ctx;
}
