public class MyMultiThreadedQueue implements Runnable {
    private static final int MAX_QUEUE_SIZE = 10000; // Example maximum size
    private Queue<String> queue = new LinkedList<>();
    private Map<String, String> cache = new HashMap<>();

    public synchronized void enqueue(String data) throws Exception {
        if (data == null || data.isEmpty()) throw new Exception("Input string cannot be null or empty");

        while (queue.size() >= MAX_QUEUE_SIZE) {
            wait(); // Wait for queue to have space
        }
        queue.add(data);
        notifyAll(); // Notify waiting threads that data is available
    }

    public synchronized String dequeue() throws Exception {
        while (queue.isEmpty()) {
            wait(); // Wait until there's something to dequeue
        }

        String data = queue.remove();
        notifyAll(); // Notify waiting threads that space is available
        return data;
    }

    public void computeAndCacheMD5(String input) throws Exception {
        if (input == null || input.isEmpty()) throw new Exception("Input string cannot be null or empty");

        long startTime = System.nanoTime();
        String md5;

        try {
            MessageDigest messageDigest = MessageDigest.getInstance("MD5");
            messageDigest.update(input.getBytes());
            byte[] digest = messageDigest.digest();
            md5 = DatatypeConverter.printHexBinary(digest).toUpperCase();
        } catch (Exception ex) {
            throw new Exception("Failed to compute MD5: " + ex);
        }

        long endTime = System.nanoTime();
        double elapsedTimeInMs = (endTime - startTime)/1000000.0;
