typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} EncryptContext;

EncryptContext* initEncryptAndRename(const char *filename, const char *password, const char *salt, int digits, int reuse) {
    static EncryptContext ctx = { NULL, 0 };

    if (reuse && ctx.ctx != NULL) return &ctx;

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);

    if (salt != NULL) {
        SHA256_Update(&sha256, salt, strlen(salt));
    }
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(hash, &sha256);

    if (ctx.ctx == NULL) {
        ctx.ctx = EVP_CIPHER_CTX_new();
    }
    EVP_EncryptInit_ex(ctx.ctx, EVP_aes_256_cbc(), NULL, hash, hash + SHA256_DIGEST_LENGTH - EVP_MAX_IV_LENGTH);

    char newFilename[MAX_FILENAME_LENGTH];
    strncpy(newFilename, filename, MAX_FILENAME_LENGTH);
    sprintf(newFilename + strlen(filename), ".%.*d.encrypted", digits, rand() % (int)pow(10, digits));

    FILE* fp = fopen(newFilename, "w");
    if (fp == NULL) {
        printf("Failed to open file for writing.\n");
