const char *allowedExtensions[] = {"txt", "docx", "jpg" /* add more as needed */, NULL};

int isAllowedExtension(const char* filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) return 0;

    for (const char **ext = allowedExtensions; *ext != NULL; ext++) {
        if (strcmp(dot + 1, *ext) == 0)
