  initBufferPool(config);

  pthread_attr_t attr;
  pthread_t threadId[config->max_threads];

  // Initializing threads attributes
  pthread_attr_init(&attr);
  pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

