typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} aes256cbc_context;

int initialize(aes256cbc_context* ctx, const char* password, size_t pw_len, int iterations, int iv_length) {
    if (iterations < 1000 || iterations > 100000) return -1; // invalid iteration count
    if (iv_length < 8 || iv_length > 16) return -2; // invalid IV length
    ctx->ctx = EVP_CIPHER_CTX_new();

    unsigned char salt[8];
    RAND_bytes(salt, sizeof(salt));

    if(!PKCS5_PBKDF2_HMAC(password, pw_len, salt, sizeof(salt), iterations, EVP_sha256(), 32, ctx->key)) return -3; // PBKDF2 error

    RAND_bytes(ctx->iv, iv_length); // generate IV

    EVP_CIPHER_CTX_init(ctx->ctx);
    if(!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) return -4; // initialization error

    return 0; // success
}

void cleanup(aes256cbc_context* ctx) {
    EVP_CIPHER_CTX_cleanup(ctx->ctx);
    OPENSSL_cleanse(ctx, sizeof(*ctx));
}
```

This code initializes a new AES-256-CBC cipher context with a given password. It supports both PBKDF2 key derivation and a fixed salt for enhanced security. The IV length can be configured within the specified range and the number of PBKDF2 iterations is also adjustable. 

