```c
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX* ctx;
} cipher_t;

cipher_t* initialize_cipher(const char* password, int enable) {
    if (!password || !strlen(password)) return NULL;  // check for invalid password

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    cipher_t *cipher = (cipher_t*)malloc(sizeof(cipher_t));
    if (!enable) return cipher;  // early return for disabled encryption

    unsigned char key[32];
    unsigned char iv[16];

    EVP_KDF(password, strlen(password), NULL, 0, key, sizeof(key), EVP_sha256());
    EVP_KDF(password, strlen(password), key, sizeof(key), iv, sizeof(iv), EVP_sha256());

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        free(cipher);
        return NULL;  // error initializing cipher
    }

    cipher->ctx = ctx;
    return cipher;
}

void disable_and_cleanup(cipher_t* cipher) {
    if (!cipher || !cipher->ctx) return;  // no context or invalid pointer

    EVP_CIPHER_CTX_free(cipher->ctx);
    free(cipher);
}
```
The `initialize_cipher` function takes a password and an enable flag, and if encryption is enabled, it initializes the cipher context using AES-256-CBC. The key and IV are derived from the password using HKDF with SHA-256 for better security.

