char* processString(const char *str, int sizeLimit, FILE *filePtr, int uppercase) {
    if (sizeLimit < 1 || str[sizeLimit] != '\0' || strlen(str) > sizeLimit) return NULL;  // constraints 1-3
    if (filePtr == NULL) {
        fprintf(stderr, "Invalid file pointer. Aborting...\n");  // constraint 4
        return NULL;
    }

    char *result = malloc(sizeLimit + 2);  // allocate memory for result and slash (+2 for null terminator and slash)
    if (result == NULL) {
        fprintf(stderr, "Memory allocation failed. Aborting...\n");  // constraint 6
        return NULL;
    }

    strncpy(result, str, sizeLimit);  // copy string without null terminator
    result[sizeLimit] = '/';  // append slash
    result[sizeLimit + 1] = '\0';  // add null terminator

    if (uppercase) {
        for (int i = 0; result[i]; i++) result[i] = toupper((unsigned char)result[i]);  // convert to uppercase
    }

    pthread_mutex_lock(&mutex);  // lock mutex for thread safety
    fprintf(filePtr, "%s", result);  // write to file
    pthread_mutex_unlock(&mutex);  // unlock mutex

    free(result);  // deallocate memory
    return "Success";
}
