['Here's a simple implementation of the described task using libcurl to parse the URL components:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>
#include <curl/curl.h>

char* append_random_query(const char *url) {
    CURLU *curlu = curl_url();
    if(!curlu){
        printf("Failed to initialize libcurl\n");
        return NULL;
    }

    CURLUcode rc = curl_url_set(curlu, CURLUPART_URL, url, 0);
    if (rc != CURLUE_OK) {
        printf("Failed to parse URL: %s\n", curl_url_strerror(rc));
        return NULL;
    }

    char *hostname = NULL;
    rc = curl_url_get(curlu, CURLUPART_HOST, &hostname, 0);
    if (rc != CURLUE_OK) {
        printf("Failed to get hostname: %s\n", curl_url_strerror(rc));
        return NULL;
    }

    int len = strlen(hostname) - 3;
    if(len < 0) len = 0; // in case the hostname is shorter than 3 characters

    srand((unsigned int)time(NULL));
    char *random_str = malloc(len + 1);
    for (int i=0; i<len; ++i) {
        random_str[i] = 'A' + rand() % 26; // generates a random uppercase letter
    }
    random_str[len] = 0;

    char *old_query = NULL;
    curl_url_get(curlu, CURLUPART_QUERY, &old_query, CURLU_APPENDQUERY);

    if (old_query) {
        len += strlen(old_query);
    }

    char *new_query = malloc(len + 1); // allocate new query string buffer
    if (old_query) {
        sprintf(new_query, "%s%s", old_query, random_str); 
    } else {
        sprintf(new_query, "%s", random_str);
    }

    free(random_str); // free the allocated memory for random string

    if (len > 100) new_query[100] = 0; // truncate to 100 characters if necessary

    curl_url_set(curlu, CURLUPART_QUERY, new_query, 0); // set the modified query

    char *new_url = NULL;
    rc = curl_url_get(curlu, CURLUPART_URL, &new_url, 0);
    if (rc != CURLUE_OK) {
        printf("Failed to get URL: %s\n", curl_url_strerror(rc));
        return NULL;
    }

    free(old_query); // free the allocated memory for old query string
    free(new_query); // free the allocated memory for new query string
    curl_url_cleanup(curlu);

    return new_url;
}
```

This code initializes libcurl and uses it to parse the input URL. It then generates a random string of length equal to the hostname minus 3, or 0 if the hostname is shorter than 3 characters. This random string is appended to the original query string (if one exists) and truncated to 100 characters if necessary. The function then sets the new query string in the libcurl URL object and retrieves the modified URL as a string. Finally, it cleans up any allocated memory and returns the result.
']

