            free(salt);
            return NULL;  // Return null on failure
        }
    } else {
        printf("Failed to derive key and IV\n");
        if (pctx)
            EVP_PKEY_CTX_free(pctx);
        free(salt);
        return NULL;  // Return null on failure
    }

    /* Cleanup */
    OPENSSL_cleanse(&key, sizeof(key));
    OPENSSL_cleanse(&iv, sizeof(iv));
    EVP_PKEY_CTX_free(pctx);
    free(salt);
    *out_len = 0;  // Indicate success by setting out_len to zero

    return ctx;
}
