typedef struct CipherContext {
    EVP_CIPHER_CTX *ctx;
} CipherContext;

CipherContext* initializeAES128GCM(const char* passphrase) {
    CipherContext *cipher = malloc(sizeof(CipherContext));

    if(!RAND_bytes((unsigned char*)&cipher->ctx, sizeof(EVP_CIPHER_CTX))) {
        printf("Failed to generate random bytes\n");
        return NULL;
    }

    EVP_CIPHER_CTX_init(cipher->ctx);

    if(!EVP_EncryptInit_ex(cipher->ctx, EVP_aes_128_gcm(), NULL, (unsigned char*)passphrase, NULL)) {
        printf("Failed to initialize AES-128-GCM cipher\n");
        return NULL;
    }

    // Set the IV length dynamically based on data size being encrypted. 
    int ivLength;
    EVP_CIPHER_CTX_ctrl(cipher->ctx, EVP_CTRL_GCM_GET_IVLEN, sizeof(int), &ivLength);

    // Generate random IV and set it to the context. 
    unsigned char *randomIv = malloc(ivLength);
    if(!RAND_bytes(randomIv, ivLength)) {
        printf("Failed to generate random bytes\n");
        return NULL;
    }

    if(!EVP_EncryptInit_ex(cipher->ctx, NULL, NULL, NULL, randomIv)) {
        printf("Failed to set IV for AES-128-GCM cipher\n");
        return NULL;
    }

    free(randomIv);

    return cipher;
}
