```java
import java.util.*;
import java.util.concurrent.*;

public class DistributedCache {
    private static final int DEFAULT_MAX_CAPACITY = 100;

    private ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private PriorityQueue<CacheEntry> lruQueue = new PriorityQueue<>((a, b) -> a.lastAccessed.compareTo(b.lastAccessed));

    private int maxCapacity;
    private ScheduledExecutorService scheduler;
    private MetricsExporter exporter;

    public DistributedCache() {
        this.maxCapacity = DEFAULT_MAX_CAPACITY;
        this.scheduler = Executors.newSingleThreadScheduledExecutor();
        this.exporter = new MetricsExporter(this);

        scheduler.scheduleAtFixedRate(exporter::exportMetrics, 0, 60, TimeUnit.SECONDS);
    }

    public void put(String key, Object value, long expirationTime) {
        if (key == null || value == null || cache.size() >= maxCapacity) {
            throw new IllegalArgumentException();
        }

        CacheEntry entry = new CacheEntry(value, System.currentTimeMillis(), expirationTime);
        cache.put(key, entry);
        lruQueue.add(entry);
    }

    public Object get(String key) {
        if (key == null || !cache.containsKey(key)) {
            throw new IllegalArgumentException();
        }

        CacheEntry entry = cache.get(key);
        entry.lastAccessed = System.currentTimeMillis();
        lruQueue.remove(entry);  // O(n) operation, but can be improved with auxiliary data structure
        lruQueue.add(entry);

        return entry.value;
    }

    public void invalidate(String key) {
        if (key == null || !cache.containsKey(key)) {
            throw new IllegalArgumentException();
        }

        CacheEntry entry = cache.remove(key);
        lruQueue.remove(entry);  // O(n) operation, but can be improved with auxiliary data structure
    }

    public void setMaxCapacity(int maxCapacity) {
        if (maxCapacity <= 0 || maxCapacity < cache.size()) {
            throw new IllegalArgumentException();
        }

        this.maxCapacity = maxCapacity;
    }

    private static class CacheEntry {
        Object value;
        long lastAccessed;
        long expirationTime;

        public CacheEntry(Object value, long lastAccessed, long expirationTime) {
            this.value = value;
            this.lastAccessed = lastAccessed;
            this.expirationTime = expirationTime;
        }
    }

    private static class MetricsExporter {
        DistributedCache cache;

        public MetricsExporter(DistributedCache cache) {
            this.cache = cache;
        }

        public void exportMetrics() {
            // Implement logic here for calculating and exporting metrics
        }
    }
}
``` 
