// Function to generate random string
char* get_random_str(int length) {
    // OpenSSL library for secure random number generation
    unsigned char *buf = malloc(length);
    RAND_bytes(buf, length);

    // Convert bytes into hexadecimal and return
    char *rand_hex = malloc(length*2 + 1);
    for (int i = 0; i < length; ++i) {
        sprintf(&rand_hex[i*2], "%02x", buf[i]);
    }

