char* generate_new_url(const char *orig_url) {
    CURLU *curlu = curl_url(); // Initialize libcurl URL handle

    if (!curlu) {
        return NULL; // Error handling for failed initialization
    }

    // Parse the original URL
    CURLUcode rc = curl_url_set(curlu, CURLUPART_URL, orig_url, 0);
    if (rc != CURLUE_OK) {
        return NULL; // Error handling for failed parsing
    }

    char *hostname;
    rc = curl_url_get(curlu, CURLUPART_HOST, &hostname, 0);
    if (rc != CURLUE_OK) {
        return NULL; // Error handling for missing hostname
    }

    int hostlen = strlen(hostname);
    char *randomStr = get_random_str((hostlen > 3) ? hostlen - 3 : 0);

    // Append the random string to the query parameters
    char *query;
    curl_url_get(curlu, CURLUPART_QUERY, &query, CURLU_APPENDQUERY);
    if (strlen(query) + strlen(randomStr) > 100) { // If length exceeds 100 characters, truncate it
        query[97] = '\0';
    }

    strcat(query, randomStr);

    free(randomStr);

    char *new_url;
    curl_url_get(curlu, CURLUPART_URL, &new_url, 0); // Obtain the new URL

    curl_url_cleanup(curlu); // Clean up libcurl handle

    return new_url;
}
```
