['Here is an implementation that uses `pthread_mutex` for thread safety. It also includes functionality to track the number of valid entries and provides a safe way to clear the list. 

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Your structure members here
} NFAPI_CRC_INDICATION_PDU_T;

// Define your list node and its next pointer
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;
int count = 0;

void add_entry(NFAPI_CRC_INDICATION_PDU_T *data) {
    if (data == NULL) return;  // Handle potential null pointer dereferences.

    pthread_mutex_lock(&lock);   // Acquire lock before modifying list.

    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = head;
    head = newNode;

    count++;  // Increment the count of valid entries.

    pthread_mutex_unlock(&lock);   // Release lock after modifying list.
}

void clear_list() {
    pthread_mutex_lock(&lock);   // Acquire lock before modifying list.

    while (head != NULL) {
        Node *temp = head;
        head = head->next;

        free(temp->data);  // Free the memory allocated for data.
        free(temp);  // Free the node itself.
    }

    count = 0;   // Reset the valid entry count to zero.

    pthread_mutex_unlock(&lock);   // Release lock after modifying list.
}

int get_count() {
    int result;

    pthread_mutex_lock(&lock);  // Acquire lock before reading count.

    result = count;

    pthread_mutex_unlock(&lock);   // Release lock after reading count.

    return result;
}
```

Please note that this is a simple and basic implementation, in a real-world scenario you would probably want to handle errors more gracefully (like when `malloc` fails), use a more efficient data structure for your list, or consider using an existing library for thread safety. Also, please replace the placeholder typedef of NFAPI_CRC_INDICATION_PDU_T with actual definition as per your requirements.
