                                     const char* password, 
                                     const unsigned char* salt, 
                                     int numDigits, 
                                     int reuseFlag, 
                                     Config* config) {
    EVP_CIPHER_CTX* ctx = NULL;

    // Create a new cipher context if not set to reuse or there is none yet
    if (!reuseFlag || !ctx) {
        ctx = EVP_CIPHER_CTX_new();

        unsigned char key[SHA256_DIGEST_LENGTH];
        SHA256((const unsigned char*)password, strlen(password), key); // Derive encryption key from password

        if (salt) {
            unsigned char saltedKey[SHA256_DIGEST_LENGTH];
            SHA256(key, SHA256_DIGEST_LENGTH, saltedKey); // Salt the encryption key if provided

            EVP_EncryptInit(ctx, EVP_aes_256_cbc(), saltedKey, NULL); // Initialize the cipher with salted key and no IV
        } else {
            EVP_EncryptInit(ctx, EVP_aes_256_cbc(), key, NULL); // Initialize the cipher without salted key and no IV
        }

        const char* filetype = ".txt"; // Set predefined file type
        int extLen = strlen(filetype) + 1 + numDigits; 
        int filenameLen = strlen(filename);

        // Allocate memory for the new filename
        char* newFilename = malloc(filenameLen + extLen + 1);
        if (!newFilename) {
            EVP_CIPHER_CTX_free(ctx); 
            return NULL; 
        }

        // Modify the extension of filename and copy it into newFilename
        sprintf(newFilename, "%.*s%s", filenameLen - extLen, filename, filetype);

        // Rename the file using temporary directory specified in config
        char tmpPath[strlen(config->tmp_dir) + filenameLen + 1]; 
        sprintf(tmpPath, "%s/%s", config->tmp_dir, newFilename);

        if (rename(filename, tmpPath)) {
            free(newFilename);
            EVP_CIPHER_CTX_free(ctx); 
            return NULL; // Handle renaming error
        }

        free(newFilename);
    } else {
        ctx = reuseFlag;
    }

    // Write logs to logging directory specified in config
    FILE* logFile = fopen(config->log_dir, "a");
    if (logFile) {
        char logMsg[1024]; 
        sprintf(logMsg, "Encryption and renaming operation completed successfully for %s\n", filename);

