    char* tempFilePath;
    char* logDir;
} Config;

pthread_mutex_t resizeLock = PTHREAD_MUTEX_INITIALIZER;

void optimizeImageResize(char *srcImg, int targetWidth, int targetHeight, 
                        int qualitySetting, Config config) {
    pthread_mutex_lock(&resizeLock); // start of critical section

    ExceptionInfo exception;
    ImageInfo *imageInfo;
    Image *image, *resizedImage;

    MagickCoreGenesis(NULL, MagickFalse); 

    char tempImg[50]; // Temporary image file name
    sprintf(tempImg, "%s/%d.jpg", config.tempFilePath, getpid());

    // Copy source to temp location for resizing
    if (access(srcImg, F_OK) != -1) {
        FILE *source = fopen(srcImg, "rb");
        FILE *dest = fopen(tempImg, "wb");

        char ch;
        while((ch = fgetc(source)) != EOF)
            fputc(ch, dest);

        fclose(source);
        fclose(dest);
    } else {
        printf("Source file does not exist\n");
        pthread_mutex_unlock(&resizeLock); // end of critical section
        return;
    }

    // Initialize ImageMagick objects and apply resize operation 
    GetExceptionInfo(&exception);

    imageInfo = CloneImageInfo((ImageInfo *) NULL);
    strcpy(imageInfo->filename, tempImg);

    image = ReadImage(imageInfo, &exception);

    resizedImage = ResizeImage(image, targetWidth, targetHeight, (FilterTypes)qualitySetting, 1.0, &exception);

    if (resizedImage == (Image *) NULL) {
        CatchException(&exception);
        pthread_mutex_unlock(&resizeLock); // end of critical section
        return;
    }

    char logFile[50]; // Log file name for this resize operation
    sprintf(logFile, "%s/%d.txt", config.logDir, getpid());

    FILE *log = fopen(logFile, "w");
    if (log == NULL) {
        printf("Cannot open log file\n");
        pthread_mutex_unlock(&resizeLock); // end of critical section
        return;
    }

    char message[100]; 
    sprintf(message, "Resized image %s to (%dx%d) with quality setting %d", tempImg, targetWidth, targetHeight, qualitySetting);
    fprintf(log, "%s\n", message);

    fclose(log); // Closing log file

    writeImage(resizedImage, &exception);
    pthread_mutex_unlock(&resizeLock); // end of critical section

    DestroyImageInfo(imageInfo); 
    DestroyExceptionInfo(&exception);
}
```

