typedef struct TCP_CONNECTION_STATS {
    char ip_address[16];
    int port;
    double duration;
    long bytes_transferred;
    int error_code;
} TCP_CONNECTION_STATS;

typedef struct Node {
    TCP_CONNECTION_STATS stats;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int connectionCount = 0;

void addConnection(char* ip, int port) {
    pthread_mutex_lock(&lock);
    ++connectionCount;

    Node* newNode = (Node*)malloc(sizeof(Node));
    strcpy(newNode->stats.ip_address, ip);
    newNode->stats.port = port;
    newNode->next = head;

    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeConnection(char* ip) {
    if (head == NULL) return;

    if (strcmp(head->stats.ip_address, ip) == 0) {
        Node* temp = head;
        head = head->next;
        free(temp);

        pthread_mutex_lock(&lock);
        --connectionCount;
        pthread_mutex_unlock(&lock);
        return;
    }

    Node* prevNode = head;
    Node* nodeToRemove = head->next;

    while (nodeToRemove != NULL && strcmp(nodeToRemove->stats.ip_address, ip) != 0) {
        prevNode = nodeToRemove;
        nodeToRemove = nodeToRemove->next;
    }

    if (nodeToRemove == NULL) return;

    prevNode->next = nodeToRemove->next;
    free(nodeToRemove);

    pthread_mutex_lock(&lock);
    --connectionCount;
    pthread_mutex_unlock(&lock);
}

int getConnectionCount() {
    int count;

    pthread_mutex_lock(&lock);
    count = connectionCount;
    pthread_mutex_unlock(&lock);

    return count;
}
```
