    char IP_ADDRESS[16];
    int PORT_NUMBER;
    unsigned int CONNECTION_STATUS_FLAGS;
    int ACTIVE_FLAG;
} TCP_CONNECTION_RECORD;

typedef struct {
    pthread_mutex_t lock;  // Mutex for thread-safety
    TCP_CONNECTION_RECORD *connections;  // Array of connection records
    int connCount;  // Number of active connections
} ConnectionPool;

void initializeConnectionPool(ConnectionPool* pool) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->connCount = 0;
    pool->connections = (TCP_CONNECTION_RECORD*) malloc(sizeof(TCP_CONNECTION_RECORD) * 50000);
}

void addConnectionToPool(ConnectionPool* pool, TCP_CONNECTION_RECORD record) {
    pthread_mutex_lock(&pool->lock);

    if (pool->connCount < 50000) {
        pool->connections[pool->connCount] = record;
        pool->connCount++;
    } else {
        printf("Maximum connection limit reached!\n");
    }

    pthread_mutex_unlock(&pool->lock);
}

void removeConnectionFromPool(ConnectionPool* pool, int index) {
    if (index < pool->connCount) {
        pthread_mutex_lock(&pool->lock);

        // Shift all the subsequent records one position down
        for (int i = index; i < pool->connCount - 1; ++i) {
            pool->connections[i] = pool->connections[i + 1];
        }

        pool->connCount--;

        pthread_mutex_unlock(&pool->lock);
    } else {
        printf("Invalid connection index!\n");
    }
}

void freeConnectionPool(ConnectionPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->connections);
}
```
