['Here is a very basic implementation in C, not taking into account all your requirements due to complexity but it should give you a general idea of how you could begin to implement this:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pthread.h>

typedef struct {
    char *filename;
    pthread_mutex_t lock;
} FileData;

void* countLinesChars(void* arg) {
    FileData *file = (FileData*)arg;

    int fd = open(file->filename, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        pthread_mutex_unlock(&file->lock);
        return NULL;
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("Failed to get file size");
        pthread_mutex_unlock(&file->lock);
        close(fd);
        return NULL;
    }

    char *addr = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (addr == MAP_FAILED) {
        perror("Failed to memory map file");
        pthread_mutex_unlock(&file->lock);
        close(fd);
        return NULL;
    }

    size_t lines = 0, chars = 0;
    for (size_t i = 0; i < sb.st_size; ++i) {
        if (addr[i] == '\n')
            ++lines;
        else if (addr[i] != '\r')  // exclude newline characters, include everything else
            ++chars;
    }

    printf("File: %s\tLines: %zu\tCharacters: %zu\n", file->filename, lines, chars);

    munmap(addr, sb.st_size);
    close(fd);
    pthread_mutex_unlock(&file->lock);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2 || strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [options] file...\n", argv[0]);
        return 1;
    }

    pthread_t threads[argc - 1];
    FileData files[argc - 1];

    for (int i = 2; i < argc; ++i) {
        strcpy(files[i - 2].filename, argv[i]);
        pthread_mutex_init(&files[i - 2].lock, NULL);
        pthread_create(&threads[i - 2], NULL, countLinesChars, &files[i - 2]);
    }

    for (int i = 0; i < argc - 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

In this code, we first check if the user has provided any command line arguments or if they have requested help. If not, we display a usage message and terminate with an error code. If there are input files specified, we create a new thread for each one that will count the lines and characters in it.

We use `mmap` to map the file into memory rather than reading it line by line or character by character, which can be very slow and consume a lot of memory when dealing with large files. 

