```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

int* read_ints(size_t *len) {
    size_t cap = 10;  // initial buffer capacity
    int* buf = malloc(cap * sizeof(*buf));  // allocate initial memory
    if (!buf) { perror("malloc failed"); exit(EXIT_FAILURE); }

    int val, nread = 0;
    while (scanf("%d", &val) == 1) {
        buf[nread++] = val;  // add value to buffer

        if (nread == INT_MAX || nread >= cap) {  // check for overflow or capacity limit
            if (cap > INT_MAX / 2) { perror("array size limit exceeded"); exit(EXIT_FAILURE); }

            cap *= 2;  // double buffer size
            buf = realloc(buf, cap * sizeof(*buf));  // allocate more memory
            if (!buf) { perror("realloc failed"); exit(EXIT_FAILURE); }
        }
    }

    if (nread != EOF && ferror(stdin)) { perror("input error"); exit(EXIT_FAILURE); }

    *len = nread;  // update length of buffer
    return buf;
}

void find_max(int* arr, size_t len) {
    if (len == 0) { printf("No valid integers were found\n"); return; }

    int max = INT_MIN;  // start with smallest possible integer
    for (size_t i = 0; i < len; ++i) {
        if (arr[i] > max) { max = arr[i]; }
    }

    printf("The largest integer is %d\n", max);
}
```

