#include <string.h>

typedef struct {
    char* file_path;
    time_t last_modified_time;
    off_t file_size;
    mode_t access_rights;
    long metadata_versioning_info;
} FILE_SYSTEM_WATCHER;

typedef struct WatcherList {
    pthread_mutex_t mutex;
    int count;
    FILE_SYSTEM_WATCHER* watchers[10000];
} WatcherList;

static WatcherList list = {PTHREAD_MUTEX_INITIALIZER, 0};

int add_watcher(FILE_SYSTEM_WATCHER* watcher) {
    pthread_mutex_lock(&list.mutex);

    if (list.count == 10000) {
        syslog(LOG_ERR, "Too many files being watched");
        return -1;
    }

    list.watchers[list.count++] = watcher;

    pthread_mutex_unlock(&list.mutex);

    return 0;
}

int remove_watcher(FILE_SYSTEM_WATCHER* watcher) {
    pthread_mutex_lock(&list.mutex);

    for (int i = 0; i < list.count; ++i) {
        if (list.watchers[i] == watcher) {
            free(watcher->file_path); // you should add code to close the file here, or elsewhere
            memmove(&list.watchers[i], &list.watchers[i + 1], sizeof(*watcher) * (list.count - i - 1));
            list.count--;

            pthread_mutex_unlock(&list.mutex);

            return 0;
        }
    }

    syslog(LOG_ERR, "Watcher not found");

    pthread_mutex_unlock(&list.mutex);

    return -1;
}

void remove_all_watchers() {
    pthread_mutex_lock(&list.mutex);

    for (int i = 0; i < list.count; ++i) {
        free(list.watchers[i]->file_path); // you should add code to close the file here, or elsewhere
        free(list.watchers[i]);
    }

    list.count = 0;

    pthread_mutex_unlock(&list.mutex);
}
```
