// Global variables and lock for concurrent access.
#define M 1024 // Max connections. Adjust as required.
TCP_CONNECTION_RECORD* connectionRecords[M] = {NULL};
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int currentConnections = 0;

// Allocates memory for a new TCP_CONNECTION_RECORD.
TCP_CONNECTION_RECORD* createNewRecord(char* src, char* dst) {
    pthread_mutex_lock(&lock); // Lock before accessing shared data.

    if (currentConnections >= M) {
        fprintf(stderr, "Error: No available connections.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    TCP_CONNECTION_RECORD* newRecord = malloc(sizeof(TCP_CONNECTION_RECORD));

    if (newRecord == NULL) {
        fprintf(stderr, "Error: Could not allocate memory.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    newRecord->SRC_IP = strdup(src);
    newRecord->DST_IP = strdup(dst);
    newRecord->PACKET_COUNT = 0;

    connectionRecords[currentConnections++] = newRecord;
    pthread_mutex_unlock(&lock); // Unlock after accessing shared data.

    return newRecord;
}

// Thread function for simulating network traffic.
void* simulateTraffic(void* arg) {
    TCP_CONNECTION_RECORD* record = (TCP_CONNECTION_RECORD*)arg;
    while (1) { // Infinite loop to simulate continuous network traffic.
        pthread_mutex_lock(&lock);
        ++record->PACKET_COUNT;
        pthread_mutex_unlock(&lock);
        sleep(1); // Simulate delay before next packet.
    }
}
