['Here's a skeleton of how you might implement this in C using `pthread` library for threading, and some simple error checking mechanisms:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#define MAX_RETRIES 3
#define MIN_PORT 1024
#define MAX_PORT 65535

typedef struct {
    char macAddress[20];
    char ipAddress[16];
    int portNumber;
} NICPConfig;

NICPConfig* getNetworkConfiguration(); // this function is supposed to call the external API and handle errors

void* fetchAndCheckData(void *arg) {
    NICPConfig **ppArray = (NICPConfig **) arg;
    NICPConfig *config;
    int retries = 0;

    do {
        config = getNetworkConfiguration();
        if (!config && errno == ECONNREFUSED) {
            printf("Connection refused while fetching data. Retrying...\n");
            sleep(1); // Sleep for one second before retrying
            retries++;
        } else if (config->portNumber < MIN_PORT || config->portNumber > MAX_PORT) {
            printf("Invalid port number %d. Ignoring this result.\n", config->portNumber);
            free(config);
            config = NULL;
        } else {
            retries = 0; // Reset the retry count on success
        }
    } while (retries < MAX_RETRIES && !config);

    if (!config) {
        printf("Failed to fetch network configuration data after %d attempts.\n", MAX_RETRIES);
        *ppArray = NULL; // Indicating failure in the array
    } else {
        *ppArray = config; // Store the fetched data in the array
    }

    pthread_exit(NULL);
}

int main() {
    int size = 10; // suppose we are fetching 10 configurations for this example
    NICPConfig **configArray = malloc(size * sizeof(NICPConfig*));
    if (!configArray) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[size];
    for (int i = 0; i < size; ++i) {
        configArray[i] = NULL;

        int result = pthread_create(&threads[i], NULL, fetchAndCheckData, &configArray[i]);
        if (result != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    // Join all threads before printing the data
    for (int i = 0; i < size; ++i) {
        pthread_join(threads[i], NULL);

        if (configArray[i]) {
            printf("MAC: %s, IP: %s, Port: %d\n", configArray[i]->macAddress, configArray[i]->ipAddress, configArray[i]->portNumber);
            free(configArray[i]); // Don't forget to free the memory allocated for each configuration
        } else {
            printf("Failed to fetch data for index %d\n", i);
        }
    }

    free(configArray); // Free the array of pointers
    return 0;
}
```
In this code, a separate thread is created for each network configuration we want to fetch. If fetching data from the API fails or the port number is invalid, it retries up to three times before giving up and moving on to the next configuration. After all threads are done, main prints out the MAC Addresses, IP Addresses, and Port Numbers of the configurations that were successfully fetched.
']

