    for (int i = 0; i < 17; i++){
        if ((i+1) % 3 != 0 && isxdigit(mac[i]) == 0)
            return 0;
        if ((i+1) % 3 == 0 && mac[i] != ':')
            return 0;
    }
    return 1;
}

int validatePortNumber(int port){
