['```python
import re
import hashlib
from collections import defaultdict

def get_booknames(content):
    book_count = defaultdict(int)
    book_regexes = {
        "Genesis": r'\bgenesis\b',
        "Exodus": r'\bexodus\b',
        "Leviticus": r'\bleviticus\b',
        "Numbers": r'\bnumbers\b',
        "Deuteronomy": r'\bdeuteronomy\b'
    }

    for book, regex in book_regexes.items():
        matches = re.findall(regex, content, flags=re.IGNORECASE)
        book_count[book] += len(matches)

    return dict(book_count)

def calculate_md5_and_books(filepath):
    hash_md5 = hashlib.md5()

    with open(filepath,'rb') as f: 
        for chunk in iter(lambda: f.read(4096), b""): 
            hash_md5.update(chunk)

    content = open(filepath, 'r').read().lower()

    return {
        "hash": hash_md5.hexdigest(),
        "books": get_booknames(content)
    }
```
