    int cipher_len;
} CipherResult;

CipherResult* perform_op(char *data, int opcode) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Failed to create cipher context.\n");
        return NULL;
    }

    CipherResult *res = malloc(sizeof(*res));
    res->cipher = NULL;
    res->cipher_len = 0;

    if (opcode == 1) { //Encryption operation code
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, "secretkey", NULL)) {
            printf("Failed to initialize encryption.\n");
            goto cleanup;
        }

        int len = strlen(data);
        res->cipher = malloc(len + EVP_CIPHER_CTX_block_size(ctx));
        if (res->cipher == NULL) {
            printf("Failed to allocate memory for cipher.\n");
            goto cleanup;
        }

        int outl = 0;
        if (!EVP_EncryptUpdate(ctx, res->cipher, &outl, (unsigned char*)data, len)) {
            printf("Failed to encrypt data.\n");
            goto cleanup;
        }
        res->cipher_len += outl;
    } else if (opcode == 2) { //Decryption operation code
        if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, "secretkey", NULL)) {
            printf("Failed to initialize decryption.\n");
            goto cleanup;
        }

        int len = strlen(data);
        res->cipher = malloc(len + EVP_CIPHER_CTX_block_size(ctx));
        if (res->cipher == NULL) {
            printf("Failed to allocate memory for cipher.\n");
            goto cleanup;
        }

        int outl = 0;
        if (!EVP_DecryptUpdate(ctx, res->cipher, &outl, (unsigned char*)data, len)) {
            printf("Failed to decrypt data.\n");
            goto cleanup;
        }
        res->cipher_len += outl;
    } else {
        printf("Invalid operation code.\n");
        goto cleanup;
    }

    EVP_CIPHER_CTX_free(ctx);
    return res;

cleanup:
    if (res) free(res->cipher);
    free(res);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

void handle_request(int opcode, char *data) {
    tokyo::run([=] {
        CipherResult *result = perform_op(data, opcode);
        if (result == NULL) {
            printf("Failed to perform operation.\n");
        } else {
            // Process result...
            free(result->cipher);
            free(result);
        }
    });
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        printf("Usage: %s <operation code> <data>\n", argv[0]);
        return 1;
    }

    int opcode = atoi(argv[1]);
    char *data = argv[2];

    tokyo::init();
    handle_request(opcode, data);
    tokyo::runloop();

    return 0;
}
```
