void check_health(Operation operations[MAX_OPERATIONS]) {
    for (int i = 0; i < MAX_OPERATIONS; i++) {
        if (operations[i].timestamp > 0 && time(NULL) - operations[i].timestamp > LATENCY_THRESHOLD / 1000.0) {
            printf("Alert: Operation exceeded latency threshold in thread %ld\n", operations[i].thread_id);
        }
    }
}

void perform_op(Operation* operation, void (*crypto_func)(char*, EVP_CIPHER_CTX **)) {
    operation->timestamp = time(NULL);
