    printf("Finished operation in thread %ld\n", thread_id);
}

void *async_crypto(void* arg) {
    Operation* operation = (Operation*)arg;
    perform_op(operation, someCryptoFunc);
    return NULL;
}

int main(int argc, char *argv[]) {
    // Initialize OpenSSL library...

    tokio_runtime runtime;
    tokio_init_runtime(&runtime);

    Operation operations[MAX_OPERATIONS];

    for (int i = 0; i < MAX_OPERATIONS; i++) {
        // Prepare operation data...

        pthread_t thread;
        int result = pthread_create(&thread, NULL, async_crypto, &operations[i]);
        if (result != 0) {
            printf("Failed to create thread\n");
            return 1;
        }
