typedef struct FAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG; 
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        unsigned int CRCFLAG : 1; // assuming only one bit is used for flags
    } CRCI;
} FAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
unsigned int totalMemory = 0;
const unsigned int MAX_MEMORY_LIMIT = 1024*1024*50; // 50MB limit

FAPI_CRC_INDICATION_PDU_T* allocate(int N) {
    pthread_mutex_lock(&lock);

    if((totalMemory + N * sizeof(FAPI_CRC_INDICATION_PDU_T)) > MAX_MEMORY_LIMIT) {
        // handle out of memory conditions gracefully
        printf("Out of memory\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    totalMemory += N * sizeof(FAPI_CRC_INDICATION_PDU_T);
    FAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(FAPI_CRC_INDICATION_PDU_T));

    if(array == NULL) { 
        // out of memory condition
        printf("Out of memory\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    srand(time(NULL));

    for(int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();  // fill valid tags
        array[i].RNTI = rand();  // fill valid RNTI

        if(rand() % 2 == 0) { 
            // randomly set CRCFLAG
            array[i].CRCI.CRCFLAG = 0;  
        } else {
            array[i].CRCI.CRCFLAG = 1; 
        }
    }

    pthread_mutex_unlock(&lock);
    return array;
}
