['Here's how you might structure your code using the LibTIFF library. This example is fairly complex due to the amount of data that needs to be processed from each page and error handling, so please take it in context with the problem statement. 

This function does not handle the resolution units (like pixels per inch), which can be quite complex depending on the format. It also doesn't check if a color profile is undefined or unsupported, but you could add this functionality easily by looking up the color space and storing any data about it in the struct.

Also note that this function does not check for TIFF errors. In practice, you should do so to handle exceptions gracefully.

```c
#include <tiffio.h>
#include <stdlib.h>
#include <string.h>

typedef struct PageInfo {
    int compression;
    int samplesPerPixel;
    uint16* bitsPerSample;
} PageInfo;

PageInfo* processTIFF(const char* filename) {
    TIFF* tif = TIFFOpen(filename, "r");

    if (tif == NULL) {
        fprintf(stderr, "Failed to open TIFF file: %s\n", filename);
        return NULL;
    }

    uint32 width, height;
    int pageCount = -1; // Start at -1 because the first call will increment it to 0.
    PageInfo* pages;

    do {
        ++pageCount;
        pages = realloc(pages, (pageCount + 1) * sizeof(PageInfo));
        if (!TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width)) {
            fprintf(stderr, "Failed to get width of page %d\n", pageCount);
            free(pages);
            return NULL;
        }

        if (!TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height)) {
            fprintf(stderr, "Failed to get height of page %d\n", pageCount);
            free(pages);
            return NULL;
        }

        if (!TIFFGetField(tif, TIFFTAG_COMPRESSION, &pages[pageCount].compression)) {
            fprintf(stderr, "Failed to get compression method of page %d\n", pageCount);
            free(pages);
            return NULL;
        }

        if (!TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &pages[pageCount].samplesPerPixel)) {
            fprintf(stderr, "Failed to get samples per pixel of page %d\n", pageCount);
            free(pages);
            return NULL;
        }

        pages[pageCount].bitsPerSample = malloc(sizeof(uint16) * pages[pageCount].samplesPerPixel);
        if (!TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, pages[pageCount].bitsPerSample)) {
            fprintf(stderr, "Failed to get bits per sample of page %d\n", pageCount);
            free(pages);
            return NULL;
        }

    } while (TIFFReadDirectory(tif));

    TIFFClose(tif);
    return pages;
}
```

This function opens a multi-page TIFF file, reads each page's details into a struct and returns an array of these structs. The compression method, samples per pixel and bits per sample are stored in the struct for each page. 

Please note that this is a very simple implementation and does not cover every scenario or feature you might need (like different resolution units, unsupported features). It also doesn't check if a color profile is undefined or unsupported, but you could add this functionality easily by looking up the color space and storing any data about it in the struct.
']

