namespace po = boost::program_options;

int main(int argc, char *argv[]) {
    try {
        po::options_description desc("Allowed options");
        desc.add_options()
            ("help", "produce help message")
            ("metrics", po::value<std::vector<std::string>>(), "set metrics to extract")
            ("report", po::value<std::string>(), "set report file")
        ;

        po::variables_map vm;        
        po::store(po::parse_command_line(argc, argv, desc), vm);
        po::notify(vm);    

        if (vm.count("help")) {
            std::cout << desc << "\n";
            return 1;
        }

        if (vm.count("metrics")) {
            std::cout << "Metrics to extract: ";
            for(auto &m : vm["metrics"].as<std::vector<std::string>>())
