    for (size_t i = 0; i < size; ++i) {
        if (array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            // Shift all elements after this one forward by one position
            for (size_t j = i; j < size - 1; ++j) {
                array[j] = array[j + 1];
            }

            --size;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void serialize(const char* filename) {
