typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[33]; // Assuming 20-byte CRC and a null terminator.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray {
    pthread_mutex_t mutex;
    size_t count;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* entries;
} DynamicArray;

DynamicArray array;

void init_array(DynamicArray* a) {
    pthread_mutex_init(&a->mutex, NULL);
    a->count = 0;
    a->capacity = 16;
    a->entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * a->capacity);
}

void add_entry(DynamicArray* a, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&a->mutex);
    if (a->count == a->capacity) {
        a->capacity *= 2;
        a->entries = realloc(a->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T) * a->capacity);
    }
    a->entries[a->count++] = entry;
    pthread_mutex_unlock(&a->mutex);
}

char* md5(const char* str, int length) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, length, (unsigned char*)digest);    

    char *mdString = malloc(sizeof(char)* 33);
    for(int i = 0; i < 16; ++i)
         sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);

    return mdString;
}
```
