```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct LTE_RRC_CCO_MSG_T {
    int NAS_MESSAGE;
    int LOGICAL_CHANNEL_GROUP_ID;
    int CCO_INDICATION;
} LTE_RRC_CCO_MSG_T;

typedef struct DynamicArray {
    pthread_mutex_t lock;
    size_t count;
    size_t capacity;
    LTE_RRC_CCO_MSG_T **entries;
} DynamicArray;

DynamicArray *create() {
    DynamicArray *array = malloc(sizeof(*array));
    if (array == NULL) return NULL;

    array->count = 0;
    array->capacity = 16;
    array->entries = calloc(array->capacity, sizeof(LTE_RRC_CCO_MSG_T *));
    if (array->entries == NULL) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void insert(DynamicArray *array, LTE_RRC_CCO_MSG_T *value) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t newCapacity = array->capacity * 2;
        LTE_RRC_CCO_MSG_T **newEntries = realloc(array->entries, newCapacity * sizeof(LTE_RRC_CCO_MSG_T *));
        if (newEntries == NULL) {
            pthread_mutex_unlock(&array->lock);
            return;
        }

        array->capacity = newCapacity;
        array->entries = newEntries;
    }

    array->entries[array->count++] = value;
    pthread_mutex_unlock(&array->lock);
}
```
