struct SensorData { /* Define your sensor data structure */ };

class DataProcessor {
public:
    DataProcessor() : running_(true), worker_(&DataProcessor::worker, this) {}
    ~DataProcessor() { stop(); }

    void push(SensorData&& data) {
        std::unique_lock<std::mutex> lock(queueMutex_);
        queue_.push(std::move(data));
        lock.unlock();
        condVar_.notify_one();
    }

private:
    void worker() {
        while (running_) {
            std::unique_lock<std::mutex> lock(queueMutex_);
            condVar_.wait(lock, [this] { return !queue_.empty(); });

            // process data from the queue...

            if (!queue_.empty()) {
                auto& data = queue_.front();
                // ... handle data here
                queue_.pop();
            }
        }
    }

    void stop() {
        running_ = false;
        condVar_.notify_one();
        if (worker_.joinable()) worker_.join();
    }

private:
    std::atomic<bool> running_;
    std::thread worker_;
    std::mutex queueMutex_;
    std::condition_variable condVar_;
    std::queue<SensorData> queue_;
};
```
This code creates a DataProcessor class which receives data from sensors and processes it using another thread. To handle high-volume data, the processor uses a synchronization mechanism to ensure that the data is not lost during processing. This way, memory usage can be optimized for performance while minimizing disk I/O operations. However, this code does not include all functionalities you have mentioned like network disruption recovery, predefined thresholds and so on because these are quite complex features which would require a full-fledged implementation. 

