['Here's a Java implementation of your task:

```java
import org.apache.commons.codec.binary.Base64;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.net.InetAddress;
import java.security.MessageDigest;
import java.util.*;
import org.apache.log4j.Logger;

public class EncryptionUtils {
    private static final Logger logger = Logger.getLogger(EncryptionUtils.class);
    private static final String AES_ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final int KEY_LENGTH = 256; // in bits
    private static final int IV_LENGTH = 16;   // in bytes

    private Cipher cipher;
    private SecretKeySpec secretKeySpec;
    private IvParameterSpec ivParamSpec;

    public EncryptionUtils(String hostname, double threshold) {
        try {
            InetAddress address = InetAddress.getByName(hostname);
            String ipAddress = address.toString();

            byte[] key = getKeyFromHash(ipAddress, KEY_LENGTH);
            secretKeySpec = new SecretKeySpec(key, "AES");
            ivParamSpec = new IvParameterSpec(new byte[IV_LENGTH]); // Initialize IV with all zeros

            cipher = Cipher.getInstance(AES_ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParamSpec);
        } catch (Exception e) {
            logger.error("Error initializing EncryptionUtils", e);
            throw new RuntimeException(e); // Handle exception gracefully
        }
    }

    public byte[] encrypt(byte[] input) {
        try {
            return cipher.doFinal(input);
        } catch (Exception e) {
            logger.error("Error encrypting data", e);
            throw new RuntimeException(e); // Handle exception gracefully
        }
    }

    private byte[] getKeyFromHash(String input, int keyLengthInBits) throws Exception {
        MessageDigest hashFunction = MessageDigest.getInstance("SHA-1");
        byte[] bytes = hashFunction.digest(input.getBytes());

        // Truncate or pad the key to meet the required length
        int keyLengthInBytes = keyLengthInBits / 8;
        if (bytes.length > keyLengthInBytes) {
            return Arrays.copyOfRange(bytes, 0, keyLengthInBytes);
        } else if (bytes.length < keyLengthInBytes) {
            byte[] paddedKey = new byte[keyLengthInBytes];
            System.arraycopy(bytes, 0, paddedKey, 0, bytes.length);
            return paddedKey;
        } else {
            return bytes;
        }
    }

    // Method to rehash input string if the difference in percentage is greater than a threshold
    private boolean shouldRehash(String newInput, String oldInput, double threshold) {
        if (newInput == null || oldInput == null) {
            return false;
        }

        int length = Math.max(newInput.length(), oldInput.length());
        if (length == 0) {
            return false;
        }

        double diffCount = 0;
        for (int i = 0; i < newInput.length() && i < oldInput.length(); ++i) {
            if (newInput.charAt(i) != oldInput.charAt(i)) {
                ++diffCount;
            }
        }

        double diffPercentage = (diffCount / length) * 100;
        return diffPercentage > threshold;
    }
}
```
This Java code utilizes the Apache Commons Codec and Log4j libraries for base64 encoding, SHA-1 hashing, and logging respectively. It initiates a cipher instance with AES encryption and provides methods to encrypt data, derive keys from IP addresses using hash functions, and check for rehashing based on threshold percentage. The code also logs errors and handles exceptions gracefully.
']

