['Here's a simplified implementation of what you requested:

```csharp
using System;
using System.IO;
using System.Xml;
using System.Threading;
using System.Collections.Concurrent;
using System.Diagnostics;

public class XmlParser {
    private ConcurrentDictionary<string, string> cache = new ConcurrentDictionary<string, string>();
    private Stopwatch watch = new Stopwatch();
    private TimeSpan timeout = TimeSpan.FromSeconds(60);
    private int successCount = 0;
    private int failCount = 0;

    public XmlParser() {
        // initialize cache
    }

    public string ParseElement(string xmlPath, string elementName) {
        try {
            watch.Start();
            if (cache.TryGetValue(elementName, out var result)) {
                Interlocked.Increment(ref successCount);
                return result;
            }

            using (var reader = XmlReader.Create(xmlPath)) {
                while (reader.Read()) {
                    if (reader.NodeType == XmlNodeType.Element && reader.Name == elementName) {
                        var value = reader.ReadString();
                        cache[elementName] = value; // add to cache
                        Interlocked.Increment(ref successCount);
                        return value;
                    }
                }
            }
        } catch (Exception e) {
            watch.Stop();
            Interlocked.Increment(ref failCount);
            throw new Exception("Failed to parse element", e);
        } finally {
            watch.Stop();
        }

        if (watch.Elapsed > timeout) {
            // handle timeout, log or throw exception
        }

        Interlocked.Increment(ref failCount);
        return null;
    }

    public void ExportToFile(string filePath, bool isBinary = false) {
        try {
            using (var writer = isBinary ? new BinaryWriter(File.OpenWrite(filePath)) : new StreamWriter(filePath)) {
                foreach (var kvp in cache) {
                    if (isBinary) {
                        var bytes = System.Text.Encoding.UTF8.GetBytes(kvp.Value);
                        writer.Write(bytes);
                    } else {
                        writer.WriteLine($"{kvp.Key}: {kvp.Value}");
                    }
                }
            }
        } catch (Exception e) {
            // handle exception, log or throw error
        }
    }

    public void LogStats() {
        Console.WriteLine($"Successful operations: {successCount}, Failed operations: {failCount}");
    }
}
```
