// Forward declarations
void log_error(const char* message);
char* compress_string(char* str, int compressionFlag);
int write_to_file(FILE* file, const char* str, size_t len);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Lock for thread safety

const char* appendSlashAndNullTerminateString(char *str, size_t limit, FILE* file, int compressionFlag) {
    if (!str || limit < 0 || !file) return NULL;  // Null pointer or negative size limit check

    pthread_mutex_lock(&lock);  // Lock for thread safety

    size_t len = strlen(str);  
    if (len >= limit) {         // Size limit check
        log_error("String exceeded the size limit");
        pthread_mutex_unlock(&lock);  
        return NULL;
    }

    // Append slash and null-terminate string
    str[len++] = '/';
    str[len] = '\0'; 

    char* compressedStr = compress_string(str, compressionFlag);
    if (compressedStr == NULL) {
        log_error("Compression failed");
        pthread_mutex_unlock(&lock);  
        return NULL;
    }

    // Write to file
    size_t writeLen = strlen(compressedStr); 
    int result = write_to_file(file, compressedStr, writeLen);

    if (result == -1) {
        log_error("File write failed");
        pthread_mutex_unlock(&lock);  
        return NULL;
    }

    free(compressedStr);  // Free memory

    pthread_mutex_unlock(&lock);  // Unlock for thread safety

    return str;
}
```
