#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    unsigned char *key;
    unsigned char iv[16];
} EncryptionResult;

EncryptionResult *encrypt_password(const char *password, const unsigned char *salt) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    // Derive key using PBKDF2 and HMAC-SHA256
    unsigned char *key = malloc(32);  // AES-256 uses a 256-bit key
    PKCS5_PBKDF2_HMAC_SHA1((const void *)password, strlen(password), salt, 8 /*salt length*/, 10000 /*iterations*/, 32, key);

    // Generate random IV
    unsigned char iv[16];
    RAND_bytes(iv, sizeof(iv));

    // Initialize cipher context for encryption
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Perform encryption here...

    EncryptionResult *result = malloc(sizeof(*result));
    result->key = key;
    memcpy(result->iv, iv, sizeof(iv));
    return result;
}

void cleanup_encryption(EncryptionResult *result) {
    free(result->key);
    free(result);
}
```
