// Function to safely close all open watchers
void closeAllOpenWatchers() {
    pthread_mutex_lock(&watcherList.lock);
    for (int i = 0; i < watcherList.count; ++i) {
        if(watcherList.items[i]->path != NULL){
            free(watcherList.items[i]->path); // Free path string memory
        }
        free(watcherList.items[i]); // Free watcher structure memory
    }
    pthread_mutex_unlock(&watcherList.lock);
}

// Function to add a new watcher to the list
void addWatcher(FILE_SYSTEM_WATCHER* watcher) {
    if (watcher == NULL) return; // Handle null pointer dereference gracefully

    pthread_mutex_lock(&watcherList.lock);
    watcherList.items = realloc(watcherList.items, sizeof(FILE_SYSTEM_WATCHER*) * ++watcherList.count); 
    watcherList.items[watcherList.count - 1] = watcher;
    pthread_mutex_unlock(&watcherList.lock);
}
