#include <openssl/ssl.h>
#include <openssl/err.h>

// Initialize SSL context
SSL_CTX *init_server_ctx(void) {
    const SSL_METHOD *method;
    SSL_CTX *ctx;

    OpenSSL_add_all_algorithms();  /* Load cryptos, err */
    SSL_load_error_strings();   /* Bring in and register error messages */
    method = TLSv1_2_server_method();  /* Create new client-side SSL/TLS context */
    ctx = SSL_CTX_new(method);   /* Create new context */

    if (ctx == NULL) {
        ERR_print_errors_fp(stderr);
        abort();
    }

    // Set session cache mode and cipher suite
    SSL_CTX_set_session_cache_mode(ctx, SSL_SESS_CACHE_CLIENT | SSL_SESS_CACHE_NO_INTERNAL);
    SSL_CTX_set_cipher_list(ctx, "HIGH:MEDIUM:+RSA:+AESGCM:+ECDHE-RSA:+DHE-RSA");

    return ctx;
}

// Establish TLS connection
SSL *tls_connection(SSL_CTX* ctx, int client) {
    SSL *ssl = SSL_new(ctx);   /* create new SSL connection state */

    if ( ssl == NULL ) {
        ERR_print_errors_fp(stderr);
        abort();
    }

    // Set the file descriptor for the connection
    SSL_set_fd(ssl, client);

    if (SSL_accept(ssl) <= 0) {   /* perform TLS/SSL server-side handshake */
        ERR_print_errors_fp(stderr);
        abort();
    } else {
        printf("Handshake successful\n");
    }

    return ssl;
}

// Close TLS connection
void close_connection(SSL *ssl) {
    SSL_free(ssl);   /* release connection state */
}
```

This example demonstrates basic functionality for setting up a server-side SSL context, establishing a TLS connection, and then closing the connection. Please note that this code does not handle errors and potential resource leaks in case of high load conditions or other unexpected circumstances. Implementing proper error handling is crucial when writing production code to ensure smooth operation under different conditions.
