    const EVP_CIPHER *cipher = EVP_aes_128_gcm();

    if(!(ctx = EVP_CIPHER_CTX_new())) {
        // Handle error here.
    }

    // Generate key using PBKDF2 with 10,000 iterations and SHA-512 as the hash function.
    PKCS5_PBKDF2_HMAC(passphrase, -1, NULL, 0, 10000, EVP_sha512(), 16, key);

    // Generate a random IV for each encryption operation to ensure uniqueness.
    RAND_bytes(iv, sizeof(iv));
    ivlen = EVP_CIPHER_CTX_iv_length(ctx);
    memcpy(iv, iv + (sizeof(iv) - ivlen), ivlen);

    // Initialize cipher context with key and IV.
    if(!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        // Handle error here.
    }

    return ctx;
}
```
