```C
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>

typedef struct {
    char *path;
    time_t lastModified;
    off_t size;
    mode_t permissions;
} FILE_SYSTEM_WATCHER;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int watcherCount = 0;
FILE_SYSTEM_WATCHER *watchers[10000];

void addWatcher(char *path) {
    pthread_mutex_lock(&lock);

    FILE_SYSTEM_WATCHER *newWatcher = malloc(sizeof(FILE_SYSTEM_WATCHER));

    if (newWatcher == NULL) {
        // Handle error
        return;
    }

    newWatcher->path = strdup(path);

    if (stat(path, &buf) == 0) {
        newWatcher->lastModified = buf.st_mtime;
        newWatcher->size = buf.st_size;
        newWatcher->permissions = buf.st_mode;
    } else {
        // Handle error
        free(newWatcher);
        pthread_mutex_unlock(&lock);
        return;
    }

    watchers[watcherCount++] = newWatcher;
    printf("Added watcher for %s\n", path);

    pthread_mutex_unlock(&lock);
}

void removeAllWatchers() {
    pthread_mutex_lock(&lock);

    int i;
    for (i = 0; i < watcherCount; ++i) {
        free(watchers[i]->path);
        free(watchers[i]);
    }

    watcherCount = 0;

    printf("Removed all watchers\n");

    pthread_mutex_unlock(&lock);
}
```
Please note that this is a very simplistic solution and doesn't cover all the requirements you have mentioned in detail. For example, it doesn't take into account symbolic links, doesn't handle file changes during the watch period, doesn't provide detailed logging, etc. Please refer to Linux System Programming by Robert Love for more advanced topic.
