['Here is a simple implementation of your requirements using C99 standard with POSIX Threads (pthread) library for thread safety. The code does not include the actual frame insertion/removal logic due to its complexity, but it provides a general structure that should help you build upon. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct MAC_RX_FRAME_T {
    int MAC_RLC_AMSDU_INFO_TAG;
    int RLC_SN;
    char MAC_RX_INDICATION_INFO_TAG;
} MAC_RX_FRAME_T;

typedef struct FrameArray {
    MAC_RX_FRAME_T *frames;
    size_t count; // Current number of frames
    size_t capacity; // Maximum allocated size
    pthread_mutex_t mutex;
} FrameArray;

int initFrame(MAC_RX_FRAME_T* frame) {
    srand(time(NULL));
    frame->MAC_RLC_AMSDU_INFO_TAG = rand();
    frame->RLC_SN = rand();
    frame->MAC_RX_INDICATION_INFO_TAG = (char)(rand() % 256);
    return 0;
}

int initFrameArray(FrameArray* array, size_t initialSize) {
    array->frames = malloc(initialSize * sizeof(MAC_RX_FRAME_T));
    if (array->frames == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    array->count = 0;
    array->capacity = initialSize;
    pthread_mutex_init(&(array->mutex), NULL);

    for (size_t i = 0; i < initialSize; ++i) {
        initFrame(&(array->frames[i]));
        ++(array->count);
    }

    return 0;
}

int insertFrame(FrameArray* array, MAC_RX_FRAME_T frame) {
    pthread_mutex_lock(&(array->mutex));

    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        MAC_RX_FRAME_T* tempFrames = realloc(array->frames, newCapacity * sizeof(MAC_RX_FRAME_T));
        if (tempFrames == NULL) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&(array->mutex));
            return -1;
        }

        array->frames = tempFrames;
        array->capacity = newCapacity;
    }

    array->frames[array->count] = frame;
    ++(array->count);

    pthread_mutex_unlock(&(array->mutex));
    return 0;
}

int removeFrame(FrameArray* array, size_t index) {
    pthread_mutex_lock(&(array->mutex));

    if (index >= array->count) {
        perror("Index out of bounds");
        pthread_mutex_unlock(&(array->mutex));
        return -1;
    }

    --(array->count);
    for (size_t i = index; i < array->count; ++i) {
        array->frames[i] = array->frames[i + 1];
    }

    pthread_mutex_unlock(&(array->mutex));
    return 0;
}
```

This code creates a frame structure and an array of frames, each with unique MAC_RLC_AMSDU_INFO_TAG, RLC_SN, and MAC_RX_INDICATION_INFO_TAG. The function `initFrameArray` initializes the array and fills it with frames. `insertFrame` adds a frame to the end of the array, resizing if necessary. `removeFrame` removes a frame from the given index, shifting all subsequent frames up. Thread safety is achieved by locking a mutex whenever the array is modified.
']

