#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <json-c/json.h>

// Define the log levels
enum LogLevel {
    INFO,
    ERROR
};

typedef struct LogEntry {
    enum LogLevel level;
    char* timestamp;
    char* message;
    json_object* metadata;
    char* context;
} LogEntry;

// Structure to hold log entries and their count
typedef struct LogQueue {
    int count;
    LogEntry** logs;
    pthread_mutex_t mutex;
} LogQueue;

// Function pointer for external logging service
typedef void (*LoggingService)(json_object*);

void sendToExternalService(LoggingService service, LogEntry* entry) {
    json_object* logObject = json_object_new_object();

    json_object_object_add(logObject, "timestamp", json_object_new_string(entry->timestamp));
    json_object_object_add(logObject, "level", json_object_new_int(entry->level));
    json_object_object_add(logObject, "message", json_object_new_string(entry->message));
    json_object_object_add(logObject, "metadata", entry->metadata);

    if (entry->context) {
        json_object_object_add(logObject, "context", json_object_new_string(entry->context));
    }

    service(logObject);
}

void addToQueue(LogQueue* queue, LogEntry* entry) {
    pthread_mutex_lock(&queue->mutex);

    // Reallocate and copy existing logs
    queue->count++;
    queue->logs = realloc(queue->logs, sizeof(LogEntry*) * queue->count);
    queue->logs[queue->count - 1] = entry;

    pthread_mutex_unlock(&queue->mutex);
}

void sendQueuedLogs(LogQueue* queue, LoggingService service) {
    while (queue->count > 0) {
        // Lock mutex to prevent concurrent modifications
        pthread_mutex_lock(&queue->mutex);

        if (queue->count == 0) {
            break;
        }

        LogEntry* entry = queue->logs[--queue->count];
        sendToExternalService(service, entry);

        free(entry->timestamp);
        json_object_put(entry->metadata);
        free(entry->message);
        if (entry->context) {
            free(entry->context);
        }
        free(entry);

        pthread_mutex_unlock(&queue->mutex);
    }
}

void logMessage(LogQueue* queue, LoggingService service, enum LogLevel level, const char* message, json_object* metadata, const char* context) {
    // Validate presence and correctness of required fields
    if (!message || !metadata || strcmp(json_object_to_json_string(metadata), "{}")) {
        return;
    }

    LogEntry* entry = malloc(sizeof(LogEntry));
    entry->level = level;

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char* timestamp = asctime(&tm);
    timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline character
    entry->timestamp = malloc((strlen(timestamp) + 1) * sizeof(char));
    strcpy(entry->timestamp, timestamp);

    entry->message = malloc((strlen(message) + 1) * sizeof(char));
    strcpy(entry->message, message);

    if (context) {
        entry->context = malloc((strlen(context) + 1) * sizeof(char));
        strcpy(entry->context, context);
    } else {
        entry->context = NULL;
    }

    entry->metadata = json_object_get(metadata);  // Increment reference count

    addToQueue(queue, entry);
}
```
