    char* level;
    char* message;
    json_object* metadata;
    char* context;
} typedef LogEntry;

/* Function to validate the presence and correctness of required fields */
int validateFields(LogEntry entry) {
    if (!entry.timestamp || !isdigit(*entry.timestamp)) return 0; /* timestamp should be a number */
    if (!entry.level || (strcmp(entry.level, log_levels[0]) && strcmp(entry.level, log_levels[1]))) return 0;
    if (!entry.message) return 0;
    if (!json_object_is_type(entry.metadata, json_type_object)) return 0; /* metadata must be a valid JSON object */
    return 1;
}

/* Function to send logs in JSON format via external API */
size_t writeCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((struct string *)userp)->len += size * nmemb;
    ((struct string *)userp)->ptr = realloc(((struct string *)userp)->ptr, ((struct string *)userp)->len+1);
    if (((struct string *)userp)->ptr == NULL) {
        fprintf(stderr, "Not enough memory (realloc returned NULL)\n");
        return 0;
    }
    memcpy(&(((struct string *)userp)->ptr[((struct string *)userp)->len - size*nmemb]), contents, size * nmemb);
    ((char *)((struct string *)userp)->ptr)[((struct string *)userp)->len - 1] = 0;
    return size * nmemb;
}

int sendLogsToAPI(CURL* curl, char* url, LogEntry entry) {
    struct string s = {0};
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

    /* Convert LogEntry to JSON string */
    char* json = json_object_to_json_string(json_object_new_object());

    struct curl_slist *headers=NULL; 
    headers = curl_slist_append(headers, "Content-Type: application/json");

    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);

    /* Send request and check response */
    int res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to send logs: %s\n", curl_easy_strerror(res));
        return 0;
    } else {
        printf("Log sent successfully\n");
    }

    free(json);
    return res;
}
```
