typedef struct NICP_config {
    unsigned char MAC[6];
    unsigned int IP;
    unsigned short Port;
} NICP_config_t;

static inline int validate_IP(unsigned int ip, unsigned int base_ip, unsigned int subnet) {
    return (((base_ip & ~subnet) ^ (ip & ~subnet)) == 0);
}

NICP_config_t *initialize_nicp_configurations(FILE *fp, int max_configs, 
                                             unsigned int base_ip, unsigned int subnet, 
                                             unsigned short min_port, unsigned short max_port) {
    // Read the configuration file for maximum configurations
    if (fp == NULL || fscanf(fp, "%d", &max_configs) != 1 || max_configs <= 0) {
        fprintf(stderr, "Failed to read config file or invalid value\n");
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Initialize the random number generator with current time

    NICP_config_t *arr = malloc(sizeof(NICP_config_t)*max_configs);
    if (arr == NULL) {
        fprintf(stderr, "Failed to allocate memory for configurations\n");
        return NULL;
    }

    // Initialize all MAC addresses and port numbers randomly. 
    for (int i = 0; i < max_configs; ++i) {
        arr[i].Port = rand() % ((max_port + 1) - min_port) + min_port;

        // Generate a unique MAC address and an IP within the valid range
        unsigned int ip;
        do {
            for (int j = 0; j < 6; ++j) 
                arr[i].MAC[j] = rand() % 256;

            // Ensure that the MAC address is not a multicast address or unspecified
            arr[i].MAC[0] &= ~1;   // Clear the first bit to make it unicast
            arr[i].MAC[0] |= 2;    // Set the second bit to make it globally unique

            ip = rand() % ((base_ip + ~subnet) - (base_ip & ~subnet)) + (base_ip & ~subnet);
        } while (!validate_IP(ip, base_ip, subnet)); // Validate IP address before using it.
        arr[i].IP = ip;
    }

    return arr;
}
``` 
