```c
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <jansson.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[16];  // AES-128 key size is 16 bytes
} CipherContext;

// Function to initialize the cipher context with a given passphrase.
CipherContext* init_cipher(const char *passphrase) {
    CipherContext *ctx = malloc(sizeof(CipherContext));
    if (ctx == NULL) return NULL;

    // Derive key from the passphrase using PBKDF2 with 1000 iterations and SHA-256.
    PKCS5_PBKDF2_HMAC_SHA1(passphrase, strlen(passphrase), NULL, 0, 1000, 16, ctx->key);

    // Initialize AES-GCM cipher in encrypt mode.
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_128_gcm(), NULL, key, iv)) {
        free(ctx);
        return NULL;
    }

    // Set IV length based on data size.
    int iv_len = EVP_CIPHER_CTX_iv_length(ctx->ctx);
    unsigned char *iv = malloc(iv_len);
    RAND_bytes(iv, iv_len);  // Generate a new IV for each encryption operation.
    EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, key, iv);

    free(iv);
    return ctx;
}

// Function to encrypt data with the cipher context and return base64-encoded output.
char* encrypt_data(CipherContext *ctx, const unsigned char *plaintext, int plaintext_len) {
    // Allocate buffer for ciphertext.
    int ciphertext_len;
    unsigned char *ciphertext = malloc(plaintext_len + EVP_MAX_BLOCK_LENGTH);

    // Encrypt the data.
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) {
        free(ciphertext);
        return NULL;
    }

    // Finalize encryption and append tag to the ciphertext.
    unsigned char tag[16];  // Tag size is 16 bytes for AES-GCM.
    if (!EVP_EncryptFinal_ex(ctx->ctx, ciphertext + ciphertext_len, &ciphertext_len) ||
        !EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, 16, tag)) {
        free(ciphertext);
        return NULL;
    }

    // Convert ciphertext to base64-encoded string.
    char *base64 = malloc(EVP_EncodeBlock(NULL, ciphertext, ciphertext_len + sizeof(tag)) + 1);
    EVP_EncodeBlock((unsigned char*)base64, ciphertext, ciphertext_len + sizeof(tag));

    // Include metadata in the resulting ciphertext.
    json_t *metadata = json_pack("{s:i, s:s}", "version", 1, "algorithm", "AES-GCM");
    if (metadata == NULL) {
        free(base64);
        return NULL;
    }

    char *json_str = json_dumps(metadata, JSON_COMPACT);
    strcat(base64, "__METADATA__");  // Use this prefix to separate metadata from ciphertext.
    strcat(base64, json_str);

    free(json_str);
    json_decref(metadata);

    return base64;
}

// Function to clean up and release resources.
void cleanup_cipher(CipherContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
```

