typedef struct {
    int CONN_ID;
    size_t BYTES_RECEIVED;
    size_t BYTES_SENT;
    time_t LAST_ACTIVE_TIMESTAMP;
    float THROUGHPUT;
    double ROUND_TRIP_TIME;
    double LATENCY;
} TCP_CONNECTION_STATS;

typedef struct {
    pthread_mutex_t lock;
    int conn_count;
    TCP_CONNECTION_STATS** array;
} ArrayManager;

void initialize(ArrayManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->conn_count = 0;
    manager->array = malloc(5000 * sizeof(TCP_CONNECTION_STATS*));
}

void insert(ArrayManager* manager, TCP_CONNECTION_STATS* stats) {
    pthread_mutex_lock(&manager->lock);
    manager->array[manager->conn_count++] = stats;
    pthread_mutex_unlock(&manager->lock);
}

void delete(ArrayManager* manager, int CONN_ID) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->conn_count; ++i) {
        if (manager->array[i]->CONN_ID == CONN_ID) {
            free(manager->array[i]);
            manager->array[i] = NULL;
            for (int j = i; j < manager->conn_count - 1; ++j) {
                manager->array[j] = manager->array[j + 1];
            }
            --manager->conn_count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void serialize(ArrayManager* manager, const char* filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    write(fd, manager->array, manager->conn_count * sizeof(TCP_CONNECTION_STATS));
    close(fd);
}

void deserialize(ArrayManager* manager, const char* filename) {
    int fd = open(filename, O_RDONLY);
    struct stat st;
    fstat(fd, &st);

    while (read(fd, manager->array + manager->conn_count++, sizeof(TCP_CONNECTION_STATS)) > 0) {}
    close(fd);
}
```
This code uses a simple linear search to delete entries, which is not very efficient. A more suitable data structure for managing connections would be a hash table or a balanced tree for faster lookup and deletion times. Please also note that this code doesn't cover error checking in system calls (such as malloc or open), which are left out for brevity.
