// Custom Memory Pool
typedef struct {
    void *start_address;
    size_t total_size;
    size_t used_size;
} MemPool;

void create_pool(MemPool *pool, size_t size) {
    pool->start_address = malloc(size);
    pool->total_size = size;
    pool->used_size = 0;
}

// Arena Allocation
typedef struct {
    void *current;
    size_t total_size;
} MemArena;

void create_arena(MemArena *arena, size_t size) {
    arena->current = malloc(size);
    arena->total_size = size;
}

// Memory Pool Allocator
void *pool_allocate(MemPool *pool, size_t size) {
    if (pool->used_size + size > pool->total_size) {
        printf("Error: Out of memory in the pool\n");
        return NULL;
    } else {
        void *ptr = (char *)pool->start_address + pool->used_size;
        pool->used_size += size;
        return ptr;
    }
}

// Arena Allocator
void *arena_allocate(MemArena *arena, size_t size) {
    void *ptr = arena->current;
    if ((char *)arena->current + size > (char *)arena->total_size) {
        printf("Error: Out of memory in the arena\n");
        return NULL;
    } else {
        arena->current = (char *)arena->current + size;
        return ptr;
    }
}

