void processData(char* inputFile, char* outputFile, char* startDate, char* endDate, int minDuration, double threshold) {
    FILE *file = fopen(inputFile, "r");
    if (file == NULL) {
        printf("Failed to open file %s\n", inputFile);
        return;
    }

    // Count the number of lines in the file
    int numLines = 0;
    char ch;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') numLines++;
    }
    rewind(file);  // Reset the file pointer to the start of the file

    Interaction* interactions = malloc(numLines * sizeof(Interaction));

    // Read all the interactions from the file
    for (int i = 0; i < numLines; i++) {
        fscanf(file, "%s %d", interactions[i].date, &interactions[i].duration);
    }
    fclose(file);

    FILE *output = fopen(outputFile, "w");
    if (output == NULL) {
        printf("Failed to open file %s\n", outputFile);
        free(interactions);
        return;
    }

    // Process interactions and write recommendations
    int count = 0;
    double totalDuration = 0.0;
    for (int i = 0; i < numLines; i++) {
        if ((strcmp(interactions[i].date, startDate) >= 0 && strcmp(interactions[i].date, endDate) <= 0) 
            && interactions[i].duration >= minDuration) {

            count++;
            totalDuration += (double)interactions[i].duration;
        }
    }

    if (count > 0) {
        double avgSessionDuration = totalDuration / count;
        fprintf(output, "Average session duration: %.2f\n", avgSessionDuration);

        // Generate recommendations for users with scores above the threshold
        if (avgSessionDuration > threshold) {
            fprintf(output, "User recommendation based on average session duration.\n");
        } else {
            fprintf(output, "No user recommendation.\n");
        }
    } else {
        fprintf(output, "No interactions found within the specified date range and minimum session duration threshold.\n");
    }

    free(interactions);
    fclose(output);
}
