```C
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
} log_level;

log_level severity = ERROR; // Default level

void setSeverityFromEnv() {
    char* envVar = getenv("LOG_SEVERITY");
    if (envVar != NULL) {
        int level = atoi(envVar);
        if (DEBUG <= level && level <= ERROR) {
            severity = level;
        }
    }
}

time_t lastLogTime = 0;
int logCount = 0;
const int maxPerMinute = 5;

void rateLimit() {
    time_t currentTime = time(NULL);
    if (currentTime - lastLogTime >= 60) {
        lastLogTime = currentTime;
        logCount = 0;
    } else {
        logCount++;
        if (logCount > maxPerMinute) {
            printf("Rate limit exceeded. Please wait before logging again.\n");
            exit(1);
        }
    }
}

void my_log(log_level level, const char* fmt, ...) {
    va_list args;
    va_start (args, fmt);

    setSeverityFromEnv();

    rateLimit();

    if (severity <= level) {
        vprintf (fmt, args);
    }

    va_end (args);
}
```
The `my_log` function takes a log level and a format string similar to `printf`. The severity is determined by the LOG_SEVERITY environment variable which must be set before running the program. If the log count exceeds 5 in one minute, it will print a warning message and exit.

