public IDataReader GetPaginatedResults(string query, IDbConnection connection, int pageNumber, int pageSize, string sortBy)
{
    try
    {
        if (pageNumber < 1 || pageSize <= 0)
        {
            throw new ArgumentException("Invalid pagination parameters");
        }

        var startIndex = (pageNumber - 1) * pageSize;
        var endIndex = pageNumber * pageSize;

        var commandText = $"SELECT * FROM ({query}) AS subQuery ORDER BY {sortBy} OFFSET {startIndex} ROWS FETCH NEXT {pageSize} ROWS ONLY";
        var stopwatch = Stopwatch.StartNew();

        using (var command = connection.CreateCommand())
        {
            command.CommandText = commandText;
            command.CommandType = CommandType.Text;

            if (connection.State != ConnectionState.Open)
                connection.Open();

            var reader = command.ExecuteReader();
            stopwatch.Stop();

            Console.WriteLine($"Executed query: {commandText}");
            Console.WriteLine($"Execution time: {stopwatch.ElapsedMilliseconds} ms");

            return reader;
        }
    }
    catch (SqlException e)
    {
        // Handle SQL exception, such as syntax error or invalid column name
        throw new Exception("An error occurred while retrieving data", e);
    }
    catch (ArgumentException e)
    {
        // Handle invalid pagination parameters
