#include <stdio.h>
#include <ctype.h>
#include <string.h>
#include <assert.h>
#include <errno.h>

void *xmalloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && size != 0) {
        fprintf(stderr, "Out of memory\n");
        abort();
    }
    return ptr;
}

char* processString(const char *str, size_t limit, FILE *fp, int uppercaseFlag) {
    assert(limit > 0);
    if (strlen(str) > limit) {
        fprintf(stderr, "Warning: input string exceeds the size limit\n");
    }

    char *processedStr = xmalloc(limit + 2); // +1 for null terminator and optional slash
    strncpy(processedStr, str, limit); 
    processedStr[limit] = '\0';

    if (fp != NULL) {
        int c;
        while ((c = fgetc(fp)) != EOF && isspace(c));

        // Check for error after first non-whitespace character was read.
        if (ferror(fp)) {
            perror("Error reading from file");
            return NULL;
        }

        clearerr(fp); 
    } else {
        fprintf(stderr, "Warning: invalid file pointer\n");
    }

    if (uppercaseFlag) {
        for(int i = 0; processedStr[i]; i++){
            processedStr[i] = toupper((unsigned char)processedStr[i]);
        }
    }

    if (strlen(processedStr) < limit) {
        strcat(processedStr, "/");
    }

    return processedStr;
}
```

