["Here is a sample solution using Node.js's built-in `fs` module to asynchronously read files from a directory, with throttling, retry mechanism, error handling, performance optimizations, file type filtering, absolute path resolution, logging for each file read operation and detailed error message. 

```javascript
const fs = require('fs');
const path = require('path');
const util = require('util');
const readdirPromise = util.promisify(fs.readdir);
const readFilePromise = util.promisify(fs.readFile);
let concurrency = 0;

async function processFilesInDirectory(directoryPath, pattern) {
  let filesContent = '';

  try {
    directoryPath = path.resolve(directoryPath); // resolve relative paths to absolute ones

    const fileNames = await readdirPromise(directoryPath);

    for (let i = 0; i < Math.min(fileNames.length, 10000); i++) {
      if (!pattern || !new RegExp(pattern).test(fileNames[i])) {
        let fileContent = '';

        while (concurrency >= 10) { // throttle concurrent operations to 10
          await new Promise(resolve => setTimeout(resolve, 5));
        }

        for (let retry = 0; retry < 3; retry++) { // retry mechanism for failed read operations
          try {
            fileContent = await readFilePromise(path.join(directoryPath, fileNames[i]), 'utf8');
            break;
          } catch (error) {
            console.log('Error reading file:', fileNames[i], '. Retry attempt:', retry + 1);
          }
        }

        filesContent += fileContent;
      } else {
        console.log(`Skipped file ${fileNames[i]} due to pattern match.`);
      }
    }

  } catch (error) {
    console.log('Error reading directory:', error.message);
  }

  return filesContent;
}
```

Please note that the actual file path, read status and any encountered errors are not included in this sample for simplicity's sake. In a real-world scenario, these details would be logged to a proper logging system like a log management tool or service. Furthermore, you might want to handle files differently based on their types using the `fileNames[i].split('.').pop()` to get the file extension and applying different processing for each type.
"]

