        dataStructure = BinaryFormatter.deserialize(serializedData); 
    } catch (error) {
        logger.log({ level: logLevel, message: `Failed to deserialize data from ${filePath}: ${error.message}`});
        return;
    }

    let testCount = 0;
    let passCount = 0;
    for (let i = 0; i < testCases.length; i++) {
        const testCase = testCases[i];

        try {
            await testCase(module, dataStructure);  // Assumes each test case is a promise returning function that accepts module and dataStructure
            passCount++;
            logger.log({ level: logLevel, message: `Test ${testCase.name} passed`});
        } catch (error) {
            logger.log({ level: logLevel, message: `Test ${testCase.name} failed: ${error.message}`});
        } finally {
            testCount++;
            blueslip.reset();  // Reset the mocking library after each test completes
        }
    }

    logger.log({ level: logLevel, message: `Total tests run: ${testCount}, Passed: ${passCount}, Failed: ${testCount - passCount}`});
