        const posTaggedBooks = await Promise.all(lemmatizedBooks.map((book) => NLP.posTag(book)));  // POS Tagging

        let booksWithFrequency = {};

        for (let i = 0; i < posTaggedBooks.length; i++) {
            if (!booksWithFrequency[posTaggedBooks[i].name]) {
                booksWithFrequency[posTaggedBooks[i].name] = posTaggedBooks[i].frequency;
            } else {
                booksWithFrequency[posTaggedBooks[i].name] += posTaggedBooks[i].frequency;
            }
        }

        return booksWithFrequency;
    }

    async processText(text) {
        await this.lock.acquire();  // Concurrency management
        try {
            const books = await this.extractBooks(text);

            for (let book in books) {
                if (!this.booksDb[book]) {
                    this.booksDb[book] = 1;
                } else {
                    this.booksDb[book] += books[book];
                }

                // Report any duplicates or potential errors
                if (books[book] > 1) {
                    console.log(`Potential duplicate book: ${book}`);
                }
            }
        } catch (e) {
            console.error('Error processing text', e);
        } finally {
            this.lock.release();  // Release the lock
        }
    }
}
