const renderAndPersistComponent = (components, targetElement, sizeLimit, filePointer, toUpperCase) => {
    return new Promise((resolve, reject) => {
        if(sizeLimit < 1){
            reject('Size limit must be greater than 0');
        }

        let resultString = '';

        components.forEach(component => {
            try{
                // Render component using a templating engine
                let renderedComponent = renderTemplate(component.template, component.props);

                if((renderedComponent + '/').length > sizeLimit){
                    reject('Size limit exceeded');
                } else {
                    resultString += renderedComponent;
                    // Insert the rendered component into target DOM element
                    insertIntoDom(targetElement, renderedComponent); 
                }
            } catch (e) {
                console.error(`Failed to render component: ${component.id}. Error: ${e}`);
            }
        });

        if(resultString){
            resultString += '/';

            if(!filePointer){
                console.warn('Invalid file pointer');
            } else {
                try{
                    // Allocate memory for the resulting string dynamically using malloc
                    let allocatedMemory = allocateMemory(sizeLimit); 

                    // Write result to memory, ensuring proper deallocation on error
                    writeToMemory(allocatedMemory, toUpperCase ? resultString.toUpperCase() : resultString);

                    // Write the resulting string to the provided file pointer
