['Here is a basic implementation in C:

```c
#include <stdlib.h>

typedef struct {
    int clientId;
    // Add more fields as needed
} ClientDevice_t;

typedef struct {
    float frequency;
    int powerLevel;
    ClientDevice_t *clients;
    size_t numClients;
    size_t capacity;
} WiFiChannel_t;

typedef struct {
    WiFiChannel_t *channels;
    size_t numChannels;
    size_t capacity;
} RouterConfig;

void initRouterConfig(RouterConfig *router, int numChannels) {
    router->numChannels = numChannels;
    router->capacity = numChannels;
    router->channels = malloc(sizeof(WiFiChannel_t) * numChannels);
}

void addClientToChannel(RouterConfig *router, int channelIdx, ClientDevice_t client) {
    WiFiChannel_t *channel = &router->channels[channelIdx];

    if (channel->numClients >= channel->capacity) {
        // Reallocate memory as needed
        channel->clients = realloc(channel->clients, sizeof(ClientDevice_t) * (channel->capacity + 1));
        channel->capacity++;
    }

    channel->clients[channel->numClients] = client;
    channel->numClients++;
}

void removeClientFromChannel(RouterConfig *router, int channelIdx, int clientId) {
    WiFiChannel_t *channel = &router->channels[channelIdx];

    for (size_t i = 0; i < channel->numClients; ++i) {
        if (channel->clients[i].clientId == clientId) {
            // Shift all clients after this one back by one
            for (size_t j = i; j < channel->numClients - 1; ++j) {
                channel->clients[j] = channel->clients[j + 1];
            }

            // Decrease the number of clients and reallocate memory if necessary
            channel->numClients--;
            if (channel->capacity - channel->numClients > 2) {
                channel->clients = realloc(channel->clients, sizeof(ClientDevice_t) * channel->numClients);
                channel->capacity = channel->numClients;
            }

            break;
        }
    }
}
``` 
This code initializes a `RouterConfig` structure with a certain number of channels, each with their own unique frequency and power level. Clients can be added to or removed from these channels dynamically, ensuring that the router can handle varying load conditions gracefully. The memory management is handled efficiently by using realloc when necessary to ensure the minimum amount of memory is used.
']

