    size_t deviceCount;
} WiFiChannel_t;

typedef struct {
    WiFiChannel_t *channels;   // Dynamic array of channels
    size_t channelCount;
} RouterConfig;

RouterConfig initRouter(int numChannels) {
    RouterConfig router;
    router.channelCount = numChannels;
    router.channels = calloc(numChannels, sizeof(WiFiChannel_t));  // Allocate memory for channels
    return router;
}

void addDeviceToChannel(RouterConfig *router, int channelIndex, ClientDevice_t *device) {
    WiFiChannel_t *channel = &router->channels[channelIndex];
    channel->connectedDevices = realloc(channel->connectedDevices, (channel->deviceCount + 1) * sizeof(ClientDevice_t*));  // Reallocate memory for devices
    channel->connectedDevices[channel->deviceCount] = device;   // Add device to list
    channel->deviceCount++;   // Increment device count
}

void removeDeviceFromChannel(RouterConfig *router, int channelIndex, ClientDevice_t *device) {
    WiFiChannel_t *channel = &router->channels[channelIndex];
    for (size_t i = 0; i < channel->deviceCount; ++i) {  // Search through connected devices
        if (channel->connectedDevices[i] == device) {
            free(channel->connectedDevices[i]);  // Free the memory associated with this device
            for (size_t j = i; j < channel->deviceCount - 1; ++j) {  
                channel->connectedDevices[j] = channel->connectedDevices[j + 1];   // Shift devices to fill the gap
            }
            channel->deviceCount--;
        }
    }
}

void periodicHealthCheck(RouterConfig *router, int timeoutPeriod) {
    for (size_t i = 0; i < router->channelCount; ++i) {  // For each channel
        WiFiChannel_t *channel = &router->channels[i];
        for (size_t j = 0; j < channel->deviceCount; ++j) {   // For each device in this channel
            ClientDevice_t *device = channel->connectedDevices[j];
            if (++device->timeout_counter > timeoutPeriod) {  // If the device hasn't responded after a while
                removeDeviceFromChannel(router, i, device);   // Remove it from the list
            }
        }
    }
}
```

Please note that this code does not include mechanisms to dynamically add or remove channels (WiFi frequency bands), nor periodic channel scanning. This would require a lot more detail about your specific use case and requirements, as these features are complex and may require extensive error checking and additional data structures. If you need such functionality, please provide the necessary details.
