class OctreeDataStructure {
public:
    OctreeDataStructure(size_t capacity) : data_(capacity), mutexes_(capacity) {}
    ~OctreeDataStructure() { deleteAllNodes(); }

    void addNode(OctreeNode* node, size_t idx) {
        std::lock_guard<std::mutex> lock(mutexes_[idx]);
        data_[idx] = node;
    }

