['```c
#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>
#include <stdlib.h>

void calculate_and_print(char* line) {
    char* token = strtok(line, ",");
    int count = 0;
    double sum = 0.0;
    char md5[MD5_DIGEST_LENGTH];

    while (token != NULL) {
        if (count >= 2) {
            sum += atof(token);
        } else if (count == 1){
            MD5((unsigned char*)token, strlen(token), md5);

            for (int i = 0; i < MD5_DIGEST_LENGTH; ++i)
                printf("%02x", md5[i]);
        } else {
            printf("%s", token);
        }

        if(token = strtok(NULL, ","))
            printf(",");

        count++;
    }

    double avg = sum / 2.0;
    printf("%.3f\n", avg);
}

int main() {
    FILE* file = fopen("textfile.txt", "r");
    char* line = NULL;
    size_t len = 0;

    if (file == NULL)
        exit(EXIT_FAILURE);

    while ((getline(&line, &len, file)) != -1) {
        calculate_and_print(line);
        free(line);
        line = NULL;
    }

    fclose(file);
    if (line)
        free(line);

    return 0;
}
