public class ShellCommandExecutor {
    private static final Logger logger = LogManager.getLogger(ShellCommandExecutor.class);
    private static final int MAX_THREADS = 10000;

    // Creating an executor service with fixed number of threads
    ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

    public void executeCommands(List<String> commands) {
        for (String command : commands) {
            executor.submit(() -> {
                try {
                    long startTime = System.currentTimeMillis();

                    Process process = Runtime.getRuntime().exec(command);

                    BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    String s;
                    while ((s = stdInput.readLine()) != null) {
                        // Handle output stream here
                    }

                    BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                    while ((s = stdError.readLine()) != null) {
                        logger.error("Error: " + s);
                    }

                    long endTime = System.currentTimeMillis();
                    logger.info("Command execution time: {} ms", (endTime - startTime));
                } catch (IOException e) {
                    logger.error(e);
                }
            });
        }
    }

    public static void main(String[] args) {
        ShellCommandExecutor executor = new ShellCommandExecutor();
        List<String> commands = Arrays.asList("ls", "pwd");  // replace with your actual commands
        executor.executeCommands(commands);
