int process_token(const char *token) {
    json_object *jobj = json_tokener_parse(token);
    json_object *access, *expires_in, *token_type, *refresh;
    int expires;

    if(!json_object_object_get_ex(jobj, "access_token", &access)) return 0;
    if(!json_object_object_get_ex(jobj, "expires_in", &expires_in)) return 0;
    if(!json_object_object_get_ex(jobj, "token_type", &token_type)) return 0;

    json_object_object_get_ex(jobj, "refresh_token", &refresh); //optional field

    if(strcmp(json_object_get_string(access),"")) return 0;
    expires = json_object_get_int(expires_in);
    if(expires<=0 || expires>604800) return 0; //validating expiry time
    if(strcmp(json_object_get_string(token_type),"Bearer")) return 0;

    if (refresh != NULL && strcmp(json_object_get_string(refresh),"")) { //if refresh token exists, it should not be empty.
        return 1;
    }
    else if (refresh == NULL) {
        return 1;
    }

    return 0;
}

void process_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp){
        printf("Cannot open file\n");
        exit(-1); // Exit program with error
    }

    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, fp)) != -1) {
        printf("%s", line);
        free(line); // Free allocated memory immediately after use.
        line = NULL;
    }
    fclose(fp);
}

int main() {
    const char *token = "{\"access_token\":\"abc123\", \"expires_in\":3600, \"token_type\":\"Bearer\"}";
    printf("Is token valid? %s\n", process_token(token) ? "Yes" : "No");

    const char *filename = "data.txt";
    process_file(filename);

    return 0;
}
