using System;
using System.Security.Cryptography;
using System.Text;

public class HashProcessor
{
    private readonly HashAlgorithm _hashAlgo;
    private readonly int _segmentSize;

    public enum SupportedHashAlgos { MD5, SHA1, SHA256 }

    public HashProcessor(SupportedHashAlgos hashType = SupportedHashAlgos.MD5, int segmentSize = 1024)
    {
        _segmentSize = segmentSize;
        switch (hashType)
        {
            case SupportedHashAlgos.MD5:
                _hashAlgo = MD5.Create();
                break;
            case SupportedHashAlgos.SHA1:
                _hashAlgo = SHA1.Create();
                break;
            case SupportedHashAlgos.SHA256:
                _hashAlgo = SHA256.Create();
                break;
        }
    }

    public string Process(string input)
    {
        byte[] hashBytes;
        using (var stream = new MemoryStream(Encoding.UTF8.GetBytes(input)))
        {
            var buffer = new byte[_segmentSize];
            int bytesRead;
            while ((bytesRead = await stream.ReadAsync(buffer, 0, _segmentSize)) > 0)
            {
                hashBytes = _hashAlgo.ComputeHash(buffer, 0, bytesRead);
                // Process the hashBytes here...
            }
        }
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }
}
```
This code uses .NET's cryptographic libraries to create an MD5, SHA1 or SHA256 hash of a text input. You can specify the hash algorithm and segment size in the constructor. The `Process` method reads segments from the input string, calculates the hash for each segment, and processes it accordingly.

