    public async Task LoadDataFromFileAsync(string filePath, Action<MyCustomType> processPart)
    {
        try
        {
            using (var sourceStream = new FileStream(filePath, FileMode.Open))
            using (var decompressionStream = new GZipStream(sourceStream, CompressionMode.Decompress))
            {
                BinaryFormatter formatter = new BinaryFormatter();

                while (decompressionStream.Position < decompressionStream.Length)
                {
                    var dataPart = (MyCustomType)formatter.Deserialize(decompressionStream);

                    // Ensure the processPart action is not called on multiple threads concurrently
                    await Task.Run(() => processPart(dataPart)); 
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error occurred while processing file: " + ex.Message);
        }
    }
}
