['Here is a simple outline for your Rust function in accordance with the requirements given above. 

Please note that this example is quite complex and requires knowledge about concurrency handling in Rust (`Arc<Mutex>`, `RwLock`), filesystem operations, environment variables management and logging.

```rust
use std::fs;
use std::sync::{Arc, Mutex};
use log::info;
use uuid::Uuid;
use std::env;
use std::path::PathBuf;
use std_semaphore::Semaphore;
use anyhow::Result;

pub struct Config {
    config_dir: Arc<Mutex<Option<PathBuf>>>,
    default_name: String,
    semaphore: Semaphore,
}

impl Config {
    pub fn new(default_name: &str) -> Self {
        let env_config_dir = env::var("CONFIG_DIR").unwrap_or_else(|_| "".to_string());
        let path = if !env_config_dir.is_empty() {
            Some(PathBuf::from(env_config_dir))
        } else {
            None
        };

        Self {
            config_dir: Arc::new(Mutex::new(path)),
            default_name: default_name.to_string(),
            semaphore: Semaphore::new(1),
        }
    }

    pub async fn get_config_dir(&self) -> Result<PathBuf> {
        self.semaphore.acquire().await;

        if let Some(ref dir) = *self.config_dir.lock().unwrap() {
            info::info(format::format(
                "Using existing configuration directory: {}",
                dir.display(),
            ));
            Ok(dir.clone())
        } else {
            let new_path = PathBuf::from(Uuid::new_v4().to_string());
            info::info(format::format(
                "Creating a new configuration directory: {}",
                new_path.display(),
            ));

            if let Err(e) = fs::create_dir(&new_path) {
                return Err(anyhow::anyhow::<&str>::Error::msg(format::format("Failed to create directory: {}", e)));
            }

            *self.config_dir.lock().unwrap() = Some(new_path.clone());
            Ok(new_path)
        }
    }
}
```

This code represents a basic structure of your Rust function which includes concurrency control, logging, and environment variable handling. However, you need to handle cleanup policy by yourself or integrate it into the struct `Config` as per your requirement.
