["Here is a Node.js implementation for such a task using libraries like `fs`, `path`, and `async`. However, it's crucial to note that JavaScript doesn't natively support multithreading or asynchronous file reading without callbacks or promises, which are not suitable for this problem due to the need for concurrent read operations and a throttling mechanism:

```javascript
const fs = require('fs');
const path = require('path');
const async = require('async');
const EventEmitter = require('events').EventEmitter;

class FileProcessor extends EventEmitter {
  constructor() {
    super();
    this.queue = async.queue((task, callback) => {
      fs.readFile(task.path, 'utf8', (err, data) => {
        if (err) return callback(err);

        task.emitter.emit('fileRead', {
          path: task.path,
          status: 'Success',
          data: data
        });

        setImmediate(callback);
      });
    }, 10); // limit concurrency to 10 at a time

    this.queue.error((err, task) => {
      task.emitter.emit('fileRead', {
        path: task.path,
        status: 'Failure',
        err: err
      });

      // Retry after 1 second on failure
      setTimeout(() => this.queue.push(task), 1000);
    });

    this.queue.drain = () => {
      this.emit('done');
    };
  }

  addFile(filePath, emitter) {
    this.queue.push({path: filePath, emitter: emitter});
  }
}

function readFilesInDir(dir, pattern, emitter) {
  const files = fs.readdirSync(dir);
  const processor = new FileProcessor();

  for (let i = 0; i < files.length; i++) {
    let filePath = path.join(dir, files[i]);
    let stats = fs.statSync(filePath);

    if (!pattern || !pattern.test(files[i])) {
      if (stats.isFile()) processor.addFile(filePath, emitter);
      else if (stats.isDirectory() && !fs.realpathSync(filePath).startsWith('/dev/')) readFilesInDir(filePath, pattern, emitter); // prevent infinite loops with realpathSync and startsWith check
    }
  }
}
```
To use the function:

