#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* log;
} Event;

Event* parse_events(const char *filename, int max_num_events) {
    FILE *file = fopen (filename, "r");
    if (file == NULL) {
        perror ("Error opening file");
        return NULL;
    }

    Event *events = malloc(max_num_events * sizeof(Event));
    if (events == NULL) {
        fclose(file);
        return NULL;
    }

    char buffer[256];
    int event_index = 0;
    while ((fgets(buffer, sizeof(buffer), file)) != NULL && event_index < max_num_events) {
        events[event_index].log = malloc((strlen(buffer) + 1) * sizeof(char));
        if (events[event_index].log == NULL) {
            for (int i = 0; i < event_index; ++i) {
                free(events[i].log);
            }
            free(events);
            fclose(file);
            return NULL;
        }
        strcpy(events[event_index++].log, buffer); // simple pattern check
    }

    if (ferror(file)) {
        perror ("Error reading file");
        for (int i = 0; i < event_index; ++i) {
            free(events[i].log);
        }
        free(events);
        fclose(file);
        return NULL;
    }

    fclose(file);
    return events;
}
```

This function opens the file, allocates memory for an array of `Event` structs and then reads line by line from the log. For each line it allocates enough space for a copy of that line and copies it into that allocated space. It will stop reading after `max_num_events` have been read or if there are no more lines in the file to read.

