void monitor_directory(fs::path dir, std::chrono::seconds interval, 
                       const std::function<void(LogFile)>& callback = nullptr) {
    while (true) {
        try {
            for (const auto & entry : fs::directory_iterator(dir)) {
                if (!fs::is_regular_file(entry.status())) continue;

                // Run each file processing asynchronously, 
                // which will not block the main thread and speed up the overall process.
                std::future<LogFile> fut = std::async(std::launch::async, process_file, entry);

                if (callback) {
