EVP_CIPHER_CTX *initializeAES128GCM(const char *passphrase) {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    int keyLen, ivLen;

    // Generate a random IV for each encryption operation.
    if(RAND_bytes(iv, EVP_MAX_IV_LENGTH) != 1) {
        return NULL; 
    }

    // Derive the key from the passphrase using PBKDF2 with SHA-512 and 10,000 iterations.
    if(EVP_BytesToKey(EVP_aes_128_gcm(), EVP_sha512(), NULL, (unsigned char *)passphrase, strlen(passphrase), 10000, key, &keyLen) != 1) {
        return NULL;
    }

    // Initialize the cipher context and set IV length based on data size.
    ctx = EVP_CIPHER_CTX_new();
    if(EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, key, iv) != 1) {
        return NULL; 
    }

    // Enable the cipher and return a pointer to the cipher context.
    if(EVP_CIPHER_CTX_set_padding(ctx, EVP_PADDING_NONE) != 1) {
        return NULL; 
    }

    return ctx;
}
