class FileHandler {
  string filename;
  size_t bufferSize;
public:
  FileHandler(const string& file, size_t bs) : filename(file), bufferSize(bs) {}
  void operator()() const {
    ifstream fin(filename);
    if (!fin.is_open()) {
      BOOST_LOG_TRIVIAL(error) << "Error opening the file: " << filename;
      return;
    }
    vector<char> buffer(bufferSize);
    size_t count = 0, totalCharCount = 0;
    while (!fin.eof()) {
      fin.read(&buffer[0], bufferSize);
      for (size_t i = 0; i < fin.gcount(); ++i) 
        if(buffer[i] != '\n') totalCharCount++;
      count += fin.gcount();
    }
    BOOST_LOG_TRIVIAL(info) << "File: " << filename << "\t Lines read: " << count << "\t Total chars (excluding newline): " << totalCharCount;
  }
};

