    size_t bufferSize = root.get<size_t>("bufferSize");

    if (!inputFile.empty()) {
        vector<thread> threads;
        for (const auto& file : splitInputFilesIntoVector(inputFile)) 
          threads.emplace_back(FileHandler(file, bufferSize));
        for (auto& th : threads) 
          if (th.joinable()) th.join();
    } else {
      cout << "No input file provided. Use --help to see options.\n";
    }
  } catch(std::exception& e){
    cerr << "Error: " << e.what() << "\n";
    return 1;
  } catch(...){
    cerr << "Unknown exception!\n";
    return 2;
  }

  return 0;
}
```

