import java.util.Arrays;
import java.util.logging.*;

public class EncryptionHelper {
    private static final Logger logger = Logger.getLogger(EncryptionHelper.class.getName());

    // AES-256-CBC encryption details
    private static final String CIPHER_ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final int KEY_SIZE = 32; // 256 bits for AES-256
    private static final byte[] IV = new byte[16]; // Initialization vector of size 128 bits for CBC mode

    // Previously hashed hostname and last hash time
    private String prevHostname;
    private long lastHashTime = 0;

    public Cipher resolveHostnameAndEncrypt(String hostname) {
        try{
            if (hostname == null || hostname.isEmpty()) {
                throw new IllegalArgumentException("Input hostname cannot be null or empty.");
            }

            // Check for changes in the input string within a certain threshold percentage
            double changeThreshold = 0.05; 
            MessageDigest digest = MessageDigest.getInstance("SHA-1");
            byte[] hash = digest.digest(hostname.getBytes());

            if (prevHostname != null && Arrays.equals(hash, prevHostname) && 
                System.currentTimeMillis() - lastHashTime <= changeThreshold * hostname.length()) {

                // The input string hasn't changed significantly since the last hash
                logger.log(Level.INFO, "Input string has not changed significantly since the last hash");
                return null;
            } 

            InetAddress ip = InetAddress.getByName(hostname);
            byte[] ipBytes = ip.getAddress();

            // Derive an AES-256-CBC encryption key from the provided hostname
            SecretKeySpec secretKey = new SecretKeySpec(hash, "AES");
            IvParameterSpec ivParameterSpec = new IvParameterSpec(IV);

            Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivParameterSpec);

            // Store the hash and current time for future comparisons
            prevHostname = hostname;
            lastHashTime = System.currentTimeMillis();

            return cipher;
        } catch (Exception e) {
            logger.log(Level.SEVERE, "An error occurred: ", e);
            return null;
        } 
    }
}
```
