    private static final String KEY_ALGORITHM = "AES";
    private static final int KEY_SIZE = 256; // bits
    private static final String CIPHER_TRANSFORMATION = "AES/CBC/PKCS5Padding";

    public Tuple resolveHostnameAndEncrypt(String hostname) {
        byte[] ipAddress = null;
        byte[] encryptedHostname = null;

        try {
            // DNS resolution and handle errors appropriately
            InetAddress address = InetAddress.getByName(hostname);
            ipAddress = address.getAddress();

            // Derive an AES-256-CBC encryption key from the hostname
            byte[] keyBytes = new byte[KEY_SIZE / 8];
            MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
            sha1.update(hostname.getBytes());
            System.arraycopy(sha1.digest(), 0, keyBytes, 0, keyBytes.length);

            SecretKeySpec secretKeySpec = new SecretKeySpec(keyBytes, KEY_ALGORITHM);
            Cipher cipher = Cipher.getInstance(CIPHER_TRANSFORMATION);
            byte[] ivBytes = new byte[cipher.getBlockSize()]; // for AES block size is 16 bytes
            IvParameterSpec ivParams = new IvParameterSpec(ivBytes);

            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParams);
            encryptedHostname = cipher.doFinal(hostname.getBytes());
        } catch (Exception e) {
            // handle errors appropriately and log them
            e.printStackTrace();
        }

        return new Tuple(ipAddress, encryptedHostname);
    }
