```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    int userId;
    char macAddress[18];
    char ipAddress[16];
    unsigned short portNumber;
} NICPConfig;

typedef struct {
    pthread_mutex_t mutex;
    NICPConfig** nicpArray;
    int capacity;
    int size;
} DynamicNICPArray;

DynamicNICPArray* createDynamicNICPArray() {
    srand(time(NULL));

    DynamicNICPArray* array = malloc(sizeof(DynamicNICPArray));
    pthread_mutex_init(&array->mutex, NULL);
    array->nicpArray = NULL;
    array->capacity = 0;
    array->size = 0;

    return array;
}

void addToDynamicNICPArray(DynamicNICPArray* array, NICPConfig* config) {
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        int newCapacity = array->capacity == 0 ? 1 : array->capacity * 2;

        NICPConfig** newArray = realloc(array->nicpArray, sizeof(NICPConfig*) * newCapacity);

        if (newArray == NULL) {
            fprintf(stderr, "Error: Out of memory!\n");
            exit(EXIT_FAILURE);
        }

        array->nicpArray = newArray;
        array->capacity = newCapacity;
    }

    array->nicpArray[array->size++] = config;

    pthread_mutex_unlock(&array->mutex);
}
```
This is a simplified version of what your program might look like. The concept here is to create an initial function that creates and initializes the `DynamicNICPArray` structure, along with a mutex for thread safety. It also has a function to add a new configuration to the dynamic array ensuring thread safety while resizing as needed.

