            if (tempBuffer == NULL) {
                fprintf(stderr, "Failed to re-allocate memory\n");
                free(buffer);
                return NULL;
            }

            buffer = tempBuffer;
            initialSize = newSize;
        }

        buffer[(*count)++] = number; // Store the number in the buffer and increment count
    }

    if (*count >= maxCount && scanf("%*[^\n]")) { // Check for excess input
        fprintf(stderr, "Input size exceeded limit\n");
    }

    return buffer;
}

