typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node *head = NULL;  // Head of the list, shared by all threads
pthread_mutex_t lock;
int count = 0;  // Count of valid entries in the list

void* manage_crc_indications(void *arg) {
    int N = *((int *) arg);  // Maximum size of array

    pthread_mutex_lock(&lock);

    if (count >= N) {
        printf("List is full\n");
        return NULL;
    }

    Node *newNode = malloc(sizeof(Node));
    if (!newNode) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize newNode->data here...

    newNode->next = head;  // Add to the start of the list
    head = newNode;
    count++;

    pthread_mutex_unlock(&lock);

    return NULL;
}

void clearList() {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current != NULL) {
        Node *nextNode = current->next;  // Save the next node before freeing memory

        free(current);

        current = nextNode;  // Move to the next node
    }

    head = NULL;
    count = 0;

    pthread_mutex_unlock(&lock);
}
```
This code is a basic implementation of a linked list with thread-safe insertion. It uses a mutex lock to protect shared data (the list) from concurrent access and modification. The `manage_crc_indications` function creates new nodes, adds them to the start of the list, and increments the count.

