/* Create a new symmetric encryption context */
struct cipher_ctx* create_cipher(const char* passphrase, const unsigned char* salt, int keylen, int mode) 
{
    if (keylen < 128 || keylen > 256) {
        return NULL; // Key size is out of valid range.
    }

    EVP_CIPHER *cipher = mode == EVP_aes_128_cbc() ? EVP_aes_128_cbc() : 
                          (mode == EVP_aes_256_gcm()) ? EVP_aes_256_gcm() : NULL;

    if (!cipher) {
        return NULL; // Invalid cipher mode.
    }

    struct cipher_ctx *cipher_context = malloc(sizeof(*cipher_context));
    cipher_context->ctx = EVP_CIPHER_CTX_new();

    if (!PKCS5_PBKDF2_HMAC_SHA1(passphrase, strlen(passphrase), salt, sizeof(salt), 1000, keylen/8, EVP_sha256())) {
        EVP_CIPHER_CTX_free(cipher_context->ctx);
        free(cipher_context);
        return NULL; // Error during PBKDF2 derivation.
    }

    if (!EVP_EncryptInit_ex(cipher_context->ctx, cipher, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(cipher_context->ctx);
        free(cipher_context);
        return NULL; // Error during initialization.
    }

    return cipher_context;
}

/* Disable the given symmetric encryption context */
void disable_cipher(struct cipher_ctx *cipher_ctx) 
{
    if (!cipher_ctx || !cipher_ctx->ctx) {
