['```java
import org.json.*;
import java.util.*;
import java.io.*;
import java.lang.reflect.*;

public abstract class JsonObject implements Serializable {
  private static Map<String, Constructor<? extends JsonObject>> registry = new HashMap<>();

  public final String toJson() throws JSONException {
    return toJson(this);
  }

  protected abstract void populate(JSONObject from) throws JSONException;

  private static <T extends JsonObject> T fromJson(Class<T> type, JSONObject from) throws JSONException, IllegalAccessException, InvocationTargetException, InstantiationException {
    Constructor<? extends JsonObject> constructor = registry.get(type.getName());
    if (constructor == null) {
      throw new IllegalArgumentException("Type " + type.getName() + " not registered.");
    }

    T instance = (T) constructor.newInstance();
    instance.populate(from);
    return instance;
  }

  public static <T extends JsonObject> void registerSubclass(Class<T> type, Constructor<? extends JsonObject> constructor) {
    registry.put(type.getName(), constructor);
  }
}
```
