        self.priority = priority

    def __lt__(self, other):
        return self.priority < other.priority

class ImageProcessor(object):
    def __init__(self, default_dir=None):
        self.default_dir = default_dir or "/path/to/default/"
        if not os.path.isdir(self.default_dir):
            os.makedirs(self.default_dir)

    def process_jpeg(self, image_path, retry=3):
        for _ in range(retry):
            try:
                img = Image.open(image_path)
                # Processing logic here...
                return True  # Indicating successful processing
            except Exception as e:
                print("Failed to process image {}: {}".format(image_path, str(e)))
        return False  # Indicating failed after multiple retries

    def handle_job(self):
        while True:
            job = self.queue.get()
            processed = self.process_jpeg(job.image_path)
            if not processed:
                print("Failed to process image {}".format(job.image_path))

    def start(self, num_workers):
        for _ in range(num_workers):
            thread = threading.Thread(target=self.handle_job)
            thread.daemon = True  # Exit when the main process finishes
            thread.start()

    def add_image_path(self, image_path, priority=0):
        self.queue.put(Job(image_path, priority))

if __name__ == "__main__":
