['The problem requires usage of third-party libraries like `poppler` (for reading pdf files) and `libharu` (for extracting fonts). Due to these dependencies, it's not possible to provide a complete solution in C. However, the general approach can be outlined as follows:

```c
#include <stdio.h>
#include <poppler.h>
#include <libharu.h>

typedef struct {
    char *encryption;
    GHashTable *metadata;
    GList *fonts;
} PDFDocumentInfo;

PDFDocumentInfo get_pdf_info(char *filename) {
    PopplerDocument *doc = poppler_document_new_from_file(filename, NULL, NULL);

    if (!doc) {
        fprintf(stderr, "Failed to load the document\n");
        exit(1);
    }

    PDFDocumentInfo info;

    // Encryption level extraction
    PopplerPage *page = poppler_document_get_page(doc, 0);
    switch (poppler_page_get_text_layer(page)) {
        case POPPLER_TEXT_LAYOUT_NONE: info.encryption = "None"; break;
        case POPPLER_TEXT_LAYOUT_UNKNOWN: info.encryption = "Unknown"; break;
        case POPPLER_TEXT_LAYOUT_OC: info.encryption = "OC (Optical Content)"; break;
    }

    // Metadata extraction
    PopplerDocumentIndex *doc_index = poppler_document_index_new(doc);
    int i, n_fields = poppler_document_index_get_n_fields(doc_index);
    info.metadata = g_hash_table_new(g_str_hash, g_str_equal);

    for (i = 0; i < n_fields; ++i) {
        PopplerIndexField *field = poppler_document_index_get_field(doc_index, i);
        const char *name = poppler_index_field_get_name(field);
        const char *value = poppler_index_field_get_text(field);

        g_hash_table_insert(info.metadata, (gpointer) name, (gpointer) value);
    }

    // Font extraction
    info.fonts = NULL;
    int n_pages = poppler_document_get_n_pages(doc);

    for (i = 0; i < n_pages; ++i) {
        page = poppler_document_get_page(doc, i);

        GList *list = haru_page_extract_fonts(HARU_PAGE(page));
        info.fonts = g_list_concat(info.fonts, list);
    }

    poppler_document_index_free(doc_index);
    g_object_unref(doc);

    return info;
}
```

This is a simplified representation of the code and does not include error handling for missing or malformed metadata fields, unsupported encryption schemes or font embedding configurations. Also note that you need to install `poppler` and `libharu` libraries before compiling the code using this command: 

```bash
sudo apt-get install libpoppler-dev libpoppler-glib-dev libhpdf-dev
```
The output is a structure (PDFDocumentInfo) containing encryption, metadata and fonts used. The structure has been designed to be easily extendable for handling additional document features if necessary. 

Remember to free the allocated memory after use:

```c
