```java
import java.util.*;
import java.security.*;
import org.apache.logging.log4j.*;

public class ThreadSafeQueue {
    private final Queue<String> queue;
    private final Logger logger = LogManager.getLogger(ThreadSafeQueue.class);
    private final MessageDigest md5;

    public ThreadSafeQueue(int capacity) throws NoSuchAlgorithmException {
        this.queue = new LinkedList<>();
        this.md5 = MessageDigest.getInstance("MD5");
    }

    public synchronized void enqueue(String item, int priority) {
        while (isFull()) {
            try {
                wait();
            } catch (InterruptedException e) {
                logger.error(e);
            }
        }
        queue.add(item);
        notifyAll();
    }

    public synchronized String dequeue() {
        while (isEmpty()) {
            try {
                wait();
            } catch (InterruptedException e) {
                logger.error(e);
            }
        }
        String item = queue.poll();
        notifyAll();
        return item;
    }

    public synchronized byte[] getMD5(String input) {
        if (input == null || input.isEmpty()) throw new IllegalArgumentException("Input cannot be null or empty");

        long start = System.nanoTime();
        md5.update(input.getBytes());
        byte[] digest = md5.digest();
        long elapsedTime = System.nanoTime() - start;

        logger.info("MD5 computation for input: " + input + " took " + elapsedTime + " ns");

        return digest;
    }

    // Other methods like rehashing, expiration check, dynamic resize, performance metrics, etc. 
    // will be similar to the enqueue and dequeue operations above.
}
```
