```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct LogEntry {
    time_t timestamp;
    char* message;
} LogEntry;

void process_log_entry(LogEntry* entry) {
    printf("[%s] %s\n", ctime(&entry->timestamp), entry->message);
}

int compare_entries(const void * a, const void * b) {
    time_t lhs = ((LogEntry*)a)->timestamp;
    time_t rhs = ((LogEntry*)b)-timestamp;

    if (lhs < rhs) return -1;
    if (lhs > rhs) return 1;
    return 0;
}

void process_log_entries(int num_batches, int batch_size) {
    for (int i = 0; i < num_batches; ++i) {
        LogEntry* logEntries = malloc(batch_size * sizeof(LogEntry));

        // Here we could parse the entries from an input source. We simulate that by generating random data here.
        for (int j = 0; j < batch_size; ++j) {
            time_t timestamp = time(NULL);  // Current timestamp
            char* message = "This is a log entry";

            LogEntry entry;
            entry.timestamp = timestamp;
            entry.message = malloc((strlen(message) + 1) * sizeof(char));
            strcpy(entry.message, message);

            logEntries[j] = entry;
        }

        // Sort the entries by their timestamps:
        qsort(logEntries, batch_size, sizeof(LogEntry), compare_entries);

        // Process each entry:
        for (int j = 0; j < batch_size; ++j) {
            process_log_entry(&logEntries[j]);

            free(logEntries[j].message);  // Remember to deallocate the memory when we're done with it.
        }

        free(logEntries);  // Free our entries array as well.
    }
}

int main() {
    process_log_entries(5, 10);

    return 0;
}
```
