['```c
#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/sha.h>
#include <openssl/rand.h>

typedef struct {
    EVP_CIPHER_CTX *encrypt;
    EVP_CIPHER_CTX *decrypt;
} fernet_ctx;

fernet_ctx* initialize(const char *password, const unsigned char *salt) {
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    int rc = EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char *)password, strlen(password), 1, key, iv);

    if (rc != 32) {
        printf("Error during key derivation\n");
        return NULL;
    }

    fernet_ctx *ctx = malloc(sizeof(fernet_ctx));
    ctx->encrypt = EVP_CIPHER_CTX_new();
    ctx->decrypt = EVP_CIPHER_CTX_new();
    if(!EVP_EncryptInit_ex(ctx->encrypt, EVP_aes_256_cbc(), NULL, key, iv)) {
        printf("Error during encryption initialization\n");
        return NULL;
    }

    if(!EVP_DecryptInit_ex(ctx->decrypt, EVP_aes_256_cbc(), NULL, key, iv)) {
        printf("Error during decryption initialization\n");
        return NULL;
    }

    return ctx;
}

void encrypt(fernet_ctx *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;
    if(!EVP_EncryptUpdate(ctx->encrypt, ciphertext, &len, plaintext, plaintext_len)) {
        printf("Error during encryption\n");
        return;
    }

    if(!EVP_EncryptFinal_ex(ctx->encrypt, ciphertext + len, &len)) {
        printf("Error during final encryption\n");
        return;
    }
}

void decrypt(fernet_ctx *ctx, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    int len;

    if(!EVP_DecryptUpdate(ctx->decrypt, plaintext, &len, ciphertext, ciphertext_len)) {
        printf("Error during decryption\n");
        return;
    }

    if(!EVP_DecryptFinal_ex(ctx->decrypt, plaintext + len, &len)) {
        printf("Error during final decryption\n");
        return;
    }
}

void cleanup(fernet_ctx *ctx) {
    EVP_CIPHER_CTX_free(ctx->encrypt);
    EVP_CIPHER_CTX_free(ctx->decrypt);
    free(ctx);
}
```
This code provides a basic implementation of Fernet encryption using OpenSSL. It includes functions for initializing the encryption and decryption contexts, encrypting and decrypting data, and cleaning up resources when no longer needed. The key derivation is done using PBKDF2 with SHA-256, ensuring secure password-based key derivation. Note that this code lacks functionality to generate and validate Fernet tokens as that would require more OpenSSL functions, complex data structures, and custom encoding/decoding logic specific to the Fernet token format.
']

