public class LargeFileProcessor {
    private static final Logger LOGGER = Logger.getLogger(LargeFileProcessor.class.getName());

    public void processLargeTextFile() {
        File inputFile = new File("input.txt");
        File outputFile = new File("output.txt");

        try (BufferedReader reader = new BufferedReader(new FileReader(inputFile), 1024*1024);
             PrintWriter writer = new PrintWriter(outputFile)) {

            String line;
            while ((line = reader.readLine()) != null) {
                try {
                    String transformedLine = transformLine(line);
                    writer.println(transformedLine);
                } catch (Exception e) {
                    LOGGER.log(Level.SEVERE, "Error processing line: " + line, e);
                }
            }
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "I/O error occurred", e);
        }
    }

    private String transformLine(String line) {
        return line.trim().toUpperCase();
    }
}
