    int numRead = 0;
    size_t outLength = 0;
    EVP_CIPHER_CTX *cipherCtx = create_cipher(EVP_aes_256_cbc(), ctx->key, ctx->iv, 0);

    while ((numRead = fread(inBuffer, 1, sizeof inBuffer, inFile))) {
        if (!EVP_DecryptUpdate(cipherCtx, outBuffer, &outLength, inBuffer, numRead)) {
            // Handle error.
        }

        // Write decrypted data to file.
    }

    destroy_cipher(cipherCtx);
    fclose(inFile);
}
