    RX_UE_INFORMATION_TAG ueInfo;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

Node *head = NULL;
int count = 0;

void addToList(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    if (count >= 10000) {
        log_error("Maximum number of elements reached.");
        pthread_mutex_unlock(&lock);
        return;
    }

    Node *newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        log_error("Memory allocation failed.");
        pthread_mutex_unlock(&lock);
        return; 
    }

    newNode->data = data;
    newNode->next = head;

    Node *temp = head;
    while (temp != NULL) {
        if (temp->data.RNTI == data.RNTI) {
            log_error("Duplicate RNTI detected.");
            free(newNode);
            pthread_mutex_unlock(&lock);
            return;
        }

        temp = temp->next;
    }

    head = newNode;
    count++;

    srand(time(NULL));
    data.crc.CRCFLAG = rand() % 2; // random CRCFLAG

    pthread_mutex_unlock(&lock);
}
```

This code defines a linked list and a function to add elements to the list. It uses a mutex for thread safety, checks if the maximum count is reached before adding new nodes, handles memory allocation failures, ensures that no duplicate `RNTI` are added by checking each node in the list, and sets a random `CRCFLAG` value. The function logs errors through an external `log_error()` function.
