int validate_and_add(NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        if(current->RNTI == node->RNTI){
            logError("Duplicate RNTI found, not adding to list");
            pthread_mutex_unlock(&lock);
            return 1;
        }
        current = current->next;
