const fs = require('fs');
const path = require('path');
const readFile = require('util').promisify(fs.readFile);

async function readFilesFromDirAsync(dir, extFilter, maxSize) {
    let result = '';
    try {
        const files = fs.readdirSync(dir).filter((file) => path.extname(file) === `.${extFilter}` && fs.statSync(path.join(dir, file)).isFile());

        for (let i = 0; i < files.length; i++) {
            const stats = fs.statSync(files[i]);

            if (stats.size <= maxSize) {
                result += await readFile(path.join(dir, files[i]), 'utf8');
            } else {
                console.error(`Error: File ${files[i]} exceeds the maximum file size limit`);
            }
        }
    } catch (err) {
        console.error('An error occurred while reading the directory:', err);
        return null;
    }

    console.log('Operation completed successfully');
    return result;
}
```

Remember to install and import the necessary modules in Node.js for this function to work as expected, like `fs` (file system) module and `path` (for handling paths). This code assumes that the path is a valid directory and the extension includes the dot.
