['Here is an example C code that meets most of your requirements. However, please note it's just a simple sample and may need adjustments based on actual use cases or specific constraints. 

```c
#include <stdio.h>
#include <time.h>
#include <string.h>
#define MAX_EVENTS 10000

typedef struct {
    char eventType[25];
    time_t timestamp;
    char sourceIP[16];
    char destIP[16];
} NetworkEventRecord;

NetworkEventRecord records[MAX_EVENTS];
int recordCount = 0;

void processLogs(char *logEntries, int numEntries) {
    char timestampStr[25], eventTypeStr[25], sourceIPStr[16], destIPStr[16];

    for (int i = 0; i < numEntries && recordCount < MAX_EVENTS; ++i) {
        sscanf(logEntries, "%s %s %s %s", timestampStr, eventTypeStr, sourceIPStr, destIPStr);

        struct tm timeStruct = {0};
        strptime(timestampStr, "%Y-%m-%dT%H:%M:%S", &timeStruct);
        records[recordCount].timestamp = mktime(&timeStruct);

        strcpy(records[recordCount].eventType, eventTypeStr);
        strcpy(records[recordCount].sourceIP, sourceIPStr);
        strcpy(records[recordCount].destIP, destIPStr);

        logEntries += strlen(timestampStr) + strlen(eventTypeStr) 
                      + strlen(sourceIPStr) + strlen(destIPStr) + 3; // + 3 for spaces

        ++recordCount;
    }

    qsort(records, recordCount, sizeof(NetworkEventRecord), compareRecords);
}

int compareRecords(const void *a, const void *b) {
    time_t lhs = ((NetworkEventRecord*)a)->timestamp;
    time_t rhs = ((NetworkEventRecord*)b)-timestamp;

    return (lhs > rhs) - (lhs < rhs);
}

void filterRecords(char *filter) {
    for (int i = 0; i < recordCount; ++i) {
        if (strstr(records[i].eventType, filter)) {
            printf("Timestamp: %s\nEvent Type: %s\nSource IP: %s\nDestination IP: %s\n", 
                   ctime(&records[i].timestamp), records[i].eventType, records[i].sourceIP, records[i].destIP);
        }
    }
}
```
This C code creates a struct to hold network event records. It then parses each line of the log entries and populates an array with these records, up to `MAX_EVENTS`. The records are sorted by timestamp using `qsort()` before filtering based on `filterRecords()` function. This is just one possible way of implementing this and it's not intended to be a complete solution, but rather a starting point that could be extended or modified as needed.

