["Here is a NodeJS solution using fs promises, async, path and events modules for asynchronous error handling and logging.

```javascript
const fs = require('fs').promises;
const pathModule = require('path');
const os = require('os');
const globby = require('globby');
const async = require('async');
const EventEmitter = require('events');

class FileReader extends EventEmitter {
    constructor(options) {
        super();
        this.options = Object.assign({
            throttle: true, 
            retries: true, 
            log: true, 
            fallback: false,
            maxRetries: 3,
            excludePattern: /^$/, // Matches nothing by default
        }, options);
    }

    async readFiles(directory) {
        directory = this.resolvePath(directory);
        let fileList;
        try{
            fileList = await globby([`${directory}/**/*`, `${directory}/.**/*`], {dot: true});
        } catch (err) {
            this.emit('error', err);
            return '';
        }

        const excludeRegex = new RegExp(this.options.excludePattern);
        fileList = fileList.filter(file => !excludeRegex.test(pathModule.extname(file)));

        let resultStr = '';
        if (this.options.throttle) {
            const concurrencyLimit = 10; // Adjust this to your needs
            const fileQueue = async.queue((task, callback) => {
                this.readFile(task).then(content => {
                    resultStr += content;
                    callback();
                }).catch(callback);
            }, concurrencyLimit);

            for (let file of fileList) {
                fileQueue.push(file, err => {
                    if (err) this.emit('error', err);
                });
            }
        } else {
            let readFilePromises = [];
            for (let file of fileList) {
                readFilePromises.push(this.readFile(file));
            }

            resultStr = await Promise.all(readFilePromises).then((contentsArray) => contentsArray.join(''));
        }

        return resultStr;
    }

    async readFile(filePath, retries = 0) {
        let content;
        try {
            if (this.options.log) this.emit('readStart', filePath);
            content = await fs.readFile(filePath, 'utf8');
            if (this.options.log) this.emit('readEnd', filePath, true);
        } catch(err) {
            if (this.options.log) this.emit('readError', filePath, err);
            content = '';
            if (this.options.retries && retries < this.options.maxRetries) return await this.readFile(filePath, retries + 1);
        }

        return content;
    }

    resolvePath(directory) {
        return pathModule.resolve((pathModule.isAbsolute(directory)? '' : process.cwd()), directory);
    }
}
```
You can then use this class as follows:
```javascript
let reader = new FileReader({retries: false, log: true});
reader.on('readStart', (filePath) => console.log(`Reading ${filePath}...`));
reader.on('readEnd', (filePath, status) => console.log(`Finished reading ${filePath}: ${status}`));
reader.on('readError', (filePath, err) => console.error(`Error reading ${filePath}: ${err}`));

reader.readFiles('./test-directory').then((resultStr) => {
    console.log(resultStr);
}).catch((err) => {
    console.error(err);
});
```
This solution uses `globby` module to get all files in a directory asynchronously, which is efficient for large number of small files. A queue mechanism with concurrency limit of 10 is used to manage the file read operations if throttling option is enabled. If an error occurs while reading a file, it will retry up to maximum retries specified. The class also emits events on each file read start and end, including errors. This can be useful for logging purposes or to display progress of file reads in a UI application.
"]

