```javascript
const fs = require('fs/promises');
const path = require('path');
const os = require('os');
const { pipeline } = require('stream/promises');
const pino = require('pino');
let cache = {};
let bufferSize = process.env.BUFFER_SIZE || 1024; // default buffer size 1KB

async function readFilesFromDir(dirPath, pattern) {
    const logger = pino({
        transport: {
            target: 'pino-multi-stream',
            streams: [{ stream: process.stdout },
                { stream: fs.createWriteStream('combined.log') }]
        }
    });

    let fileContents = '';
    try {
        const files = await fs.readdir(dirPath);
        for (let file of files) {
            if (!pattern || path.extname(file).endsWith(pattern)) {
                // check cache first
                if (cache[file]) {
                    logger.info('Serving ' + file + ' from the cache');
                    fileContents += cache[file];
                } else {
                    let start = Date.now();
                    const filePath = path.join(dirPath, file);
                    // handle large files and errors
                    await pipeline(fs.createReadStream(filePath, { bufferSize }), fs.createWriteStream(), (error) => {
                        if (error) {
                            logger.error('Error reading ' + file + ': ' + error.message);
                            return;
                        }

                        let end = Date.now();
                        let size = os.statSync(filePath).size;
                        logger.info('Read ' + file + '. Start: ' + start + ', End: ' + end + ', Size: ' + size);
                    });

                    // store to cache for future use 
                    cache[file] = fileContents;
                }
            }
        }
    } catch (error) {
        logger.error('Error reading files from directory: ' + error.message);
        throw new Error(`Failed to read files from directory ${dirPath} due to error: ${error.message}`);
    }

    return fileContents;
}
```
This function uses a `pino` logger for logging and `stream/promises` for efficient data processing. Also, it employs caching mechanism for frequently accessed files which will improve performance. However, please note that this implementation is quite high-level and doesn't cover all aspects of the task as stated in the prompt (e.g., timeout handling). Depending on the specifics of your use case, you may need to add error handling for cases when `BUFFER_SIZE` environment variable can't be parsed into a number or is less than 1, etc.
