typedef struct UserActivity {
    char *userID;
    cJSON *actionType;
    cJSON *timestamp;
    cJSON *deviceInfo;
} UserActivity;

// A node in the linked list of user activities
typedef struct ActivityNode {
    UserActivity *activity;
    struct ActivityNode *next;
} ActivityNode;

// Linked list of user activities, indexed by userID
typedef struct IndexedActivities {
    ActivityNode **array;
    size_t capacity;
    size_t size;
} IndexedActivities;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

IndexedActivities *createIndex() {
    IndexedActivities *index = malloc(sizeof(IndexedActivities));
    index->capacity = 1024; // Start with a reasonable initial capacity
    index->size = 0;
    index->array = calloc(index->capacity, sizeof(ActivityNode*));
    return index;
}

void destroyIndex(IndexedActivities *index) {
    for (size_t i = 0; i < index->capacity; ++i) {
        ActivityNode *node = index->array[i];
        while (node != NULL) {
            ActivityNode *next = node->next;
            free(node->activity); // Assume the UserActivity struct itself owns all memory
            free(node);
            node = next;
        }
    }
    free(index->array);
    free(index);
}

UserActivity *createUserActivity(const char *userID, cJSON *actionType, cJSON *timestamp, cJSON *deviceInfo) {
    UserActivity *activity = malloc(sizeof(UserActivity));
    activity->userID = strdup(userID);
    activity->actionType = actionType; // Assume the caller owns this memory
    activity->timestamp = timestamp; // Assume the caller owns this memory
    activity->deviceInfo = deviceInfo; // Assume the caller owns this memory
    return activity;
}

void addActivityToIndex(IndexedActivities *index, UserActivity *activity) {
    unsigned long hash = 5381;
    for (const char *p = activity->userID; *p != '\0'; ++p) {
        hash = ((hash << 5) + hash) + (unsigned char)*p; // djb2 string hashing algorithm
    }

    size_t indexPos = hash % index->capacity;

    ActivityNode *newNode = malloc(sizeof(ActivityNode));
    newNode->activity = activity;
    newNode->next = index->array[indexPos];
    index->array[indexPos] = newNode;
}

// Returns NULL if the user does not exist in the index. The caller owns the returned memory.
UserActivity *getActivitiesForUser(IndexedActivities *index, const char *userID) {
    unsigned long hash = 5381;
    for (const char *p = userID; *p != '\0'; ++p) {
        hash = ((hash << 5) + hash) + (unsigned char)*p; // djb2 string hashing algorithm
    }

    size_t indexPos = hash % index->capacity;

    for (ActivityNode *node = index->array[indexPos]; node != NULL; node = node->next) {
        if (strcmp(node->activity->userID, userID) == 0) {
            return node->activity;
        }
    }

    return NULL;
}

