        }

        cJSON *timestamp = cJSON_GetObjectItemCaseSensitive(json, "timestamp");
        if (timestamp == NULL || !cJSON_IsNumber(timestamp)) {
            fprintf(stderr, "Invalid timestamp in log entry\n");
            cJSON_Delete(json);
