        }

        cJSON *deviceInfo = cJSON_GetObjectItemCaseSensitive(json, "deviceInfo");
        if (deviceInfo == NULL || !cJSON_IsString(deviceInfo)) {
            fprintf(stderr, "Invalid deviceInfo in log entry\n");
