['Creating a comprehensive solution for this task within this context would not fit well due to its complexity but I can provide you with an example of how such a function might start:

```javascript
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

let cache = {};
let lastDirHash = '';

async function readFilesInDirectory(dir, ext) {
    const files = await getAllFiles(dir);
    let fileContents = [];

    for (let i = 0; i < files.length; i++) {
        if (!files[i].isHidden && path.extname(files[i].name) === ext) {
            try {
                const content = await readFileAsync(path.join(dir, files[i].name));
                fileContents.push(content);
            } catch (err) {
                // handle error here - e.g., log or retry
            }
        }
    }

    return fileContents.join('');
}

function getAllFiles(dir, ext) {
  const dirHash = crypto.createHash('md5').update(dir).digest("hex");

  if (lastDirHash !== '' && lastDirHash === dirHash) {
    return Promise.resolve(cache[dir].files);
  } else {
    cache[dir] = {};
    lastDirHash = dirHash;
  }

  return new Promise((resolve, reject) => {
      fs.readdir(dir, (err, files) => {
          if (err) {
              reject(err);
          } else {
              const fileList = [];

              for (let i = 0; i < files.length; i++) {
                  const filePath = path.join(dir, files[i]);

                  fs.stat(filePath, (err, stats) => {
                      if (!stats.isDirectory()) {
                          // store each file in a list with their name and isHidden flag
                          fileList.push({name: files[i], isHidden: files[i].startsWith('.')});
                      }
                  });
              }

              cache[dir] = {files: fileList, hash: dirHash};
              resolve(fileList);
          }
      });
  });
}

function readFileAsync(path) {
    return new Promise((resolve, reject) => {
        fs.readFile(path, 'utf8', (err, data) => {
            if (err) {
                reject(err);
            } else {
                resolve(data);
            }
        });
    });
}
```
