typedef struct thread_data {
    char *filename;
} thread_data;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
long total_lines = 0, total_chars = 0;
int max_file_size = get_config_value("max_file_size", 1048576); // 1MB default
FILE *output_file;

void* process_file(void* arg) {
    thread_data* data = (thread_data*)arg;
    char* filename = data->filename;
    FILE *file = fopen(filename, "r");

    if (!file) {
        log_error("Failed to open file");
        return NULL;
    }

    int chars = 0, lines = 1;
    char buffer[256];

    while (fgets(buffer, sizeof(buffer), file)) {
        chars += strlen(buffer);
        lines++;
    }

    pthread_mutex_lock(&lock);
    total_lines += lines;
    total_chars += chars;

    if (output_file) {
        fprintf(output_file, "File: %s\nLines: %d\nCharacters: %d\n", filename, lines, chars);
    }

    pthread_mutex_unlock(&lock);
    fclose(file);

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: ./program --help|-o output_file input_files...\n");
        return 1;
    }

    if (!strcmp(argv[1], "--help")) {
        printf("Help information goes here.\n");
        return 0;
    } else if (!strcmp(argv[1], "-o") && argc > 2) {
        output_file = fopen(argv[2], "w");
    } else {
        output_file = stdout;
    }

    pthread_t threads[argc - 3];
    thread_data data[argc - 3];
    int i, rc;

    for (i = 0; i < argc - 3; ++i) {
        char* filename = argv[i + 3];

        if (access(filename, F_OK) == -1) {
            log_error("File does not exist");
            continue;
        }

        long size = get_config_value("max_file_size", max_file_size);
        struct stat st;

        if (stat(filename, &st) == 0 && st.st_size > size) {
            log_error("File is too large");
            continue;
        }

        data[i].filename = filename;
        rc = pthread_create(&threads[i], NULL, process_file, &data[i]);

        if (rc) {
            log_error("Failed to create thread");
            return 1;
        }
    }

    for (int j = 0; j < i; ++j) {
        rc = pthread_join(threads[j], NULL);

        if (rc) {
            log_error("Failed to join thread");
            return 1;
        }
    }

    fprintf(output_file, "\nTotal Lines: %ld\nTotal Characters: %ld\n", total_lines, total_chars);
    fclose(output_file);

    return 0;
}
```
