    if (!newFilename) {  // Handle out-of-memory errors gracefully
        return NULL;
    }

    strncpy(newFilename, filename, lenWithoutExt);  // Copy the original filename without extension

    srand(time(0));  // Seed the random number generator with current time
    for (size_t i = 0; i < digitCount; ++i) {  // Generate a random alphanumeric string to append
        newFilename[lenWithoutExt + i] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"[rand() % 62];
    }

    strcpy(&newFilename[lenWithoutExt + digitCount], extension);  // Copy the original extension to new filename

