NFAPI_CRC_INDICATION_PDU_T* allocateStruct() {
    NFAPI_CRC_INDICATION_PDU_T* structPtr = NULL;

    pthread_mutex_lock(&mutex);
    if (poolIndex < MAX_POOL_SIZE) {
        structPtr = memoryPool[poolIndex++];
    }
    pthread_mutex_unlock(&mutex);

    return structPtr;
}

void deallocateStruct(NFAPI_CRC_INDICATION_PDU_T* structPtr) {
    if (structPtr != NULL) {
