['Here is a high-level implementation in C using pthreads for thread safety and memory pooling techniques for efficient memory management. This code does not include logging or resource management features as these would require more specific requirements and could be added after further clarification on how to handle those logs and resources. 

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
int count = 0;
#define MAX 10000
#define MEMORY_POOL_SIZE (MAX * sizeof(NFAPI_CRC_INDICATION_PDU_T))
static NFAPI_CRC_INDICATION_PDU_T* memoryPool = NULL;

void init() {
    srand((unsigned int) time(NULL));  // Seed the random number generator

    head = malloc(sizeof(Node));
    if (head == NULL) exit(1);
    head->next = NULL;

    memoryPool = malloc(MEMORY_POOL_SIZE);
    if (memoryPool == NULL) exit(2);
}

void* createStructure(void* RNTI_) {
    int RNTI = *((int*)RNTI_);
    if (RNTI < 1 || RNTI > 65535) return NULL;  // Invalid RNTI value

    pthread_mutex_lock(&lock);
    if(count >= MAX) {
        pthread_mutex_unlock(&lock);
        return NULL;  // Maximum limit reached
    }

    NFAPI_CRC_INDICATION_PDU_T* newData = &memoryPool[count++];
    newData->RNTI = RNTI;
    newData->CRCFLAG = rand() % 2;  // Randomly set CRCFLAG

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL;  // Failed to allocate memory for a new node
    }
    newNode->data = *newData;
    newNode->next = head->next;
    head->next = newNode;

    pthread_mutex_unlock(&lock);

    return &(head->next->data);  // Return the address of the created structure
}
```
The `init()` function initializes a global mutex and allocates memory for the linked list and the data pool. The `createStructure()` function is used to create and add new structures concurrently while ensuring thread safety with locks. It also validates that the RNTI value is within the acceptable range (1-65535), checking whether the maximum structure limit has been reached, allocating memory for a new node and its data, setting up the new data, adding it to the linked list, and returning a pointer to the created structure. The `pthread_mutex_lock()` and `pthread_mutex_unlock()` functions ensure that only one thread can access shared resources at a time.
