["Here is an implementation based on NodeJS using Promises, async/await, streams, and other optimizations:

```javascript
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const readdirp = require('readdirp');
let cache = {};

function createHash(input) {
  return crypto.createHash('md5').update(JSON.stringify(input)).digest('hex');
}

async function readFilesInDirectoryAsync(directory, ext, chunkSize, showProgress) {
  const dirHash = createHash(fs.statSync(directory));
  if (cache[dirHash]) return cache[dirHash];

  let dataChunks = [];
  let totalBytes = 0;
  let progressPercentage = 0;
  let currentProgress = 0;

  await readdirp(directory, { fileFilter: ext }).on('data', async (entry) => {
    if (fs.statSync(path.join(directory, entry.name)).isFile()) {
      const stream = fs.createReadStream(path.join(directory, entry.name));
      let dataChunk = '';

      for await (const chunk of stream) {
        currentProgress++;

        if (showProgress && Math.floor((currentProgress / totalBytes) * 100) !== progressPercentage) {
          progressPercentage = Math.floor((currentProgress / totalBytes) * 100);
          console.log(`Reading progress: ${progressPercentage}%`);
        }

        dataChunk += chunk.toString();

        if (dataChunk.length >= chunkSize && chunkSize !== -1) {
          dataChunks.push(dataChunk);
          dataChunk = '';
        }
      }

      if (dataChunk.length > 0 || totalBytes === 0) {
        dataChunks.push(dataChunk);
      }
    }
  });

  const concatenatedData = dataChunks.join('');
  cache[dirHash] = concatenatedData;

  return concatenatedData;
}
```

This code snippet creates a function `readFilesInDirectoryAsync` that asynchronously reads files from the specified directory, filters them by extension (if provided), and concatenates their contents into a single string. A progress indicator is shown if `showProgress` is set to true. The read operations are cached using an in-memory cache to avoid redundant file reads for subsequent requests to the same directory, with each directory being identified by its hash. 

For error handling and retries, you can use libraries like 'retry' or build your own retry logic inside try/catch blocks of async functions. 

This implementation assumes that NodeJS is used as a runtime for this script, so filesystem operations are performed using native NodeJS APIs (fs module). However, if an environment where these features aren't available, polyfills or alternative libraries can be utilized to achieve similar results. 

For larger files and more than ~10k files, consider chunking the concatenated result for processing in chunks, this could be a bottleneck though due to NodeJS being single-threaded with async I/O model. For truly large datasets, consider streaming data or using an environment that supports parallel processing (like Web Workers in a browser). 

Also note that this implementation doesn't handle file renames, deletions, or changes in directories well due to its simplistic nature. A more sophisticated solution may be needed for these use-cases.
"]

