atomic_int finished = 0;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* process(void* arg) {
    // worker thread processing code here
}

void initNFAPIWorkers() {
    pthread_t workers[NUM_WORKER_THREADS];

    for (int i = 0; i < NUM_WORKER_THREADS; ++i) {
        if (pthread_create(&workers[i], NULL, process, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return 1; // or handle error appropriately
        }
    }

    for (int i = 0; i < NUM_WORKER_THREADS; ++i) {
        if (pthread_join(workers[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return 2; // or handle error appropriately
        }
    }
}

int main() {
    initNFAPIWorkers();

    if (finished != 1) {
        fprintf(stderr, "Some threads didn't finish correctly.\n");
        return -1; // or handle error appropriately
    }

    printf("All threads finished successfully.\n");

    return 0;
}
```
This code creates a fixed number of worker threads that execute the `process` function. The main thread waits for all workers to finish before it continues execution. If a worker fails or does not finish, the program will report an error and terminate with a non-zero exit status. Note that this is a basic example and may require additional modifications to meet your specific requirements.
