} CipherObject;

CipherObject* secure_encrypt(const char *filepath, const EVP_CIPHER *cipher) {
    FILE *infile = fopen(filepath, "rb"); // open file in binary mode for cross-platform compatibility
    if (infile == NULL) {
        printf("Failed to open file.\n");
        return NULL;
    }

    CipherObject* cipherObj = malloc(sizeof(*cipherObj)); 
    if (!cipherObj) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Allocate memory for the key and iv
    cipherObj->key = OPENSSL_malloc(EVP_CIPHER_CTX_key_length(cipher)); 
    cipherObj->iv = OPENSSL_malloc(EVP_CIPHER_CTX_iv_length(cipher));

    // Generate random key and iv
    if (RAND_bytes(cipherObj->key, EVP_CIPHER_CTX_key_length(cipher)) != 1 ||
        RAND_bytes(cipherObj->iv, EVP_CIPHER_CTX_iv_length(cipher)) != 1) {
            // Handle error
            printf("Key/IV generation failed.\n");
            return NULL;
    }

    /* Other encryption and decryption logic here */

    fclose(infile);
    return cipherObj;
}
