['```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>

#define MAX_LEN 255
#define MAX_EXTENSION_LEN 8
#define PBKDF2_ITER 10000
#define AES_KEYLEN 32
#define AES_IVLEN 16
#define HMAC_DIGEST_LENGTH 32

typedef struct {
    unsigned char key[AES_KEYLEN];
    unsigned char iv[AES_IVLEN];
} KeyIvPair;

KeyIvPair* deriveKeyIv(const EVP_MD* dgst, const void* salt, int saltlen, const void* pass, int passlen, int iterations) {
    static KeyIvPair cachedKeys[PBKDF2_ITER];
    if (iterations < PBKDF2_ITER && cachedKeys[iterations].key[0] != 0) {
        return &cachedKeys[iterations];
    }

    KeyIvPair* kiv = malloc(sizeof(KeyIvPair));
    if (kiv == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    unsigned char buf[HMAC_DIGEST_LENGTH];
    int res = PKCS5_PBKDF2_HMAC((const char*)pass, passlen, salt, saltlen, iterations, dgst, AES_KEYLEN+AES_IVLEN, buf);
    if (res != 1) {
        printf("Key derivation failed.\n");
        free(kiv);
        exit(EXIT_FAILURE);
    }

    memcpy(kiv->key, buf, AES_KEYLEN);
    memcpy(kiv->iv, buf+AES_KEYLEN, AES_IVLEN);

    if (iterations < PBKDF2_ITER) {
        cachedKeys[iterations] = *kiv;
    }

    return kiv;
}

void freeKeyIv(KeyIvPair* kiv) {
    memset(kiv->key, 0, AES_KEYLEN);
    memset(kiv->iv, 0, AES_IVLEN);
    free(kiv);
}

char* generateNewFilename(const char* filename, const char* extension) {
    if (strlen(filename) > MAX_LEN - strlen(extension)) {
        printf("Filename is too long.\n");
        return NULL;
    }

    int numDigits = strlen(filename) > 5 ? strlen(filename) - 5 : 0;
    if (numDigits > 10) {
        numDigits = 10;
    }
    char* randomStr = malloc(numDigits+1);
    if (randomStr == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    unsigned char buf[HMAC_DIGEST_LENGTH];
    RAND_bytes(buf, numDigits / 2 + 1); // Generate enough random bytes for desired length.
    for (int i = 0; i < numDigits; ++i) {
        if ((buf[i/2] >> ((i % 2 == 0 ? 4 : 0))) & 0xF < 10) {
            randomStr[i] = '0' + ((buf[i/2] >> ((i % 2 == 0 ? 4 : 0))) & 0xF); // Alphanumeric digit.
        } else {
            randomStr[i] = 'a' + (((buf[i/2] >> ((i % 2 == 0 ? 4 : 0))) & 0xF) - 10); // Lowercase letter.
        }
    }

    char* newExtension = malloc(numDigits + 5);
    if (newExtension == NULL) {
        printf("Memory allocation failed.\n");
        free(randomStr);
        return NULL;
    }

    snprintf(newExtension, numDigits+1, "%s", randomStr); // Prepend the random string.
    strncat(newExtension, extension, MAX_EXTENSION_LEN - numDigits); // Append the original extension (up to 8 characters).

    char* newFilename = malloc(strlen(filename) + strlen(newExtension) + 2);
    if (newFilename == NULL) {
        printf("Memory allocation failed.\n");
        free(randomStr);
        free(newExtension);
        return NULL;
    }

    snprintf(newFilename, strlen(filename)+1, "%s", filename); // Copy the original filename.
    strncat(newFilename, newExtension, MAX_EXTENSION_LEN - numDigits); // Append the new extension.

    free(randomStr);
    free(newExtension);
    return newFilename;
}

void handleOpenSSLError() {
    ERR_print_errors_fp(stderr);
    abort();
}

void cipherFile(const char* filename, const char* pass) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Could not open file.\n");
        exit(EXIT_FAILURE);
    }

    // Generate new filename.
    char* extension = strrchr(filename, '.');
    if (extension != NULL && *(++extension) != 0) {
        extension = generateNewFilename(filename, extension);
    } else {
        extension = "enc"; // Default extension.
    }

    char* newFilename = malloc(strlen(filename) + strlen(extension) + 2);
    if (newFilename == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    snprintf(newFilename, strlen(filename)+1, "%s", filename); // Copy the original filename.
    strncat(newFilename, extension, MAX_EXTENSION_LEN - numDigits); // Append the new extension.

    FILE* outFile = fopen(newFilename, "wb");
    if (outFile == NULL) {
        printf("Could not open output file.\n");
        exit(EXIT_FAILURE);
    }

    // Derive key and IV.
    KeyIvPair* kiv = deriveKeyIv(EVP_sha256(), NULL, 0, pass, strlen(pass), PBKDF2_ITER);

    EVP_CIPHER_CTX* ctx;
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        handleOpenSSLError();
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, kiv->key, kiv->iv) <= 0 || 
        EVP_CIPHER_CTX_set_padding(ctx, 1) != 1) { // Enable padding.
        handleOpenSSLError();
    }

    int len;
    unsigned char inbuf[4096], outbuf[4096 + EVP_MAX_BLOCK_LENGTH];
    while ((len = fread(inbuf, 1, sizeof(inbuf), file)) > 0) {
        if (EVP_EncryptUpdate(ctx, outbuf, &len, inbuf, len) != 1) {
            handleOpenSSLError();
        }

        fwrite(outbuf, 1, len, outFile); // Write ciphertext.
    }

    if (EVP_EncryptFinal_ex(ctx, outbuf, &len) != 1) {
        handleOpenSSLError();
    }

    fwrite(outbuf, 1, len, outFile); // Write final ciphertext.

    EVP_CIPHER_CTX_free(ctx);
    freeKeyIv(kiv);
    fclose(file);
    fclose(outFile);
}
```
This code is a skeleton for the described task and does not include all required error handling or functionality such as file validation, encryption/decryption handling, etc. Please adapt it to your needs. The KDF function should be adapted depending on your specific requirements (iteration count, salt length, key/IV length). Memory management errors are currently just handled by exiting the program, but you may want to handle these in a more sophisticated way, for example by returning error codes and handling them in the calling function.
