#define MAX_POOL_SIZE 10

typedef struct Node {
    int fd;
    time_t timeout;
    struct Node* next;
} Node;

Node *head = NULL, *tail = NULL;
pthread_mutex_t lock;
int size = 0;

void add(int fd, time_t timeout) {
    pthread_mutex_lock(&lock);
    if (size >= MAX_POOL_SIZE) {
        printf("Max pool size reached.\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    Node* newNode = malloc(sizeof(Node));
    newNode->fd = fd;
    newNode->timeout = time(NULL) + timeout;
    newNode->next = NULL;
    if (head == NULL) {
        head = tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }
    size++;
    pthread_mutex_unlock(&lock);
}

int removeFD(int fd) {
    pthread_mutex_lock(&lock);
    Node* current = head, *prev = NULL;
    while (current != NULL && current->fd != fd) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;  // not found
    }
    if (prev == NULL) head = current->next;   // removing head node
    else prev->next = current->next;
    free(current);
    size--;
    pthread_mutex_unlock(&lock);
    return 0;
}

int getActiveConnections() {
    int count = 0;
    Node* temp = head;
    while (temp != NULL) {
        if(difftime(temp->timeout, time(NULL)) > 0)
            count++;
        temp = temp->next;
    }
    return count;
}

void manageConnections() {
    Node* current = head, *prev = NULL;
    while (current != NULL && difftime(current->timeout, time(NULL)) <= 0) {
        if (prev == NULL) head = current->next;
        else prev->next = current->next;
        free(current);
        size--;
    }
}

void* connectionHandler(void *arg) {
