['This problem requires creating a function in C which performs directory traversal to get each filename and generates a new file name by appending a timestamp, hash of its content, and specified file type extension. Here's an implementation using some basic file I/O operations and hashing functions from the OpenSSL library:

```c
#include <stdio.h>
#include <sys/stat.h>
#include <dirent.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>

void process_directory(char* dir_path, char* filetype) {
    DIR *dir;
    struct dirent *entry;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    FILE *file;
    size_t nread;
    unsigned char buffer[1024];
    SHA256_CTX sha256;
    char newfilename[FILENAME_MAX], timestamp[30], filepath[PATH_MAX], hashedContent[SHA256_DIGEST_LENGTH*2+1];

    dir = opendir(dir_path);
    if (dir == NULL) {
        perror("Could not open directory");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (!strcmp (entry->d_name, ".") || !strcmp (entry->d_name, "..")) 
            continue;

        sprintf(filepath,"%s/%s", dir_path, entry->d_name);
        file = fopen(filepath, "rb");
        if (file == NULL) {
            perror("Could not open file for reading");
            continue;
        }

        SHA256_Init(&sha256);
        while ((nread = fread(buffer, 1, sizeof buffer, file)) > 0)
            SHA256_Update(&sha256, buffer, nread);

        SHA256_Final(hash, &sha256);

        for (int i = 0; i < SHA256_DIGEST_LENGTH; i++)
            sprintf(&(hashedContent[i*2]), "%02x", hash[i]);

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        strftime(timestamp, sizeof timestamp, "%Y%m%d%H%M%S", tm);

        sprintf(newfilename, "%s/%s_%s.%s", dir_path, entry->d_name, timestamp, filetype);
        if (rename(filepath, newfilename) != 0) {
            perror("Error renaming file");
            return;
        }
    }

    closedir(dir);
}
``` 

This code opens a directory and reads each entry. If the entry is a regular file, it computes a SHA256 hash of its content, appends a timestamp and this hash to the filename before renaming it. Be aware that you need OpenSSL installed in your system for compilation of above C program. You can install it on Ubuntu using `sudo apt-get install libssl-dev` command.
']

