```c
#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/aes.h>

void secure_file_operation(char* filename, char operation, unsigned char* password, unsigned char* salt) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;
    unsigned char key[32];
    unsigned char iv[16];
    FILE *fpIn = fopen(filename, "rb");
    FILE *fpOut = fopen((operation == 'e') ? "encrypted.txt" : "decrypted.txt", "wb");
    unsigned char in_buf[1024], out_buf[1024 + EVP_MAX_BLOCK_LENGTH];

    if(!fpIn || !fpOut) {
        printf("Failed to open file\n");
        return;
    }

    /* Generate the encryption key using PBKDF2 with SHA-256 */
    PKCS5_PBKDF2_HMAC(password, strlen((char*)password), salt, 8, 1000, EVP_aes_256_cbc(), 32, key);

    /* Initialize the cipher context */
    ctx = EVP_CIPHER_CTX_new();
    if(operation == 'e') {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    } else {
        EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    }

    /* Process the file in chunks */
    while((len = fread(in_buf, 1, sizeof in_buf, fpIn)) > 0) {
        if(!EVP_CipherUpdate(ctx, out_buf, &ciphertext_len, in_buf, len)) {
            printf("Error processing file\n");
            return;
        }

        fwrite(out_buf, 1, ciphertext_len, fpOut);
    }

    /* Finalize encryption/decryption */
    if(!EVP_CipherFinal_ex(ctx, out_buf, &ciphertext_len)) {
        printf("Error finalizing operation\n");
        return;
    }

    fwrite(out_buf, 1, ciphertext_len, fpOut);

    EVP_CIPHER_CTX_free(ctx);
}
```

Please note that you need to have the OpenSSL library installed and include the appropriate header files. This is just a basic demonstration of how you might perform AES encryption/decryption in C using OpenSSL's high-level EVP interface, not a comprehensive solution for the task as described in your problem statement.
