public byte[] serialize(List<CustomObject> objList) {
    try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
         ObjectOutput out = new ObjectOutputStream(bos)) {
        for (CustomObject obj : objList) {
            out.writeObject(obj);
        }
        return bos.toByteArray();
    } catch (IOException e) {
        throw new RuntimeException("Failed to serialize objects", e);
    }
}

public List<CustomObject> deserialize(byte[] data) {
    try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
         ObjectInput in = new ObjectInputStream(bis)) {
        List<CustomObject> objList = new ArrayList<>();
        while (true) {
            CustomObject obj = (CustomObject) in.readObject();
            objList.add(obj);
        }
    } catch (EOFException e) {
        // End of file reached, return list
        return objList;
    } catch (IOException | ClassNotFoundException e) {
        throw new RuntimeException("Failed to deserialize objects", e);
    }
}
