void process_file(const char* filename) {
    FILE *fp = fopen(filename, "rb");

    if (fp == NULL) {
        perror("Could not open file for reading\n");
        exit(-1);
    }

    /* Allocate a buffer of CHUNK_SIZE */
    char *buffer = malloc(CHUNK_SIZE);

    if (buffer == NULL) {
        perror("Could not allocate memory for buffer\n");
        exit(-1);
    }

    pthread_t threads[4]; /* create 4 worker threads */
    int i;
    while(fread(buffer, sizeof(char), CHUNK_SIZE, fp) == CHUNK_SIZE){
        for (i = 0; i < 4; ++i) {
            pthread_create(&threads[i], NULL, process_thread, buffer); /* start processing */
            buffer = malloc(CHUNK_SIZE); /* allocate new buffer for next chunk */
        } 

        for (i = 0; i < 4; ++i) {
            pthread_join(threads[i], NULL); /* wait for all threads to finish */
        } 
    }

    free(buffer); /* free the last buffer */
    fclose(fp);
}
