void processBatch(char* filename) {
    FILE* file = fopen(filename, "r");
    if(file == NULL){
        printf("Failed to open the file %s. Exiting...\n", filename);
        return;
    }

    LogEntry* entries = (LogEntry*)malloc(10000 * sizeof(LogEntry));
    int count = 0;

    char line[256];
    while(fgets(line, sizeof(line), file)) {
        if(count >= 10000) {
            printf("Maximum entries per batch limit reached. Exiting...\n");
            break;
        }

        LogEntry* entry = &entries[count++];
        sscanf(line, "%ld %m[^\n]", &entry->timestamp, &entry->message);
    }

    fclose(file);

    qsort(entries, count, sizeof(LogEntry), compare);

    // process entries here...
}

