    int error_code;
} TCP_CONNECTION_STATS;

typedef struct ListNode {
    void *data;
    struct ListNode *next;
} ListNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
ListNode *head = NULL;
int nodesCount = 0;

void* allocateAndInitialize(size_t dataSize, int type) {
    void *data = malloc(dataSize);

    if (data == NULL) {
        // handle error in memory allocation
    }

    pthread_mutex_lock(&lock);
    nodesCount++;
    ListNode* node = (ListNode*)malloc(sizeof(ListNode));

    if (node == NULL) {
        // handle error in memory allocation
    }

    node->data = data;
    node->next = head;
    head = node;
    pthread_mutex_unlock(&lock);

    return data;
}

void deallocate(ListNode* node) {
    if (node == NULL) {
        // handle error in NULL pointer dereference
    }

    free(node->data);

    pthread_mutex_lock(&lock);
    nodesCount--;
    ListNode *temp = head;

    if (head == node) {
        head = node->next;
    } else {
        while (temp != NULL) {
            if (temp->next == node) {
                temp->next = node->next;
                break;
            }

            temp = temp->next;
        }
    }

    free(node);
    pthread_mutex_unlock(&lock);
}
```
The above code snippet represents a basic implementation of thread-safe linked list with two different types of data. `allocateAndInitialize` function is used to dynamically allocate memory for the given size and type, lock the mutex before modifying the shared state, create new node, initialize it with allocated memory and add it to the head of the linked list. 

The `deallocate` function is used to safely deallocate memory by finding a corresponding node in the linked list, freeing its data and removing this node from the list. It also maintains the count of active nodes which can be used for load balancing and tracking system load.
