['This task requires advanced knowledge of C programming, concurrent programming, system design, network programming, and performance tuning. Here is a simplified solution using POSIX threads (pthreads) library for managing multiple threads and connection pool as linked list. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

typedef struct TCP_CONNECTION_RECORD {
    char IP_ADDRESS[16];
    int PORT;
    pthread_t CONN_ID;
    int STATUS; // 0 for inactive, 1 for active
} TCP_CONNECTION_RECORD;

typedef struct Node {
    TCP_CONNECTION_RECORD data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* handleConnection(void *args) {
    TCP_CONNECTION_RECORD *conn = (TCP_CONNECTION_RECORD*) args;
    sleep(rand() % 10); // Simulate connection handling
    printf("Handled Connection: %s\n", conn->IP_ADDRESS);
}

void addConnection(char* IP, int PORT) {
    pthread_mutex_lock(&lock);

    Node *newNode = (Node*)malloc(sizeof(Node));
    strcpy(newNode->data.IP_ADDRESS, IP);
    newNode->data.PORT = PORT;
    newNode->data.STATUS = 1; // Status to active

    pthread_create(&(newNode->data.CONN_ID), NULL, handleConnection, &(newNode->data));

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void closeInactiveConnections() {
    pthread_mutex_lock(&lock);

    Node *temp = head;
    while (temp != NULL) {
        if (temp->data.STATUS == 0 && pthread_join(temp->data.CONN_ID, NULL)) {
            printf("Closed Inactive Connection: %s\n", temp->data.IP_ADDRESS);
            Node *toRemove = temp;
            temp = temp->next;
            free(toRemove);
        } else {
            temp = temp->next;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
This is a simplified version of the code and does not fully satisfy all requirements such as timeouts, handling 1000 connections per second load etc. Also it assumes that there are separate threads for each connection which might not be feasible in real-world applications with high number of connections. Real implementation may need to consider other factors like TCP sliding window protocol, congestion control algorithms and error handling etc.
