#include <iostream>
#include <fstream>
#include <string>
#include <cpr/cpr.h> // For handling network requests in C++

int archiveToCloudStorage(const std::string& filePath, const std::string& cloudURL) {

    std::ifstream fileStream(filePath, std::ios::binary);

    if(!fileStream) {
        return -1; // Error opening file
    }

    cpr::Session session;
    session.SetUrl(cpr::Url{cloudURL});

    int retryCount = 0;
    const int maxRetries = 3;

    while (retryCount < maxRetries) {
        // Post the file to cloud storage
        cpr::Response response = session.Post();

        if(response.status_code == 200) {
            return 0; // Success
        } else {
            ++retryCount;
        }
    }

    return -1; // Error archiving to cloud storage
}
