    if(EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) { printf("Failed to initialize encryption\n"); return; }

    // Open file for reading and writing
    FILE *file = fopen(filename, "r+b");
    if(file == NULL) { printf("Failed to open file: %s\n", filename); return; }

    char buffer[1024]; // Buffer for reading/writing file content

    while(!feof(file)) {
