        unsigned char ciphertext[sizeof(buffer) + EVP_MAX_BLOCK_LENGTH]; // Buffer for encrypted/decrypted data
        if(!EVP_EncryptUpdate(ctx, ciphertext, &len, buffer, bytesRead)) { printf("Failed to update encryption\n"); return; }

