```java
import org.apache.commons.csv.*;
import org.apache.commons.math3.stat.descriptive.DescriptiveStatistics;
import java.io.*;
import java.time.*;
import java.util.*;

public class UserSessionAnalyzer {
    private static final int CRITICAL_FEATURES_THRESHOLD = 90; // Example threshold

    public void analyze(String logFilePath, int maxConcurrentSessions) {
        try (Reader reader = new FileReader(logFilePath)) {
            Iterable<CSVRecord> records = CSVFormat.RFC4180.parse(reader);
            Map<String, DescriptiveStatistics> userStatsMap = new HashMap<>();
            int totalSessions = 0;

            for (CSVRecord record : records) {
                String sessionId = record.get(0); // Assume first column is the session ID
                LocalDateTime startTime = LocalDateTime.parse(record.get(1)); // Second column is start time
                LocalDateTime endTime = LocalDateTime.parse(record.get(2)); // Third column is end time
                long durationMillis = Duration.between(startTime, endTime).toMillis();

                DescriptiveStatistics stats = userStatsMap.computeIfAbsent(sessionId, id -> new DescriptiveStatistics());
                stats.addValue(durationMillis);
                ++totalSessions;
            }

            for (String sessionId : userStatsMap.keySet()) {
                DescriptiveStatistics stats = userStatsMap.get(sessionId);
                double averageResponseTime = stats.getMean();
                int criticalFeaturesPercentage = 100 * stats.getSum() / totalSessions; // Assuming the sum is a count of critical features

                if (criticalFeaturesPercentage > CRITICAL_FEATURES_THRESHOLD) {
                    System.out.println("Alert: User session " + sessionId 
                            + " has an average response time of " + averageResponseTime 
                            + " and interacted with critical features for " + criticalFeaturesPercentage + "% of the time.");
                }
            }

        } catch (IOException e) {
            System.err.println("Error reading log file: " + e);
        }
    }
}
```
This code block reads a CSV log file with each row representing a user session, where the first column is the session ID, second column is the start time of the session and third column is the end time. It calculates the average response times for each user session and generates an alert if this exceeds the specified threshold. Please note that you would need to adapt this code to your specific requirements, such as reading from a different format or using different libraries for parsing/statistics.
