    int rnti;
    float crc_flag_state;
} RNTIData;

// Global variables for managing multi-threading and AES cipher context
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
EVP_CIPHER_CTX *ctx;
char key[32], iv[16];
int isPersistent = 0;

// Function to initialize AES-256-CBC cipher with given password and salt
void initAES(const char* password, const unsigned char* salt) {
    pthread_mutex_lock(&mutex);

    if (!isPersistent || ctx == NULL) {
        // Derive key and IV from the password using OpenSSL's PKCS5_PBKDF2_HMAC function
        PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt), 1000, EVP_sha256(), 32, key);
        RAND_bytes(iv, 16);

        // Initialize the cipher context with AES-256-CBC and our derived key and IV
        ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    }

    pthread_mutex_unlock(&mutex);
}

// Function to encrypt and rename a file using the AES-256-CBC cipher
void encryptAndRenameFile(const char* filename, const char* newExtension) {
    // Initialize cipher if not already done
    initAES("password", NULL);

    FILE *infile = fopen(filename, "rb");
    if (!infile) {
        printf("Error opening input file\n");
        return;
    }

    // Open output file with new extension
    char outFilename[256];
    snprintf(outFilename, sizeof(outFilename), "%s.%s", filename, newExtension);
    FILE *outfile = fopen(outFilename, "wb");
    if (!outfile) {
        printf("Error opening output file\n");
        return;
    }

    // Read input file in chunks and encrypt each chunk before writing to the output file
    unsigned char buffer[4096], encryptedBuffer[4096 + EVP_MAX_BLOCK_LENGTH];
    int bytesRead, outLength;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), infile)) > 0) {
        if (!EVP_EncryptUpdate(ctx, encryptedBuffer, &outLength, buffer, bytesRead)) {
            printf("Error encrypting data\n");
            return;
        }

        fwrite(encryptedBuffer, 1, outLength, outfile);
    }

    // Finalize encryption and write the last chunk of encrypted data
    if (!EVP_EncryptFinal_ex(ctx, encryptedBuffer, &outLength)) {
        printf("Error finalizing encryption\n");
        return;
    }
    fwrite(encryptedBuffer, 1, outLength, outfile);

    // Close input and output files
    fclose(infile);
    fclose(outfile);
}

// Function to handle large binary log files (processEncryptAndRenameBinaryLog)
void processEncryptAndRenameBinaryLog(const char* filename, const char* password, int newExtensionDigits, int persistentCipher) {
    isPersistent = persistentCipher;

    // Generate a salt and initialize AES-256-CBC cipher with given password and salt
    unsigned char salt[8];
    RAND_bytes(salt, sizeof(salt));
    initAES(password, salt);

    // Encrypt and rename the file using the derived key and IV
    encryptAndRenameFile(filename, generateExtension(newExtensionDigits));
}
