#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

Node* create(int val) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        return NULL;
    }
    new_node->value = val;
    new_node->next = NULL;
    return new_node;
}

void append(Node** head, Node* node_to_add) {
    if (!(*head)) {
        *head = node_to_add;
        return;
    }

    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = node_to_add;
}

void display(Node* head) {
    Node* list = head;
    while (list != NULL) {
        printf("%d ", list->value);
        list = list->next;
    }
    printf("\n");
}
