function processEncryptAndRenameBinaryLog($filePath, $outputDir) {
    // Open file for reading
    $inputFile = fopen($filePath, 'rb');
    if ($inputFile === false) {
        throw new Exception('Failed to open input file.');
    }

    // Generate output file path
    $outputFilePath = $outputDir . '/' . basename($filePath);

    // Open output file for writing
    $outputFile = fopen($outputFilePath, 'wb');
    if ($outputFile === false) {
        throw new Exception('Failed to open output file.');
    }

    // Read and write data in chunks
    while (!feof($inputFile)) {
        $data = fread($inputFile, 8192);
        if ($data === false) {
            throw new Exception('Failed to read from input file.');
        }

        $success = fwrite($outputFile, $data);
        if ($success === false) {
            throw new Exception('Failed to write to output file.');
        }
    }

    // Close files
    fclose($inputFile);
    fclose($outputFile);
}
```
