```c
#include <stdlib.h>
#include <string.h>
#define MAX_STATES 100 // define maximum states

// Structure for state list
typedef struct StateList {
    int* states;
    int size;
} StateList;

StateList* createStateList(int* array, int numOfElements) {
    StateList* sl = (StateList*)malloc(sizeof(StateList));
    if (!sl) {
        printf("Error: Out of memory.\n");
        return NULL; // handle out of memory error
    }

    sl->states = (int*)malloc(numOfElements * sizeof(int));
    if(!sl->states){
        free(sl); 
        printf("Error: Out of memory.\n");
        return NULL; // handle out of memory error
    }

    memcpy(sl->states, array, numOfElements * sizeof(int));
    sl->size = numOfElements;

    printf("Successfully created state list with %d elements.\n", numOfElements); 
    return sl;
}

StateList* appendToStateList(StateList* oldSl, int* array, int numOfElements) {
    if (oldSl->size + numOfElements > MAX_STATES) {
        printf("Error: Exceeding maximum states.\n"); 
        return NULL; // handle error, list will not be modified.
    }

    oldSl->states = (int*)realloc(oldSl->states, (oldSl->size + numOfElements) * sizeof(int));
    if(!oldSl->states){
        printf("Error: Out of memory.\n"); 
        return NULL; // handle out of memory error
    }

    memcpy(&oldSl->states[oldSl->size], array, numOfElements * sizeof(int));
    oldSl->size += numOfElements;
    printf("Successfully appended %d elements to state list.\n", numOfElements); 
    return oldSl;
}

StateList* replaceStateList(StateList* oldSl, int* array, int numOfElements) {
    if (numOfElements > MAX_STATES) {
        printf("Warning: Exceeding maximum states. Truncating the list.\n"); 
        numOfElements = MAX_STATES;
    }

    free(oldSl->states); // free old memory
    oldSl->states = (int*)malloc(numOfElements * sizeof(int));
    if(!oldSl->states){
        printf("Error: Out of memory.\n"); 
        return NULL; // handle out of memory error
    }

    memcpy(oldSl->states, array, numOfElements * sizeof(int));
    oldSl->size = numOfElements;
    printf("Successfully replaced state list with %d elements.\n", numOfElements); 
    return oldSl;
}
```
Please note that the above code snippet doesn't include error checking and memory management for edge cases, missing features like logging or external data storage system integration, but it gives a basic idea of how to implement such functionality in C. You should add those features as per your requirement. 

