Thread-Safe Queue in C: 
```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>

typedef struct {
    int capacity;
    void **items;
    int front;
    int rear;
    sem_t mutex;
    sem_t slots;
    sem_t itemsSem;
} Queue;

void queueInit(Queue *q, int capacity) {
    q->capacity = capacity;
    q->items = malloc(sizeof(void*) * capacity);
    q->front = 0;
    q->rear = 0;
    sem_init(&q->mutex, 0, 1);
    sem_init(&q->slots, 0, capacity);
    sem_init(&q->itemsSem, 0, 0);
}

void enqueue(Queue *q, void *item) {
    sem_wait(&q->slots);
    sem_wait(&q->mutex);

    q->items[q->rear] = item;
    q->rear = (q->rear + 1) % q->capacity;

    sem_post(&q->mutex);
    sem_post(&q->itemsSem);
}
```

Please note that this is a very simplified example and does not include all the necessary error handling or testing.  Also, for memory allocation failures gracefully it's recommended to use `malloc` function which returns NULL if the allocation fails. You can check if `malloc` returned NULL before using the pointer to avoid potential crashes.
