#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#define MAX_ENTRIES 1000000
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[32];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LogFileInfo{
    FILE* file;
    long startPos;
    long endPos;
    int threadId;
} LogFileInfo;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int uniqueRNTICount = 0;
double averageCRCFLAG = 0.0;

void* processLogSegment(void *args) {
    LogFileInfo *info = (LogFileInfo*) args;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    fseek(info->file, info->startPos, SEEK_SET);
    for(long i=info->startPos; i<info->endPos && !feof(info->file); i += sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, info->file);
        pthread_mutex_lock(&lock);
        uniqueRNTICount++;
        averageCRCFLAG += (double) pdu.CRC_INDICATION_REL8_TAG[0] / MAX_ENTRIES;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void processLogFile(char* filename, int numThreads){
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening the file\n");
        exit(1);
    }
    fseek(file, 0L, SEEK_END);
    long size = ftell(file);

    pthread_t threads[numThreads];
    LogFileInfo infos[numThreads];
    for (int i = 0; i < numThreads; ++i) {
        infos[i].startPos = i*(size/numThreads);
        if(i != numThreads-1){
            infos[i].endPos   = (i+1)*(size/numThreads);
        }else{
            infos[i].endPos   = size;
        }
        infos[i].file = file;
        infos[i].threadId = i;

        if(pthread_create(&threads[i], NULL, processLogSegment, &infos[i])) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL); 
    }
    printf("Unique RNTI Count: %d\n", uniqueRNTICount);
    printf("Average CRCFLAG: %.2f\n", averageCRCFLAG);
    fclose(file);
}
```
