import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import javax.xml.bind.DatatypeConverter;
import java.security.MessageDigest;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

public class HashingService {
    private static final Pattern SPECIAL_CHARACTERS = Pattern.compile("[^a-z0-9 ]", Pattern.CASE_INSENSITIVE);
    private static final Logger logger = LoggerFactory.getLogger(HashingService.class);

    private Cache<String, String> cache;
    private int count = 0;

    public HashingService() {
        this.cache = CacheBuilder.newBuilder().maximumSize(10_000).expireAfterWrite(2, TimeUnit.HOURS).build(); 
    }

    public synchronized String computeHash(String input) {
        if (input == null || input.length() > 2048 || SPECIAL_CHARACTERS.matcher(input).find()) {
            return null;
        }

        String hash = cache.getIfPresent(input);

        if (hash != null) { 
            logger.debug("{}: using cached hash for {}", prefix, input);
            return hash;
        } else { 
            count++;

            try {
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                byte[] hashBytes = digest.digest(input.getBytes("UTF-8"));
                hash = DatatypeConverter.printHexBinary(hashBytes).toLowerCase();

                logger.debug("{}: computed hash for {}: {}", prefix, input, hash);
                cache.put(input, hash); 
            } catch (Exception e) {
                logger.error("Error in hashing", e);
                return null;
            }
        }

        return hash;
    }

    public int getCount() {
        return count;
    }
}
```
