} DataTransferRequest;

DataTransferRequest* requests = NULL;
int requestCount = 0;

void addRequest(int session_id, const char* destination_address, size_t data_payload_size) {
    for (int i=0; i<requestCount; i++){
        if(requests[i].session_id == session_id){
            // Handle existing session ID
            return;
        }
    }

    requestCount++;
    requests = realloc(requests, sizeof(DataTransferRequest) * requestCount);

    DataTransferRequest newRequest = {session_id, strdup(destination_address), data_payload_size};
    requests[requestCount-1] = newRequest;
}

void updateRequest(int session_id, const char* destination_address, size_t data_payload_size) {
    for (int i=0; i<requestCount; i++){
        if(requests[i].session_id == session_id){
            free(requests[i].destination_address);
            requests[i].destination_address = strdup(destination_address);
            requests[i].data_payload_size = data_payload_size;
            return;
        }
    }

    // Handle non-existing session ID
}

void removeRequest(int session_id) {
    for (int i=0; i<requestCount; i++){
        if(requests[i].session_id == session_id){
            free(requests[i].destination_address);

            // Shift all elements after the one to be removed up by one position.
            for (int j=i+1; j<requestCount; j++) {
                requests[j-1] = requests[j];
            }

            requestCount--;
            requests = realloc(requests, sizeof(DataTransferRequest) * requestCount);
            return;
        }
    }

    // Handle non-existing session ID
}
```
