Here is the C code for a simple thread-safe queue using pthreads and condition variables:

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>

typedef struct {
    int capacity;
    void **data;
    int front, rear;
    pthread_mutex_t lock;
    sem_t count, spaces;
} queue_t;

void* dequeue(queue_t *q) {
    void* item = NULL;
    sem_wait(&q->count);
    pthread_mutex_lock(&q->lock);

    item = q->data[q->front];
    q->front = (q->front + 1) % q->capacity;

    pthread_mutex_unlock(&q->lock);
    sem_post(&q->spaces);

    return item;
}

void enqueue(queue_t *q, void* _item) {
    sem_wait(&q->spaces);
    pthread_mutex_lock(&q->lock);

    q->data[q->rear] = _item;
    q->rear = (q->rear + 1) % q->capacity;

    pthread_mutex_unlock(&q->lock);
    sem_post(&q->count);
}
``` 
