```c
#include <openssl/evp.h>
#include <openssl/err.h>
#include <stdio.h>
#include <string.h>

void handleErrors(void) {
  ERR_print_errors_fp(stderr);
  abort();
}

int encryptFile(const char* inPath, const char* outPath, const EVP_CIPHER *cipher){

  // Initialize the context and other necessary variables
  EVP_CIPHER_CTX *ctx;
  FILE *infile, *outfile;
  int len;
  unsigned char inbuf[1024], outbuf[1024 + EVP_MAX_BLOCK_LENGTH];

  // Open the input file for reading and output file for writing. Handle errors if necessary
  infile = fopen(inPath, "rb");
  if(!infile) { perror("fopen: inpath"); return -1; }

  outfile = fopen(outPath, "wb");
  if(!outfile) { perror("fopen: outpath"); return -2; }

  // Initialize the encryption operation. Clean up if it fails.
  ctx = EVP_CIPHER_CTX_new();
  if(ctx == NULL) handleErrors();

  // Initialize the cipher with the chosen algorithm
  if(1 != EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL))
    handleErrors();

  // Read from input file and write to output file. Handle errors if necessary.
  for(;;) {
    len = fread(inbuf, 1, sizeof inbuf, infile);
    if (len <= 0) break;

    if(!EVP_EncryptUpdate(ctx, outbuf, &len, inbuf, len)) handleErrors();
    if (!fwrite(outbuf, 1, len, outfile)) handleErrors();
  }

  // Finalize the encryption process and write the remaining bytes. Handle errors if necessary.
  if(!EVP_EncryptFinal_ex(ctx, outbuf, &len)) handleErrors();
  if (!fwrite(outbuf, 1, len, outfile)) handleErrors();

  EVP_CIPHER_CTX_free(ctx);
  fclose(infile);
  fclose(outfile);

  return 0;
}
```

