```cpp
#include <iostream>
#include <unordered_map>
#include <shared_mutex>
#include <atomic>
#include <vector>
#include <algorithm>
#include <thread>

template<typename Key, typename Value>
class DistributedKeyValueStore {
private:
    std::unordered_map<Key, Value> store;
    mutable std::shared_mutex mtx;  // For concurrency control
    std::atomic<std::size_t> memoryUsed{0}; // To monitor memory usage

public:
    void set(const Key &key, const Value &value) {
        std::unique_lock<std::shared_mutex> lock(mtx);  // For exclusive access

        auto it = store.find(key);
        if (it != store.end()) {
            memoryUsed -= sizeof(Key) + sizeof(Value); // If key already exists, subtract old size before updating value
        }

        store[key] = value;
        memoryUsed += sizeof(Key) + sizeof(Value);  // Update the memory used by adding new size
    }

    Value get(const Key &key) const {
        std::shared_lock<std::shared_mutex> lock(mtx);  // For shared access

        auto it = store.find(key);
        if (it != store.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Key not found");
        }
    }
};
```
