char* handleStringAndAppendSlash(const char* inputStr, size_t limit, FILE* fp) {
    if (inputStr == NULL || fp == NULL) {
        return NULL;
    }

    size_t len = strlen(inputStr);
    if (len >= limit) {
        return NULL;
    }

    char* outputStr = malloc(len + 2);
    if (outputStr == NULL) {
        return NULL;
    }

    memcpy(outputStr, inputStr, len);
    outputStr[len] = '/';
