// Define logging severity levels
typedef enum {DEBUG, INFO, WARNING, ERROR} Severity;

// Logger structure to hold log buffer and configuration
typedef struct Logger {
    char buffer[10000];
    int index;
    time_t lastLogTime;
    Severity severityThreshold;
} Logger;

Logger logger;
AES_KEY aesKey;

// Initialize logger with threshold from environment variable and start log rolling.
void initLogger(Severity threshold) {
    // Set severity threshold based on environment variable
    logger.severityThreshold = threshold;
    // Start timer for rate limiting
    logger.lastLogTime = time(NULL);
}

// Log a message with specified severity level
void logMessage(Severity severity, const char *format, ...) {
    if (severity >= logger.severityThreshold && difftime(time(NULL), logger.lastLogTime) > 60) {
        va_list args;
        va_start(args, format);

        vsnprintf(&logger.buffer[logger.index], 10000 - logger.index, format, args);
        logger.index += strlen(&logger.buffer[logger.index]);

        if (logger.index >= 10000) {
            logger.index = 0; // Start overwriting from the beginning of buffer
        }

        va_end(args);
    }
}

// Initialize AES-256 CBC cipher with given password
void initAESCipher(const char *password) {
    unsigned char key[SHA512_DIGEST_LENGTH];

    // Check password length
    if (strlen(password) < 8 || strlen(password) > 64) {
        logMessage(ERROR, "Password length is not between 8 and 64 characters.");
        return;
    }

    SHA512((unsigned char*) password, strlen(password), key); // Derive encryption key from password using SHA-512 hash function.
    AES_set_encrypt_key(key, 256, &aesKey); // Set cipher key and start encryption.
}
```

