typedef struct Cache{
    pthread_mutex_t lock;
    int size;
    ResourceBundle** bundles;
}Cache;

typedef struct Config{
    enum format format;
    char* path;
    int cacheEnabled;
}Config;

static void *loadResource(void *arg);

pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER; 

void manageResources(Cache* cache, Config* config){

    pthread_mutex_lock(&config->lock); /* Lock the configuration to ensure it doesn't change during loading */

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle)); 
    bundle->format = config->format;
    bundle->path = strdup(config->path); 

    /* load data from file */
    pthread_t thread;
    if (pthread_create(&thread, NULL, loadResource, bundle)){
        fprintf(stderr,"Error creating thread\n");
        return;
    }
    if (config->cacheEnabled){
        /* Lock cache for write access and add resource to it */
        pthread_mutex_lock(&cache->lock); 
        cache->bundles[cache->size++] = bundle; 
        pthread_mutex_unlock(&cache->lock); 
    }

    pthread_join(thread, NULL); /* Wait for resource to be loaded */

    /* Log that the resource is loaded successfully or failed */
    pthread_mutex_lock(&logMutex); 
    if (bundle->data == NULL){
        fprintf(stderr,"Error loading resource from path %s\n", bundle->path);
    } else {
        printf("Successfully loaded resource from path %s\n", bundle->path);
    }
    pthread_mutex_unlock(&logMutex); 

    pthread_mutex_unlock(&config->lock); /* Unlock the configuration */
}

static void *loadResource(void *arg){
    ResourceBundle* bundle = (ResourceBundle*) arg;
    FILE *file;
    switch(bundle->format) {
        case JSON: 
            file = fopen(bundle->path, "r");
            if (!file) break;
            /* load and parse JSON */
            break;

        case XML: 
            file = fopen(bundle->path, "r");
            if (!file) break;
            /* load and parse XML */
            break;

        case YAML: 
            file = fopen(bundle->path, "r");
            if (!file) break;
            /* load and parse YAML */
            break;
    }

    if (file){
        fclose(file);
        return bundle;
    } else {
        free(bundle->path);
        free(bundle);
        return NULL;
    }
}
