        reports[i].CSI_REFERENCE_SIGNAL = ((float)rand() / RAND_MAX) * (highQualityScoreRange - lowQualityScoreRange) + lowQualityScoreRange;  // random score within range
        reports[i].CHANNEL_ESTIMATION_RESULT = rand();  // assign valid CHANNEL_ESTIMATION_RESULT
    }
    return reports;
}

