    OpenSSL_add_all_algorithms();  // load all OpenSSL algorithms
    CryptoFunc *funcs = (CryptoFunc *)malloc(EVP_get_cipher_count() + EVP_get_digest_count() * sizeof(CryptoFunc));  // allocate memory
    if (!funcs) {
        perror("Failed to allocate memory");
        return NULL;
    }

