    for (int j = 0; j < EVP_get_digest_count(); j++, i++) {  // load hash functions
        funcs[i].name = (char *)EVP_get_digests()[j].name;
        funcs[i].func = dlsym(RTLD_DEFAULT, funcs[i].name);
    }

    for (int j = 0; j < EVP_get_cipher_count(); j++, i++) {  // load ciphers
        funcs[i].name = (char *)EVP_get_ciphers()[j].name;
        funcs[i].func = dlsym(RTLD_DEFAULT, funcs[i].name);
    }

    return funcs;
}
