char* appendNewline(const char *str, size_t limit, FILE *fp) {
    if (str == NULL || fp == NULL) return NULL; // Error handling for null pointers

    size_t len = strlen(str);
    if (len >= limit) return NULL; // String exceeds limit

    char *newStr = malloc(len + 2); // +1 for newline, +1 for terminating null character
    if (newStr == NULL) return NULL; // Error handling for memory allocation failure

    memcpy(newStr, str, len); // Copy the string contents to new memory location
    newStr[len] = '\n'; // Append a newline
    newStr[len + 1] = '\0'; // Add terminating null character

