#define MAX_CONCURRENT_SESSIONS 10000

typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T{
    RX_UE_INFORMATION_TAG ueInfo;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

static omp_lock_t lock;
static int currentIndex = 0;
static NFAPI_CRC_INDICATION_PDU_T *structArray = NULL;

void initializeStructure(int RNTI, int CRCFLAG) {
    structArray[currentIndex].ueInfo.RNTI = RNTI;
    structArray[currentIndex].crcTag.CRCFLAG = CRCFLAG;
}

NFAPI_CRC_INDICATION_PDU_T* getNFAPICRCIndicationPDUT(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;

    omp_set_lock(&lock);  // Ensure thread safety.

    if (currentIndex < MAX_CONCURRENT_SESSIONS) {
        pdu = &structArray[currentIndex];
        ++currentIndex;
    } else {
        currentIndex = 0;  // Reuse structures.
    }

    omp_unset_lock(&lock);

    return pdu;
}

