class ConnectionPool {
public:
    static std::shared_ptr<Connection> getConnection() {
        std::lock_guard<std::mutex> lock(m_mutex);

        if (!m_freeConnections.empty()) {
            auto conn = m_freeConnections.back();
            m_freeConnections.pop_back();
            return conn;
        }

        // If there are no free connections, create a new one and add to pool
        std::shared_ptr<Connection> conn(new Connection);
        m_connections.push_back(conn);
        return conn;
    }

    static void releaseConnection(std::shared_ptr<Connection>& connection) {
        if (connection != nullptr) {
            std::lock_guard<std::mutex> lock(m_mutex);

            // Clear the connection's data and add it to the free list
            connection->clientIP.clear();
            m_freeConnections.push_back(connection);
        }
    }

private:
    static std::vector<std::shared_ptr<Connection>> m_connections;
    static std::vector<std::shared_ptr<Connection>> m_freeConnections;
    static std::mutex m_mutex;
};

