```java
import com.google.gson.Gson;
import org.apache.commons.codec.binary.Base64;

public byte[] serializeAndEncrypt(Object data, String password) {
    // Serialize the object to JSON
    Gson gson = new Gson();
    String jsonData = gson.toJson(data);
    byte[] plainTextBytes = jsonData.getBytes();

    // Derive key and IV using PBKDF2 with SHA-256
    byte[] salt = "Random_Salt".getBytes(); // Ideally you should use a different salt for each encryption operation to prevent rainbow table attacks
    KeySpec spec = new PBEKeySpec(password.toCharArray(), salt, 65536, 256);
    SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
    byte[] derivedBytes = factory.generateSecret(spec).getEncoded();
    Key key = new SecretKeySpec(derivedBytes, "AES");  // AES as example for symmetric encryption cipher.

    // Initialize the cipher with derived key and IV
    Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
    cipher.init(Cipher.ENCRYPT_MODE, key);
    AlgorithmParameters params = cipher.getParameters();
    byte[] iv = params.getParameterSpec(IvParameterSpec.class).getIV(); // Use the generated IV for encryption and send it separately to decrypting party (insecure but simpler)

    // Encrypt the data
    byte[] encryptedBytes = cipher.doFinal(plainTextBytes);

    return Base64.encodeBase64(encryptedBytes);
}
```
Thread-safe queue in C:
```C
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int capacity;
    void **items;
    int front;
    int rear;
    int count;
    sem_t mutex, full, empty;
} Queue;

void queueInit(Queue *q, int capacity) {
    q->capacity = capacity;
    q->items = malloc(sizeof(*q->items) * q->capacity);
    q->front = 0;
    q->rear = -1;
    q->count = 0;

    sem_init(&q->mutex, 0, 1); // Binary Semaphore
    sem_init(&q->full, 0, 0); // Starts at 0 because it is empty
    sem_init(&q->empty, 0, capacity); // Starts at capacity because queue starts out full of NULL elements
}

void enqueue(Queue *q, void *item) {
    sem_wait(&q->empty); // Wait for there to be an empty slot
    sem_wait(&q->mutex); // Lock the queue

    q->rear = (q->rear + 1) % q->capacity;
    q->items[q->rear] = item;
    q->count++;

    sem_post(&q->mutex); // Unlock the queue
    sem_post(&q->full); // Signal that there is now at least one element in the queue
}

void *dequeue(Queue *q) {
    sem_wait(&q->full); // Wait for there to be an item to dequeue
    sem_wait(&q->mutex); // Lock the queue

    void *item = q->items[q->front];
    q->items[q->front] = NULL;
    q->front = (q->front + 1) % q->capacity;
    q->count--;

    sem_post(&q->mutex); // Unlock the queue
    sem_post(&q->empty); // Signal that there is now at least one empty slot

    return item;
}
```
Please note that this is a simplified version. Real world applications would need more comprehensive error handling, proper memory management, encryption key and IV management (possibly externalized to a secure vault service), logging, unit tests, etc. Also, you might want to use some form of continuous integration and delivery pipeline for automated testing and deployment.
