['Here is an example of how you might approach this task:

```java
import java.security.*;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import org.apache.log4j.Logger;

public class UniqueIdentifierGenerator {
    static final Logger logger = Logger.getLogger(UniqueIdentifierGenerator.class);

    /** 
    * Generates a secure, unique identifier from a given input string using SHA-256 algorithm.
    * @param input - The input string for which the unique identifier is to be generated
    * @return A Base64 encoded string of the hashed output that represents the unique identifier
    */ 

    public String generateUniqueIdentifier(String input) {
        try {
            long startTime = System.currentTimeMillis();

            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
            String base64Hash = Base64.getEncoder().encodeToString(hashBytes);

            long endTime = System.currentTimeMillis();
            logger.info("Processing time for input " + input + ": " + (endTime - startTime) + "ms");

            return base64Hash;
        } catch (NoSuchAlgorithmException e) {
            logger.error("Failed to generate unique identifier", e);
            throw new RuntimeException(e); // propagate error if necessary
        }
    }
}
