public class UniqueIdentifierGenerator {

    // Assuming you have an existing logging framework, like Apache Commons Logging.
    private static final Log log = LogFactory.getLog(UniqueIdentifierGenerator.class);

    public String generateUniqueId(String input) {
        long startTime = System.currentTimeMillis();

        try {
            return DigestUtils.sha256Hex(input);
        } catch (Exception e) {
            log.error("Failed to generate unique id", e);
            throw new RuntimeException(e);
        } finally {
            long endTime = System.currentTimeMillis();
            log.info("Processing time: " + (endTime - startTime));
        }
    }

    public List<String> generateUniqueIdsInBulk(List<String> inputs) {
        return inputs.parallelStream()
                .map(input -> CompletableFuture.supplyAsync(() -> generateUniqueId(input)))
                .collect(Collectors.toList())
                .stream()
                .map(CompletableFuture::join)
                .collect(Collectors.toList());
    }
}
