        key[i] = hashedPassword[i % SHA_DIGEST_LENGTH];
    }

    for (int i = 0; i < EVP_MAX_IV_LENGTH; ++i) {
        iv[i] = hashedPassword[(i + EVP_MAX_KEY_LENGTH) % SHA_DIGEST_LENGTH];
    }

    // Initialize cipher context with key and IV
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        throw std::runtime_error("Failed to initialize cipher");
    }

    // Initialize octree here...
    Octree* octree;
    try {
        octree = new Octree(featureSize, leafNodesCount, dataCapacity);
