#include <octree.hpp>  // Assume we have an Octree class defined in this header

// AES-256-CBC key and IV length
const int KEY_LEN = 32; 
const int IV_LEN  = 16;

struct CipherContext {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[KEY_LEN];
    unsigned char iv[IV_LEN];
};

std::shared_ptr<Octree> initializeEncryptionOctree(const std::string& password, size_t featureSize, 
                                                 size_t numLeafNodes, size_t dataCapacity) {
    // SHA-1 hash of the password to derive AES key and IV
    unsigned char shaResult[SHA_DIGEST_LENGTH];
    SHA1(reinterpret_cast<const unsigned char*>(password.c_str()), 
         password.length(), shaResult);

    // Derive Key and IV from the SHA-1 result
    unsigned char key[KEY_LEN];
    unsigned char iv[IV_LEN];
    memcpy(key, shaResult, KEY_LEN);
    memcpy(iv,  &shaResult[SHA_DIGEST_LENGTH - IV_LEN], IV_LEN);

    // Initialize AES-256-CBC cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == nullptr || EVP_EncryptInit(ctx, EVP_aes_256_cbc(), key, iv) != 1) {
        throw std::runtime_error("Failed to initialize AES-256-CBC cipher context");
    }

    // Create and return CipherContext struct
    auto cipherCtx = std::make_shared<CipherContext>(ctx, key, iv);

    // Create the octree
    auto octree = std::make_shared<Octree>(featureSize, numLeafNodes, dataCapacity, cipherCtx);

    return octree;
}
``` 
