            this.file = file;
        }

        @Override
        public Void call() throws Exception {
            List<String> lines = FileUtils.readLines(file, "UTF-8");

            // Perform transformations on lines here...

            FileUtils.writeLines(new File("output/" + file.getName()), lines);

            return null;
        }
    }

    public void processFilesInDirectory(File directory) {
        List<File> files = Arrays.asList(directory.listFiles());

        Stopwatch stopwatch = Stopwatch.createStarted();
        int processed = 0;

        for (File file : files) {
            if (!file.isDirectory()) {
                queue.add(file);
                ++processed;
                executor.submit(new TransformTask(file));
            }

            // This is a simple heuristic and does not take into account actual processing speed, system load, etc.
            if (queue.size() >= BATCH_SIZE) {
                try {
                    queue.take();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        System.out.println("Processed " + processed + " files in " + stopwatch);
    }
}
