```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <zlib.h>

typedef struct {
    int TX_POWER_LEVEL;
    int TX_ANTENNA_ID;
} LTE_PHY_TEST_TX_PARAMS;

typedef struct {
    float SNR;
    float BER;
} LTE_PHY_TEST_RX_STATS;

typedef struct Node {
    LTE_PHY_TEST_TX_PARAMS txParams;
    LTE_PHY_TEST_RX_STATS rxStats;
    struct Node* next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;

void* populateData(void* arg) {
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed!\n");
        exit(-1);
    }

    srand(time(NULL));
    int txPowerLevel = rand();
    int antennaId = rand();

    float snr = ((float)rand()/(float)(RAND_MAX)) * 50;
    float ber = ((float)rand()/(float)(RAND_MAX)) * 1.0;

    newNode->txParams.TX_POWER_LEVEL = txPowerLevel;
    newNode->txParams.TX_ANTENNA_ID = antennaId;
    newNode->rxStats.SNR = snr;
    newNode->rxStats.BER = ber;

    if (head == NULL) {
        head = newNode;
    } else {
        Node* temp = head;
        while (temp->next != NULL) {
            if ((temp->txParams.TX_POWER_LEVEL == txPowerLevel && 
                 temp->txParams.TX_ANTENNA_ID == antennaId) || 
                (temp->rxStats.SNR == snr && temp->rxStats.BER == ber)) {
                printf("Duplicate entry detected!\n");
                free(newNode);
                pthread_mutex_unlock(&lock);
                return NULL;
            }
            temp = temp->next;
        }
        temp->next = newNode;
    }

    printf("Populated data: TX_POWER_LEVEL: %d, TX_ANTENNA_ID: %d, SNR: %.2f, BER: %.2f\n", 
           txPowerLevel, antennaId, snr, ber);

    pthread_mutex_unlock(&lock);

    return NULL;
}
```
