void wifiScan(int n, float threshold) {
    FILE *file = fopen("wifi_scan.bin", "wb");

    if (file == NULL) {
        printf("Failed to create file.\n");
        exit(-1);
    }

    WIFI_SCAN_RESULTS *results = malloc(sizeof(WIFI_SCAN_RESULTS) * n);

    if (results == NULL) {
        printf("Failed to allocate memory.\n");
        exit(-1);
    }

    for (int i = 0; i < n; ++i) {
        sprintf(results[i].ssid, "SSID%d", i + 1);
        sprintf(results[i].bssid, "BSSID%d", i + 1);
        results[i].rssi = rand() % 100;
        results[i].stats.latency = rand() % 5000;
        results[i].stats.packetLossPercentage = 100.0f * rand() / RAND_MAX;

        if (results[i].stats.packetLossPercentage > threshold) {
            fwrite(&results[i], sizeof(WIFI_SCAN_RESULTS), 1, file);
        }
    }

    printf("Processed %d elements.\n", n);
    fclose(file);
    free(results);
}
