#include <dirent.h>
#include <stdio.h>
#include <string.h>
#include <openssl/sha.h> /* For SHA256 */
#include <sys/stat.h>
#include <time.h>

/* Function to calculate the SHA256 hash of a file */
unsigned char* calc_hash(const char *filename) {
    FILE *file = fopen (filename, "rb");
    if (!file) return NULL;

    unsigned char *hash = malloc(SHA256_DIGEST_LENGTH);
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    const int bufSize = 32768; /* Read 32Kb at a time */
    unsigned char *buffer = malloc(bufSize);
    size_t bytesRead = 0;
    while ((bytesRead = fread(buffer, 1, bufSize, file))) {
        SHA256_Update(&ctx, buffer, bytesRead);
    }

    SHA256_Final(hash, &ctx);
    free(buffer);
    return hash;
}

int main() {
    DIR *dir = opendir("."); /* Open current directory */
    if (dir != NULL) {
        struct dirent *ent;

        while ((ent = readdir(dir)) != NULL) {
            char new_name[256] = "";

            unsigned long time_now = time(NULL);
            sprintf(new_name, "%lu", time_now); /* Append timestamp */

            if (ent->d_type != DT_DIR) { 
