```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#define MAX_SIZE 5000
#define MIN_SIZE 3000
#define NUM_RETAINED 1000

typedef struct {
    int rssi;
    double throughput;
    float latency;
} WIFI_NETTEST_STATS;

typedef struct {
    short channelID;
    char txPowerLevel;
    WIFI_NETTEST_STATS stats;
} WIFI_NETTEST_CONFIG;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
WIFI_NETTEST_CONFIG* configs = NULL;
int currentSize = 0;
FILE *filePtr;
char fileName[]="wifiData.bin";

void populateStructure(WIFI_NETTEST_CONFIG* element){
    element->channelID = rand(); 
    element->txPowerLevel = rand() % 100; 
    element->stats.rssi = rand() % 120 - 60; 
    element->stats.throughput = 5 * (double)rand() / (RAND_MAX); 
    element->stats.latency = (float)rand() / RAND_MAX;
}

int addElement(){
    pthread_mutex_lock(&lock);

    if(currentSize >= MAX_SIZE){
        fprintf(stderr, "Cannot exceed maximum size!\n");
        return -1;
    }

    configs = realloc(configs, sizeof(*configs) * (currentSize + 1)); 
    if(!configs){
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Failed to allocate memory for new element!\n");
        return -2;
    }

    populateStructure(&configs[currentSize++]); 

    if(ftell(filePtr) > 8*1024*1024){
        fprintf(stderr, "File size exceeds limit!\n");
        return -3;
    }

    fwrite(&configs[currentSize-1], sizeof(*configs), 1, filePtr);

    if (currentSize > MIN_SIZE){
      configs = &configs[currentSize - NUM_RETAINED];
      currentSize = NUM_RETAINED;
    }

    pthread_mutex_unlock(&lock);

    return 0;
}
```
This code creates a structure array and populates it with random data. It also opens a file to write the serialized data into it, which is checked for size limit before writing. The function allows for adding new elements ensuring thread safety. If memory allocation fails, or if the current dataset exceeds 3000, it prunes old configurations to free up memory. This code assumes that the CHANNEL_ID and TX_POWER_LEVEL values can be represented with a short and char respectively.
