```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RSSI;
    float throughput;
    double latency;
} WIFI_NETTEST_STATS;

typedef struct {
    unsigned short CHANNEL_ID;
    unsigned char TX_POWER_LEVEL;
    WIFI_NETTEST_STATS stats;
} WIFI_NETTEST_CONFIG;

#define MAX_CONFIG 5000
#define FILE_SIZE_LIMIT (1 << 23) // 8MB
WIFI_NETTEST_CONFIG *configList = NULL;
size_t configCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *file = NULL;
clock_t lastUpdateTime = 0;
int batchSize = 0;

void wifiNtestConfigInit(unsigned short channel, unsigned char powerLevel) {
    if (configCount >= MAX_CONFIG) {
        // Prune old configurations to free up memory.
        configCount -= MAX_CONFIG / 3;
        memmove(configList, &configList[MAX_CONFIG / 10], sizeof(WIFI_NETTEST_CONFIG) * (MAX_CONFIG - MAX_CONFIG / 10));
    }

    if (!file || ftell(file) > FILE_SIZE_LIMIT) {
        // Close the old file and open a new one.
        fclose(file);
        file = fopen("wifiNtestConfig.bin", "wb");
        batchSize = 0;
    }

    clock_t currentTime = clock();
    if (currentTime - lastUpdateTime > CLOCKS_PER_SEC) {
        // Serialize the data to a binary file in batches for efficiency.
        fwrite(configList, sizeof(WIFI_NETTEST_CONFIG), batchSize, file);
        fflush(file);
        batchSize = 0;
    }

    WIFI_NETTEST_CONFIG newConfig = {
        .CHANNEL_ID = channel,
        .TX_POWER_LEVEL = powerLevel,
        .stats = {
            // Generate randomly generated values.
            .RSSI = rand(),
            .throughput = (float)rand() / RAND_MAX,
            .latency = (double)rand() / RAND_MAX
        }
    };

    pthread_mutex_lock(&lock);
    configList[configCount++] = newConfig;
    batchSize++;
    lastUpdateTime = currentTime;
    pthread_mutex_unlock(&lock);
}
```
This code uses a linked list structure to manage the configurations. However, this approach has several drawbacks: 
- Linked lists require more memory than arrays due to the overhead of pointers and the increased complexity of traversal.
- Linked lists are not cache friendly as array elements remain contiguous in memory, which can improve performance by reducing cache misses.

A better approach would be using a dynamically allocated array for managing configurations with sufficient size, which allows efficient insertion and retrieval operations while minimizing memory fragmentation. This approach also provides the flexibility of dynamic resizing the array as needed. However, care must be taken to handle thread safety effectively, such as protecting shared data structures with mutex locks or other synchronization mechanisms.
