["Here's a basic implementation of what you asked for in C++. Note that this is just a simple sketch, not complete code and it doesn't include the real implementation of all the requested functionalities. 

```cpp
#include <queue>
#include <mutex>
#include <condition_variable>
#include <random>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

class ConcurrentQueue {
public:
    explicit ConcurrentQueue(size_t capacity) : capacity_(capacity) {}

    void enqueue(NFAPI_CRC_INDICATION_PDU_T item);
    NFAPI_CRC_INDICATION_PDU_T dequeue();

    bool isFull() const;
    bool isEmpty() const;

private:
    mutable std::mutex mtx_;
    std::condition_variable notEmpty_, notFull_;
    std::deque<NFAPI_CRC_INDICATION_PDU_T> queue_;
    size_t capacity_;
};

void ConcurrentQueue::enqueue(NFAPI_CRC_INDICATION_PDU_T item) {
    std::unique_lock<std::mutex> lock(mtx_);

    notFull_.wait(lock, [this]() { return queue_.size() != capacity_; });

    // Set random CRCFLAG in the NFAPI_CRC_INDICATION_PDU_T structure
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);

    item.CRCFLAG = dis(gen) == 1;
    queue_.push_back(item);
}

NFAPI_CRC_INDICATION_PDU_T ConcurrentQueue::dequeue() {
    std::unique_lock<std::mutex> lock(mtx_);

    notEmpty_.wait(lock, [this]() { return !queue_.empty(); });

    auto item = queue_.front();
    queue_.pop_front();

    return item;
}

bool ConcurrentQueue::isFull() const {
    std::lock_guard<std::mutex> lock(mtx_);
    return queue_.size() == capacity_;
}

bool ConcurrentQueue::isEmpty() const {
    std::lock_guard<std::mutex> lock(mtx_);
    return queue_.empty();
}
```
