    if (!logBuf->buffer) {
        exit(-1);
    }

    logBuf->capacity = MAX_LOG_SIZE;
    logBuf->size = 0;
    pthread_mutex_init(&logBuf->mutex, NULL);
}

void freeLogBuffer(LogBuffer* logBuf) {
    if (logBuf && logBuf->buffer) {
        free(logBuf->buffer);
        logBuf->capacity = 0;
        logBuf->size = 0;
        pthread_mutex_destroy(&logBuf->mutex);
    }
}

void appendLogMessage(LogBuffer* logBuf, const char* format, ...) {
    if (!format) return;

    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&logBuf->mutex);

    size_t remaining = logBuf->capacity - logBuf->size;
    if (remaining > 0) {
        int written = vsnprintf(logBuf->buffer + logBuf->size, remaining, format, args);

        // Check for truncated output or other errors.
        if (written >= 0 && written < remaining) {
            logBuf->size += written;
        } else {
            logBuf->size = logBuf->capacity - 1;
        }
    }

    pthread_mutex_unlock(&logBuf->mutex);

    va_end(args);
}
