typedef struct cipher_context {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} cipher_context;

cipher_context* initialize_aes256cbc(const char *password) {
    cipher_context *ctx = malloc(sizeof(cipher_context));
    if (!ctx) return NULL;

    // Generate a 32-byte key from the password using SHA-512
    unsigned char shaResult[SHA512_DIGEST_LENGTH];
    SHA512((unsigned char*)password, strlen(password), shaResult);

    // Copy the first 32 bytes of the SHA result into key
    memcpy(ctx->key, shaResult, EVP_MAX_KEY_LENGTH);

    // Generate a random IV of length 16
    RAND_bytes(ctx->iv, EVP_MAX_IV_LENGTH);

    return ctx;
}
