#include <openssl/evp.h>
#include <zlib.h>
#include <time.h>

typedef struct {
    int tx_power_level;
    time_t timestamp;
} LTE_PHY_TEST_TX_PARAMS;

// Populate array with unique elements
void populateArray(LTE_PHY_TEST_TX_PARAMS *params, int length) {
    for (int i = 0; i < length; ++i) {
        params[i].tx_power_level = i + 1; // make them unique
        params[i].timestamp = time(NULL);
    }
}

// Compress with zlib
void compressData(char *data, int dataLength, char **compressedData, unsigned long *compressedLength) {
    *compressedLength = compressBound(dataLength);
    *compressedData = malloc(*compressedLength);

    if (compress2((Bytef*)*compressedData, compressedLength, (const Bytef*)data, dataLength, Z_BEST_COMPRESSION) != Z_OK) {
        fprintf(stderr, "Compression failed!\n");
        free(*compressedData);
        return;
    }
}

// Encrypt with AES-256-CBC using OpenSSL
void encryptAes(char *plaintext, int plaintextLength, char **ciphertext, int *ciphertextLength) {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH]; // 256 bits
    unsigned char iv[EVP_MAX_IV_LENGTH]; // 128 bits

    /* Generate a random key and IV. We'll use these for the encryption */
    RAND_bytes(key, EVP_MAX_KEY_LENGTH);
    RAND_bytes(iv, EVP_MAX_IV_LENGTH);

    *ciphertextLength = plaintextLength + (EVP_CIPHER_CTX_block_size(ctx) - 1); // Max ciphertext length is the same as input length
    *ciphertext = malloc(*ciphertextLength);

    /* Create and initialise the context */
    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    /* Initialise the encryption operation. IMPORTANT - ensure you use a key
     * and IV size appropriate for your cipher
     * In this example we are using 256 bit AES (i.e. a 256 bit key). The
     * IV size for *most* modes is the same as the block size. For AES this
     * is 128 bits */
    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) handleErrors();

    /* Provide the message to be encrypted, and obtain the encrypted output.
     * EVP_EncryptUpdate can be called multiple times if necessary */
    if(1 != EVP_EncryptUpdate(ctx, (unsigned char*)*ciphertext, &ciphertextLength, (const unsigned char*)plaintext, plaintextLength)) handleErrors();

    /* Finalise the encryption. Further ciphertext bytes may be written at
     * this stage. */
    if(1 != EVP_EncryptFinal_ex(ctx, (unsigned char*)*ciphertext + ciphertextLength, &ciphertextLength)) handleErrors();
}
```

