} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node *head;
    int size;
    pthread_mutex_t mutex;
} LinkedList;

void init(LinkedList* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int insert(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node *newNode = (Node*) malloc(sizeof(Node));

    if(newNode == NULL) 
        return -1;

    newNode->data = data;
    pthread_mutex_lock(&list->mutex);
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int delete(LinkedList* list, int index) {
    if(index < 0 || index >= list->size) 
        return -1;

    pthread_mutex_lock(&list->mutex);
    Node *temp = list->head;

    if (index == 0) {
        list->head = temp->next;
        free(temp);
        list->size--;
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }

    for (int i=0; temp != NULL && i<index - 1; i++)
         temp = temp->next;

    if(temp == NULL || temp->next == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    Node *next = temp->next->next;
    free(temp->next);
    temp->next = next; 
    list->size--;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}
```

Please note, this is a rudimentary version of linked list in C with no error handling. You should add more robust error checks and improve performance by using better data structures or algorithms for insertion/deletion based on specific requirements. Also, there's no logging mechanism here but you can add one yourself as per your requirement.
