#include <stdlib.h>
#include <glib.h> // This includes functions from GLib, such as GHashTable and GThread
#include <pthread.h>

typedef struct PHY_FRAME_INFO {
    int frameNumber;
    int subframeNumber;
} PHY_FRAME_INFO;

typedef struct SRS_CONFIG {
    int srsConfigIndex;
} SRS_CONFIG;

typedef struct LTE_PHY_RX_FRAME_INFO_T {
    PHY_FRAME_INFO *phyFrameInfo;
    SRS_CONFIG *srsConfig;
} LTE_PHY_RX_FRAME_INFO_T;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for thread safety.
static GHashTable* frameInfoTable;  // For efficient lookups and updates.
static int successCount = 0, failureCount = 0; // Counters for logging purposes.

void LTE_PHY_RX_FRAME_INFO_Init(int capacity) {
    frameInfoTable = g_hash_table_new(g_direct_hash, g_direct_equal); // Initializes the hash table.
    g_mutex_init(&lock);  // Initialize the lock.
}

void LTE_PHY_RX_FRAME_INFO_AddOrUpdate(int key, LTE_PHY_RX_FRAME_INFO_T *frameInfo) {
    pthread_mutex_lock(&lock);  // Acquire the lock to ensure thread safety.
    gpointer previous = g_hash_table_lookup(frameInfoTable, &key); // Look for an existing entry with this key.
    if (previous != NULL) { // If there's a previous entry...
        free(previous);  // ...free the memory.
        successCount++;   // Increment success count.
    } else { // If it was not found...
        failureCount++; // ...increment failure count.
    }
    g_hash_table_insert(frameInfoTable, &key, frameInfo);  // Add or update the entry.
    pthread_mutex_unlock(&lock); // Release the lock to allow other threads to access.
}
```
