        int attempts = 0;
        void* buffer = NULL;

        while ((buffer = aligned_alloc(16, BUFFER_SIZE)) == NULL && attempts < 3) {
            // Re-allocation if allocation fails due to insufficient memory
            free(arr);
            arr = malloc((max_size + (++attempts * 1024)) * sizeof(*arr));
        }

        if (!buffer) {
            // Allocation failed after re-allocation attempts, clean up and return NULL
            for (int j = 0; j < i; j++) {
