public class ConcurrentQueue<E> {
    private final ConcurrentLinkedQueue<E> queue = new ConcurrentLinkedQueue<>();

    public boolean add(E e) {
        return queue.add(e);
    }

    public boolean offer(E e) {
        return queue.offer(e);
    }

    public E remove() {
        return queue.remove();
    }

    public E poll() {
        return queue.poll();
    }
}
