```java
public class MemoryPoolManager {
    private final Object[] pool;

    public MemoryPoolManager(int size) {
        this.pool = new Object[size];
    }

    public synchronized void addObject(Object object, int position) {
        if (position >= pool.length || position < 0) 
            throw new IndexOutOfBoundsException("Position is out of bounds");

        this.pool[position] = object;
    }

    public synchronized Object getObject(int position) {
        if (position >= pool.length || position < 0) 
            throw new IndexOutOfBoundsException("Position is out of bounds");

        return this.pool[position];
    }
}
