#include <pthread.h>
#include <glib.h>
#include <stdlib.h>
#include <string.h>

typedef struct NFAPI_RX_FRAME_PDU {
    int RX_FRAME_TAG;
    int RNTI;
    int FRAME_TYPE;
    struct NFAPI_RX_FRAME_PDU* prev;
    struct NFAPI_RX_FRAME_PDU* next;
} NFAPI_RX_FRAME_PDU_T;

typedef struct {
    NFAPI_RX_FRAME_PDU_T* head;
    NFAPI_RX_FRAME_PDU_T* tail;
    pthread_mutex_t lock;
} LinkedList;

void initialize(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        g_error("Failed to initialize mutex");
        exit(EXIT_FAILURE);
    }
}

NFAPI_RX_FRAME_PDU_T* createNode(int RX_FRAME_TAG, int RNTI, int FRAME_TYPE) {
    NFAPI_RX_FRAME_PDU_T* newNode = (NFAPI_RX_FRAME_PDU_T*)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    if (newNode == NULL) {
        g_error("Failed to allocate memory");
        return NULL;
    }
    newNode->RX_FRAME_TAG = RX_FRAME_TAG;
    newNode->RNTI = RNTI;
    newNode->FRAME_TYPE = FRAME_TYPE;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void insert(LinkedList* list, NFAPI_RX_FRAME_PDU_T* node) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        NFAPI_RX_FRAME_PDU_T* curr = list->head;
        while(curr != NULL) {
            if (curr->RNTI == node->RNTI) {
                g_error("Duplicate RNTI detected");
                free(node);
                return;
            }
            curr = curr->next;
        }
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->lock);
}

void forwardTraversal(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_RX_FRAME_PDU_T* curr = list->head;
    while (curr != NULL) {
        // Perform operation on each node
        g_debug("Node with RNTI: %d", curr->RNTI);
        curr = curr->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void reverseTraversal(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_RX_FRAME_PDU_T* curr = list->tail;
    while (curr != NULL) {
        // Perform operation on each node
        g_debug("Node with RNTI: %d", curr->RNTI);
        curr = curr->prev;
    }
    pthread_mutex_unlock(&list->lock);
}
```
