typedef struct {
    int source_id;
    long timestamp;
    int log_level;
    char *message;
} LOG_RECORD;

// Global variables and mutex
LOG_RECORD* log_records = NULL;
size_t num_logs = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void process_log_record(int source_id, long timestamp, int log_level, char* message) {
    // Lock the mutex before accessing shared data
    pthread_mutex_lock(&lock);

    if (num_logs % 10 == 0 && num_logs != 0) {
        size_t new_size = sizeof(LOG_RECORD) * (num_logs + 10);
        LOG_RECORD* temp = realloc(log_records, new_size);
        if (temp == NULL) {
            log_error("Memory allocation failed.");
            pthread_mutex_unlock(&lock);  // Unlock the mutex before returning
            return;
        }
        log_records = temp;
    }

    LOG_RECORD new_record = {source_id, timestamp, log_level, strdup(message)};
    if (new_record.message == NULL) {
        log_error("Memory allocation failed.");
        pthread_mutex_unlock(&lock);  // Unlock the mutex before returning
        return;
    }

    log_records[num_logs++] = new_record;

    // Unlock the mutex after modifying shared data
    pthread_mutex_unlock(&lock);
}

void clear_log_records() {
    // Lock the mutex before accessing shared data
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < num_logs; ++i) {
        free(log_records[i].message);  // Free memory allocated by strdup
    }
    free(log_records);  // Free the array itself
    log_records = NULL;
    num_logs = 0;

    // Unlock the mutex after modifying shared data
    pthread_mutex_unlock(&lock);
}
```

