```c
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <libgen.h> // for basename() function
#include <getopt.h>
// Assuming some logging library has been included and initialized as 'logger'

void print_usage(char *program_name) {
    printf("Usage: %s [-c] [-s] [-o output_file] [--manpage] -l log_file file...\n", program_name);
}

int main(int argc, char **argv) {
    int c;
    FILE *out_file = stdout; // default to stdout
    char *log_file = NULL;
    int count_lines = 0, count_chars = 0;

    while ((c = getopt(argc, argv, "cosl:")) != -1) {
        switch (c) {
            case 'c':
                count_lines = 1;
                break;
            case 's':
                count_chars = 1;
                break;
            case 'o':
                out_file = fopen(optarg, "w");
                if (out_file == NULL) {
                    logger.logError("Can't open output file: %s", strerror(errno));
                    return 1;
                }
                break;
            case 'l':
                log_file = optarg;
                break;
        }
    }

    if (optind >= argc) {
        logger.logWarning("No input file provided");
        print_usage(basename(argv[0]));
        return 1;
    }

    // process each remaining argument as an input file
    for (; optind < argc; ++optind) {
        FILE *in_file = fopen(argv[optind], "r");

        if (in_file == NULL) {
            logger.logError("Can't open input file: %s", strerror(errno));
            continue; // try next file
        }

        int line_count = 0, char_count = 0;
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), in_file) != NULL) {
            ++line_count;
            if (strcmp(buffer, "\n") != 0) { // non-empty line
                ++char_count;
                char_count += strlen(buffer);
            }
        }

        fprintf(out_file, "File: %s\n", argv[optind]);
        if (count_lines)
            fprintf(out_file, "Line count: %d\n", line_count);
        if (count_chars)
            fprintf(out_file, "Character count: %d\n", char_count);

        // cleanup
