#include <pthread.h>
#include <stdlib.h>

typedef struct {
    unsigned int PDCP_SN;
    unsigned int PDCP_CTXT_ID;
    char* DATA;
} LTE_PDCP_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t length;
    LTE_PDCP_PDU_T *array;
} LTE_PDCP_Array;

void init(LTE_PDCP_Array* array, size_t initialCapacity) {
    pthread_mutex_init(&array->mutex, NULL);
    array->capacity = initialCapacity;
    array->length = 0;
    array->array = (LTE_PDCP_PDU_T*) malloc(initialCapacity * sizeof(LTE_PDCP_PDU_T));
}

void add(LTE_PDCP_Array* array, LTE_PDCP_PDU_T element) {
    pthread_mutex_lock(&array->mutex);

    if (array->length >= array->capacity) {
        // Double the capacity when full to reduce reallocations.
        array->capacity *= 2;
        LTE_PDCP_PDU_T* newArray = (LTE_PDCP_PDU_T*) realloc(array->array, array->capacity * sizeof(LTE_PDCP_PDU_T));

        if (!newArray) {
            // Reallocation failed. Release the lock and return.
            pthread_mutex_unlock(&array->mutex);
            return;
        }

        array->array = newArray;
    }

    array->array[array->length++] = element;
    pthread_mutex_unlock(&array->mutex);
}

void destroy(LTE_PDCP_Array* array) {
    for (size_t i = 0; i < array->length; ++i) {
        free(array->array[i].DATA);
    }

    pthread_mutex_destroy(&array->mutex);
    free(array->array);
}
```
