#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Define WEB_REQUEST structure
typedef struct {
    int USER_ID;
    char* URL;
    char* METHOD;
    time_t TIMESTAMP;
    int STATUS_CODE;
} WEB_REQUEST;

// Define node for binary tree
typedef struct TreeNode {
    WEB_REQUEST* request;
    struct TreeNode *left, *right;
} TreeNode;

TreeNode* newNode(WEB_REQUEST* req) {
    TreeNode* temp = (TreeNode*)malloc(sizeof(TreeNode));
    temp->request = req;
    temp->left = temp->right = NULL;
    return temp;
}

// Insert a new node with given request into the tree
TreeNode* insertRequest(TreeNode* root, WEB_REQUEST* req) {
    if (root == NULL) 
        return newNode(req);

    // Split based on USER_ID and TIMESTAMP combination.
    int split = req->USER_ID + req->TIMESTAMP;

    if (split < root->request->USER_ID + root->request->TIMESTAMP) 
        root->left  = insertRequest(root->left, req);
    else if (split > root->request->USER_ID + root->request->TIMESTAMP) 
        root->right = insertRequest(root->right, req);

    return root;
}

// Thread safe functions for tree operation. Use appropriate locks based on usage scenario.
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
void addToTreeThreadSafe(TreeNode** root, WEB_REQUEST* req) {
    pthread_mutex_lock(&lock);
    *root = insertRequest(*root, req);
    pthread_mutex_unlock(&lock);
}
```

