use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::net::IpAddr;
use reqwest::blocking::ClientBuilder;

pub struct HttpClient {
    client: Arc<Mutex<reqwest::blocking::Client>>,
}

impl HttpClient {
    pub fn new(disable_certificate_validation: bool) -> Self {
        let client = if disable_certificate_validation {
            ClientBuilder::new().danger_accept_invalid_certs(true).build().unwrap()
        } else {
            ClientBuilder::new().build().unwrap()
        };

        HttpClient {
            client: Arc::new(Mutex::new(client)),
        }
    }

    pub fn get(&self, url: &str) -> Result<reqwest::blocking::RequestBuilder, reqwest::Error> {
        let client = self.client.lock().unwrap();
        Ok(client.get(url))
    }
}
```
