void addPdu(int TAC, int RAC) {
    if (TAC < 0 || RAC < 0) {
        printf("Invalid input parameters.\n");
        return;
    }

    pthread_mutex_lock(&listLock); // Lock list for synchronization

    if(numPdus >= MAX_PDUS) {
        printf("Maximum number of PDUs reached.\n");
        pthread_mutex_unlock(&listLock); 
        return;
    }

    PDU_T *newPdu = (PDU_T *)malloc(sizeof(PDU_T));
