    fwrite(txParams, sizeof(WIFI_PHY_TEST_TX_PARAMS), numElements, file);

    // Write RX statistics to file.
    fwrite(rxStats, sizeof(WIFI_PHY_TEST_RX_STATS), numElements, file);

    if (ferror(file)) handleError("Failed writing data");

    fclose(file); // Close the file.
}

