#include <string.h>

typedef struct UserSession {
    char userId[50];
    time_t startTimestamp;
    time_t endTimestamp;
    enum Status{active, idle, terminated} connectionStatus;
} UserSession;

typedef struct Node {
    UserSession* session;
    struct Node *left;
    struct Node *right;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* root = NULL;
int totalSessions = 0;
double averageTimePerSession = 0.0;
void (*callback)(UserSession*) = NULL;
size_t maxSize; // adjustable at runtime
time_t lastValidationCheck;
const int validationInterval = 3600; // one hour in seconds
extern void* fetchAnalytics(char *userId); // dummy function for fetching analytics
extern void notifyUser(); // dummy function for notifying user

Node* newNode(UserSession* session) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->session = session;
    node->left = NULL;
    node->right = NULL;
    return(node);
}

Node* insertRecursive(Node* node, UserSession* session) {
    if (node == NULL) {
        return newNode(session);
    }

    if (strcmp(session->userId, node->session->userId) < 0) {
        node->left = insertRecursive(node->left, session);
    } else if (strcmp(session->userId, node->session->userId) > 0) {
        node->right = insertRecursive(node->right, session);
    }

    return node;
}

void addUserSession(UserSession* session) {
    pthread_mutex_lock(&lock); // start of critical section

    clock_t begin = clock();
    if (totalSessions >= maxSize) {
        free(session);
        pthread_mutex_unlock(&lock); // end of critical section
        return;
    }

    root = insertRecursive(root, session);
    totalSessions++;
    clock_t end = clock();

    averageTimePerSession = (averageTimePerSession + ((double)(end - begin) / CLOCKS_PER_SEC)) / 2.0;

    if(callback != NULL) {
        callback(session); // call the provided callback function
    }

    pthread_mutex_unlock(&lock); // end of critical section
}
```
