void addOrUpdateContext(UEContextManager *manager, LTE_UE_INFO_TAG ueInfo, PHY_RX_UE_CONTEXT phyContext) {
    pthread_mutex_lock(&(manager->mutex));

    int i;
    for (i = 0; i < manager->size; ++i) {
        if (manager->ue_info[i].ue_id == ueInfo.ue_id) {
            // Update existing context
            manager->phy_contexts[i] = phyContext;
            break;
        }
    }

    if (i >= manager->size) {
        // Add new context
        manager->size++;
        manager->ue_info = realloc(manager->ue_info, manager->size * sizeof(LTE_UE_INFO_TAG));
        manager->phy_contexts = realloc(manager->phy_contexts, manager->size * sizeof(PHY_RX_UE_CONTEXT));

        manager->ue_info[i] = ueInfo;
        manager->phy_contexts[i] = phyContext;
    }

    pthread_mutex_unlock(&(manager->mutex));
}

PHY_RX_UE_CONTEXT *getContextByUeId(UEContextManager *manager, int ue_id) {
    pthread_mutex_lock(&(manager->mutex));

    for (int i = 0; i < manager->size; ++i) {
        if (manager->ue_info[i].ue_id == ue_id) {
            pthread_mutex_unlock(&(manager->mutex));
            return &(manager->phy_contexts[i]);
        }
    }

    pthread_mutex_unlock(&(manager->mutex));
    return NULL;  // No UE context found with the given ID
}
