#include <chrono>
#include <unordered_map>
#include <mutex>
#include <shared_mutex>

struct USER_CONTEXT {
    int user_id;
    std::chrono::system_clock::time_point session_start_time;
    std::chrono::system_clock::time_point last_active_time;
};

class UserManager {
private:
    using MapType = std::unordered_map<int, USER_CONTEXT>;
    std::shared_timed_mutex mtx_;
    MapType users_;

public:
    void addUser(USER_CONTEXT user) {
        std::lock_guard<std::shared_timed_mutex> lock(mtx_);
        users_.insert({user.user_id, user});
    }

    void updateUser(int userId, USER_CONTEXT updatedInfo) {
        std::unique_lock<std::shared_timed_mutex> lock(mtx_);
        if (users_.find(userId) != users_.end()) {
            auto& user = users_[userId];
            user.session_start_time = updatedInfo.session_start_time;
            user.last_active_time = updatedInfo.last_active_time;
        }
    }

    USER_CONTEXT getUser(int userId) {
        std::shared_lock<std::shared_timed_mutex> lock(mtx_);
        return users_.find(userId)->second;
    }

    double totalActiveTime() {
        std::chrono::duration<double> totalDuration = std::chrono::seconds(0);
        std::shared_lock<std::shared_timed_mutex> lock(mtx_);
        for (const auto& user : users_) {
            totalDuration += user.second.last_active_time - user.second.session_start_time;
        }
        return totalDuration.count();
    }

    void expireSessions() {
        std::unique_lock<std::shared_timed_mutex> lock(mtx_);
        auto now = std::chrono::system_clock::now();
        for (auto it = users_.cbegin(), next_it = it; it != users_.cend(); it = next_it) {
            ++next_it;
            if ((now - it->second.last_active_time) > std::chrono::seconds(10)) { // expire sessions after 10 seconds inactivity
                users_.erase(it);
            }
        }
    }
};
```
