    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL; // Out of memory

    pthread_mutex_lock(&mutex);  // Lock for synchronization
    for (int i = 0, j = 1; i < count; ++i) {
        while(used[j]) { // Find an unused RNTI
            if (++j > 1000) j = 1; // Wrap around to start of array if necessary
