        free(node);
        return -2; // Out of memory
    }

    node->session->user_id = atomic_fetch_add(&nextID, 1); // Generate unique ID
    node->session->profile = profile; // Set user roles and permissions.
    // Initialize other fields...

    pthread_rwlock_wrlock(&list_lock); 
    node->next = list;
    list = node;
    pthread_rwlock_unlock(&list_lock); 

    return node->session->user_id;
}

// Function to get a session, returns SESSION_INFO or error code.
SESSION_INFO* getSession(uint32_t id) {
    pthread_rwlock_rdlock(&list_lock); 
    Node* node = list;
    while(node && node->session->user_id != id) 
        node = node->next; // Find the session in the linked list.

    if(!node) {
        pthread_rwlock_unlock(&list_lock); 
        return NULL; // Session not found.
    }

    atomic_fetch_add(&node->refcount, 1); // Increase reference count.
    pthread_mutex_lock(&node->lock); // Lock the node for concurrent access.

    SESSION_INFO* session = node->session;
    pthread_rwlock_unlock(&list_lock); 
    return session;
}

// Function to remove a session, returns an error code.
int32_t removeSession(uint32_t id) {
    pthread_rwlock_wrlock(&list_lock); 
    Node* node = list;
    while(node && node->session->user_id != id) 
        node = node->next; // Find the session in the linked list.

    if(!node) {
        pthread_rwlock_unlock(&list_lock); 
        return -1; // Session not found.
    }

    atomic_fetch_sub(&node->refcount, 1); // Decrease reference count.
    pthread_mutex_lock(&node->lock); // Lock the node for concurrent access.

    if(atomic_load(&node->refcount) > 0) {
        pthread_mutex_unlock(&node->lock); 
        pthread_rwlock_unlock(&list_lock); 
        return -2; // Session is still in use.
    }

    Node* prev = list;
    if(prev == node) { // Removing head of the list?
        list = node->next;
    } else {
        while(prev && prev->next != node) 
            prev = prev->next;

        if(!prev) {
            pthread_mutex_unlock(&node->lock); 
            pthread_rwlock_unlock(&list_lock); 
            return -3; // Could not find session in the list.
        }

        prev->next = node->next;
    }

    free(node->session); // Free memory of SESSION_INFO.
    pthread_mutex_unlock(&node->lock); 
    pthread_mutex_destroy(&node->lock); 
    free(node); // Free memory of Node.

    pthread_rwlock_unlock(&list_lock); 
    return 0; // Successfully removed session.
}
```
