import javax.xml.bind.DatatypeConverter;

public class SessionManager {
    private static final int MAX_SESSIONS = 100000;

    // Lock-free queue for session metadata
    private ConcurrentLinkedQueue<SessionMetadata> sessions = new ConcurrentLinkedQueue<>();

    // Locks for thread safety
    private ReentrantLock addLock = new ReentrantLock();
    private ReentrantLock removeLock = new ReentrantLock();

    public void processDataStream(Stream<SessionData> data) {
        data.parallel()
            .limit(MAX_SESSIONS)
            .forEach(session -> 
                addSession(new SessionMetadata(session)));
    }

    private void addSession(SessionMetadata session) {
        // Use ReentrantLock for thread-safe operation
        addLock.lock();
        try {
            sessions.add(session);
        } finally {
            addLock.unlock();
        }
    }

    public Optional<SessionMetadata> getSessionById(String id) {
        String hashId = generateMD5Hash(id);

        // Use ReentrantLock for thread-safe operation
        removeLock.lock();
        try {
            return sessions.stream()
                .filter(session -> session.getId().equals(hashId))
                .findFirst();
        } finally {
            removeLock.unlock();
        }
    }

    private String generateMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));
            return DatatypeConverter.printHexBinary(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
```

