NFAPI_CRC_INDICATION_PDU_T* initializeNfadecrypt(const char *passphrase, const EVP_CIPHER *cipher) {
    int keySize = EVP_CIPHER_key_length(cipher);
    unsigned char salt[8]; // Generate random salt
    RAND_bytes(salt, sizeof(salt));

    const EVP_MD *digest = EVP_sha256();
    const int iterations = 1000; // Arbitrary number of iterations for PBKDF2
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];

    /* Derive a key and IV from the passphrase */
    if (!PKCS5_PBKDF2_HMAC(passphrase, strlen(passphrase), salt, sizeof(salt), iterations, digest, keySize / 8, key)) {
        fprintf(stderr, "Error deriving key: %lu\n", ERR_get_error());
        return NULL; // Return NULL to indicate an error occurred.
    }

    /* Initialize the encryption context */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        fprintf(stderr, "Error initializing encryption: %lu\n", ERR_get_error());
        return NULL; // Return NULL to indicate an error occurred.
    }

    /* Allocate and populate NFAPI_CRC_INDICATION_PDU_T structures */
    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10); // Allocate memory for PDUs
    if (pduList == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL; // Return NULL to indicate an error occurred.
    }

    /* Populate the PDU structures */
