        pduList[i].RX_UE_INFORMATION_TAG = i;
        pduList[i].RNTI = i * 2;
        pduList[i].CRCFLAG = i % 2 == 0 ? 1 : 0; // Randomly set CRCFLAG.
    }

    return ctx;
}

void cleanup(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx); // Free the cipher context when it is no longer needed.
}
