["Here is a basic C implementation of a session pool manager using pthread mutexes for thread safety:

```c
#include <pthread.h>
#include <jansson.h>
#include <time.h>
#include <string.h>

typedef struct {
    char username[32];
    int session_id;
    time_t last_active_time;
    char auth_token[64];
    json_t *preferences;
} USER_SESSION_RECORD;

#define MAX_SESS 500
USER_SESSION_RECORD sessions[MAX_SESS];
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;
int current_sess = 0;
time_t timeout;

void create_session(char *username, char *auth_token, json_t *preferences) {
    pthread_mutex_lock(&session_lock);

    for (int i = 0; i < MAX_SESS; ++i) {
        if (sessions[i].last_active_time + timeout < time(NULL)) { // session is inactive
            strncpy(sessions[i].username, username, sizeof(sessions[i].username));
            sessions[i].session_id = current_sess++;
            sessions[i].auth_token = auth_token;
            sessions[i].preferences = preferences;
            sessions[i].last_active_time = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&session_lock);
}

void update_session(int session_id, json_t *preferences) {
    pthread_mutex_lock(&session_lock);

    for (int i = 0; i < MAX_SESS; ++i) {
        if (sessions[i].session_id == session_id) {
            sessions[i].last_active_time = time(NULL);
            json_decref(sessions[i].preferences); // free old preferences before setting new ones
            sessions[i].preferences = preferences; 
        }
    }

    pthread_mutex_unlock(&session_lock);
}

void invalidate_session(int session_id) {
    pthread_mutex_lock(&session_lock);

    for (int i = 0; i < MAX_SESS; ++i) {
        if (sessions[i].session_id == session_id) {
            sessions[i].last_active_time = time(NULL) - timeout - 1; // move session into inactive state
        }
    }

    pthread_mutex_unlock(&session_lock);
}

char *serialize_json(json_t *obj){
    return json_dumps(obj, JSON_INDENT(2)); 
}

json_t* deserialize_json(const char *str){
    json_error_t error;
    json_t *root = json_loads(str, 0, &error);

    return root;
}
```
Please note that this is a basic implementation and does not cover all aspects of your requirements. It does include thread safety for session manipulation (`create_session`, `update_session`, `invalidate_session`), serialization and deserialization for JSON preferences, as well as invalidating sessions after a specified timeout period. However, it doesn't include efficient memory management of sessions or handling multiple simultaneous requests per second under heavy load conditions. 

Also remember to add error checking code in the functions above that are omitted here for simplicity.
