typedef struct {
    /* Fields related to TCP connection */
} TCP_CONNECTION_RECORD;

TCP_CONNECTION_RECORD *connectionPool = NULL;
int currentSize = 0;
int maxSize = 0;
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread safety

void resizeConnectionPool() {
    int loadFactor = (currentSize * 100) / maxSize;

    if(loadFactor > MAX_LOAD){
        pthread_mutex_lock(&poolMutex);  

        // Double the size of the connection pool
        TCP_CONNECTION_RECORD *temp = realloc(connectionPool, currentSize * RESIZE_FACTOR * sizeof(TCP_CONNECTION_RECORD)); 

        if (temp) {
            maxSize = currentSize * RESIZE_FACTOR;
            connectionPool = temp;
            printf("Connection pool resized to %d\n", maxSize);
        } else {
            printf("Failed to resize connection pool\n");
        }   

        pthread_mutex_unlock(&poolMutex);  
    }
}
