  // If we have a memory block available in the pool, use it.
  if (memPool != NULL) {
    MemBlockNode *oldHead = memPool;
    memPool = oldHead->next;

    result = oldHead->mem_block;
    free(oldHead);
    ++allocatedCount;
  } else { // Otherwise, allocate new memory.
