public class FileSummary {
    public static void main(String[] args) throws IOException {
        Path dir = Paths.get("/path/to/directory");

        try (Stream<Path> paths = Files.walk(dir)) {
            List<FileInfo> fileInfos = paths
                    .filter(Files::isRegularFile)
                    .map(file -> getFileInfo(dir, file))
                    .collect(Collectors.toList());

            // For CSV output:
            String csvOutput = toCSV(fileInfos);
            System.out.println(csvOutput);

            // For JSON output:
            String jsonOutput = toJSON(fileInfos);
            System.out.println(jsonOutput);
        } catch (IOException e) {
            System.err.println("An error occurred while processing the directory: " + e.getMessage());
        }
    }

    private static FileInfo getFileInfo(Path dir, Path file) {
        try {
            long size = Files.size(file);
            String checksum = calcChecksum(Files.readAllBytes(file));

            return new FileInfo(dir.relativize(file).toString(), size, checksum);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to read file " + file, e);
        }
    }

    private static String calcChecksum(byte[] bytes) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(bytes);

            return bytesToHex(hashBytes);
        } catch (Exception e) {
            throw new RuntimeException("Failed to calculate checksum", e);
        }
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();

        for (byte b : hash) {
            String hex = Integer.toHexString(0xFF & b);

            if (hex.length() == 1) {
                hexString.append('0');
            }

            hexString.append(hex);
        }

        return hexString.toString();
    }

