    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate(int count) {
    openlog("allocator", LOG_NDELAY | LOG_PID, LOG_USER);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (array == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        pthread_mutex_lock(&mutex); // acquire lock before accessing shared data

        array[i].RNTI = i + 1;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // for example a simple pattern derived from RNTI value

        pthread_mutex_unlock(&mutex); // release lock after accessing shared data
    }

    syslog(LOG_INFO, "Successfully allocated and populated array of size %d", count);
    closelog();

    return array;
}
