NRCellConfig* createNRCellConfig(int n) {
    if (n <= 0) {
        fprintf(stderr, "Invalid input value for N.\n");
        return NULL;
    }

    NRCellConfig *head = NULL, *prev = NULL, *curr = NULL;
    int i = 0;
    for (i=0; i<n; i++) {
        curr = malloc(sizeof(NRCellConfig));
        if (!curr) {
            fprintf(stderr, "Memory allocation failed.\n");
            // Clean up allocated memory and return NULL in case of failure
            cleanupList(head); 
            return NULL; 
