        curr->cellId = i + 1; // Set cell id to sequence number. You may set it to anything as per requirement
        curr->band = 0; // set band, carrierFrequency and rsPower based on your requirements
        curr->carrierFrequency = 0;
        curr->rsPower = 0;

        if (prev) {
            prev->next = curr;
            curr->previous = prev;
        } else {
            head = curr;
        }
        prev = curr; // Move the previous node pointer to current node.
    }
    printf("Successfully allocated %d elements.\n", n);
    return head;
}

void cleanupList(NRCellConfig* head) {
    NRCellConfig *nextNode = NULL;
    while (head) {
        nextNode = head->next;
        free(head);
        head = nextNode;
    }
}
