NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate(int num_threads) {
    if (num_threads > NFAPI_CRC_INDICATION_PDU_T_SIZE) return NULL; // Exceed system resources

    pthread_mutex_lock(&mutex); 

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_threads * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
