#include <sys/stat.h>
#include <fcntl.h>
#include <libgen.h>

#define MAX_FILENAME_LEN 255
#define MAX_EXTENSION_LEN 8

char* modifyExtension(const char *input) {
    // Extract original extension, ignore trailing dots
    const char *ext = strrchr(input, '.');
    if (!ext) return NULL;

    ext++;

    int len_original = (int)strlen(input);
    int len_extension = (int)strlen(ext);

    // Determine number of digits to append to the extension
    int numDigits = len_original - 5 > 10 ? 10 : len_original - 5;

    char *output = malloc(MAX_FILENAME_LEN + 1);
    if (!output) return NULL;

    // Join the filename prefix, new extension, and original file's extension
    snprintf(output, MAX_FILENAME_LEN, "%.*s.%0*d", len_original - len_extension - numDigits, input, numDigits, rand());

    int outputLen = (int)strlen(output);
    if (outputLen > MAX_EXTENSION_LEN) {
        // Truncate the new extension to 8 characters
        memcpy(&output[MAX_EXTENSION_LEN - len_extension], ext, len_extension + 1);
    }

    return output;
}
```
This function will generate a modified filename based on your rules. However, it does not handle cases where the filename is too long or contains invalid characters, nor does it account for edge cases in naming like filenames starting with a dash (-) or containing multiple dots (.) within the name.

