typedef struct {
    pthread_mutex_t lock;
    unsigned int size;
    unsigned int capacity;
    NFAPI_CRC_INDICATION_PDU_T* array;
} DynamicArray;

void initialize(DynamicArray *arr) {
    arr->capacity = 1024;  // Start with a small, efficient size.
    arr->size = 0;
    arr->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*arr->capacity);

    if (pthread_mutex_init(&arr->lock, NULL) != 0) {
        perror("Failed to initialize mutex\n");
        exit(-1);
    }
}

void reinitialize(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);  // Ensure no other thread is using this array.
    free(arr->array);
    initialize(arr);
    pthread_mutex_unlock(&arr->lock);
}

void clear(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);  // Ensure no other thread is using this array.
    arr->size = 0;
    pthread_mutex_unlock(&arr->lock);
}

void resize(DynamicArray *arr, unsigned int newCapacity) {
    NFAPI_CRC_INDICATION_PDU_T* newArray = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*newCapacity);

    if (newArray == NULL) {
        perror("Failed to allocate memory\n");
        exit(-1);  // Signal an error has occurred.
    }

    pthread_mutex_lock(&arr->lock);  // Ensure no other thread is using this array.
    memcpy(newArray, arr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T)*arr->size);
    free(arr->array);

    arr->capacity = newCapacity;
    arr->array = newArray;
    pthread_mutex_unlock(&arr->lock);
}

