typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node *head = NULL;  // head of the linked list
pthread_rwlock_t lock;  // reader/writer lock for thread-safety
FILE *logFile = NULL;  // log file handle

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failure.\n");
        return;
    }

    pthread_rwlock_wrlock(&lock);  // acquire writer lock for safety

    Node *current;
    /* insertion sort based on RNTI */
    if (head == NULL || head->data.RNTI >= newNode->data.RNTI) {
        newNode->next = head;
        head = newNode;
    } else {
        current = head;
        while (current->next != NULL && 
               current->next->data.RNTI < newNode->data.RNTI) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }

    pthread_rwlock_unlock(&lock);  // release lock after completion
}

void update(uint16_t RNTI, bool CRCFLAG) {
    Node *current = head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            current->data.CRC_INDICATION_REL8_TAG = CRCFLAG;
            fprintf(logFile, "Updated RNTI: %hu with CRCFLAG: %s\n", 
                    RNTI, CRCFLAG ? "True" : "False");
        }
        current = current->next;
    }
}

int main() {
    pthread_rwlock_init(&lock, NULL);
    logFile = fopen("log.txt", "w");

    // create threads and perform operations here...

    fclose(logFile);
    pthread_rwlock_destroy(&lock);
}
```
