    LTE_PDCP_STATS_T *node = malloc(sizeof(LTE_PDCP_STATS_T));

    if (node == NULL) {
        // Handle memory allocation failure.
    }

    node->SRC_RNTI = src;
    node->DST_RNTI = dst;
    node->PDCP_SN  = pdcpSn;

    return node;
}

void addElement(uint32_t src, uint32_t dst, uint32_t pdcpSn){
    LTE_PDCP_STATS_T *node = createElement(src, dst, pdcpSn);

    pthread_mutex_lock(&lock);
    tree = insertNode(tree, node, compare);
    pthread_mutex_unlock(&lock);
}

void removeElementsBySrcRnti(uint32_t src){
    LTE_PDCP_STATS_T node;
    node.SRC_RNTI = src;

    pthread_mutex_lock(&lock);
    tree = deleteNode(tree, &node, compare);
    pthread_mutex_unlock(&lock);
}

void removeElementsByDstRnti(uint32_t dst){
    LTE_PDCP_STATS_T node;
    node.DST_RNTI = dst;

    pthread_mutex_lock(&lock);
    tree = deleteNode(tree, &node, compare);
    pthread_mutex_unlock(&lock);
}

void updatePdcpSnByPair(uint32_t src, uint32_t dst, uint32_t newPdcpSn){
    LTE_PDCP_STATS_T node;
    node.SRC_RNTI = src;
    node.DST_RNTI = dst;

    pthread_mutex_lock(&lock);
    AVLTree* tempNode = search(tree, &node, compare);
    if (tempNode != NULL) {
        ((LTE_PDCP_STATS_T*)tempNode->data)->PDCP_SN = newPdcpSn;
    }
    pthread_mutex_unlock(&lock);
}
```
The actual implementation of AVL Tree operations and other functions would be beyond the scope of this platform. The above code is a demonstration on how to approach such problem by using an AVL tree (a self-balancing binary search tree) for efficient ordered insertion, deletion, and update. Please note that memory deallocation for elements in AVL Tree nodes needs to be handled separately as per your requirement of use case.
